def get_setting(key, default=None):
    try:
        sb = get_supabase()
        data = sb.table("impostazioni_kreo").select("*").eq("chiave", key).limit(1).execute().data
        if data:
            return data[0].get("valore")
    except Exception:
        pass
    return default


def set_setting(key, value, descrizione=""):
    sb = get_supabase()
    existing = sb.table("impostazioni_kreo").select("*").eq("chiave", key).limit(1).execute().data
    payload = {
        "chiave": key,
        "valore": str(value),
        "descrizione": descrizione,
        "updated_at": now_iso(),
        "updated_by": user_label(),
    }
    if existing:
        sb.table("impostazioni_kreo").update(payload).eq("chiave", key).execute()
    else:
        payload["created_at"] = now_iso()
        sb.table("impostazioni_kreo").insert(payload).execute()


def get_kreo_settings():
    return {
        "apertura": get_setting("orario_apertura", "07:30"),
        "chiusura": get_setting("orario_chiusura", "20:00"),
        "trainer_default": get_setting("trainer_default", "Vincenzo Crinisio"),
        "lezioni_settimanali_default": int(get_setting("lezioni_settimanali_default", "3") or 3),
        "durata_slot_pt_minuti": int(get_setting("durata_slot_pt_minuti", "60") or 60),
        "max_posti_luxury": int(get_setting("max_posti_luxury", "1") or 1),
        "max_posti_gold": int(get_setting("max_posti_gold", "2") or 2),
        "max_posti_vip": int(get_setting("max_posti_vip", "3") or 3),
        "max_posti_coaching": int(get_setting("max_posti_coaching", "20") or 20),
    }


def pacchetto_tipo(pacchetto):
    p = (pacchetto or "").upper()
    if "LUXURY" in p or "ONE TO ONE" in p:
        return "LUXURY"
    if "GOLD" in p or "TWO TO ONE" in p:
        return "GOLD"
    if "VIP" in p or "THREE TO ONE" in p:
        return "VIP"
    if "COACHING" in p:
        return "COACHING"
    return "ALTRO"


def max_posti_per_pacchetto(pacchetto):
    s = get_kreo_settings()
    tipo = pacchetto_tipo(pacchetto)
    if tipo == "LUXURY":
        return s["max_posti_luxury"]
    if tipo == "GOLD":
        return s["max_posti_gold"]
    if tipo == "VIP":
        return s["max_posti_vip"]
    if tipo == "COACHING":
        return s["max_posti_coaching"]
    return 1


def tipo_slot_per_pacchetto(pacchetto):
    tipo = pacchetto_tipo(pacchetto)
    if tipo == "LUXURY":
        return "ONE TO ONE"
    if tipo == "GOLD":
        return "TWO TO ONE"
    if tipo == "VIP":
        return "THREE TO ONE"
    if tipo == "COACHING":
        return "COACHING IN SEDE"
    return "GRUPPO / ALTRO"


def trainer_per_pacchetto(pacchetto):
    tipo = pacchetto_tipo(pacchetto)
    if tipo == "COACHING":
        return "Libero utilizzo attrezzi"
    return get_kreo_settings()["trainer_default"]


def start_of_week(d):
    if not isinstance(d, date):
        d = parse_date(d, date.today())
    return d - timedelta(days=d.weekday())


def count_prenotazioni_settimana(cliente_id, target_date):
    try:
        lez_df = load_lezioni()
    except Exception:
        return 0
    if lez_df.empty:
        return 0
    start = pd.Timestamp(start_of_week(target_date))
    end = start + pd.Timedelta(days=7)
    tmp = lez_df.copy()
    tmp["data_dt"] = pd.to_datetime(tmp["data_lezione"], errors="coerce")
    tmp = tmp[
        (tmp["cliente_id"].astype(int) == int(cliente_id)) &
        (tmp["data_dt"] >= start) &
        (tmp["data_dt"] < end) &
        (~tmp["stato"].isin(["ANNULLATO"]))
    ]
    return len(tmp)



def is_pacchetto_standard_settimanale(pacchetto):
    tipo = pacchetto_tipo(pacchetto)
    return tipo in ["LUXURY", "GOLD", "VIP", "COACHING"]


def get_accessi_settimanali_cliente(cliente):
    pacchetto = cliente.get("pacchetto", "")
    if is_pacchetto_standard_settimanale(pacchetto):
        return get_kreo_settings()["lezioni_settimanali_default"]
    # Pacchetto personalizzato: usa numero lezioni impostato manualmente
    return int(cliente.get("numero_lezioni") or 0)


def accessi_usati_settimana(cliente_id, target_date=None):
    target_date = target_date or date.today()
    return count_prenotazioni_settimana(cliente_id, target_date)


def accessi_residui_settimana(cliente):
    max_accessi = get_accessi_settimanali_cliente(cliente)
    usati = accessi_usati_settimana(int(cliente.get("id")), date.today())
    return max(max_accessi - usati, 0), usati, max_accessi


def mesi_tra(start_date, end_date):
    if not start_date or not end_date:
        return 0
    return (end_date.year - start_date.year) * 12 + (end_date.month - start_date.month)


def get_numero_rate_annuali(tipologia):
    t = (tipologia or "").upper()
    if "MENSILE" in t:
        return 12
    if "TRIMESTRALE" in t:
        return 4
    if "SEMESTRALE" in t:
        return 2
    if "ANNUALE" in t or "UNICA" in t:
        return 1
    return 1


def get_mesi_per_rata(tipologia):
    rate = get_numero_rate_annuali(tipologia)
    return max(int(12 / rate), 1)


def calcola_situazione_rate(cliente, data_riferimento=None):
    """
    Logica semplice:
    - importo = valore contratto/periodo
    - tipologia pagamento mensile => 12 rate
    - trimestrale => 4 rate
    - semestrale => 2 rate
    - annuale/unica => 1 rata
    - calcola quanto doveva essere pagato fino alla data odierna
    """
    data_riferimento = data_riferimento or date.today()
    importo = float(cliente.get("importo") or 0)
    pagato = float(cliente.get("importo_pagato") or 0)
    tipologia = cliente.get("tipologia_pagamento", "")
    inizio = parse_date(cliente.get("data_inizio_pacchetto") or cliente.get("data_iscrizione"), data_riferimento)

    numero_rate = get_numero_rate_annuali(tipologia)
    mesi_per_rata = get_mesi_per_rata(tipologia)
    rata = importo / numero_rate if numero_rate else importo

    mesi_passati = max(mesi_tra(inizio, data_riferimento), 0)
    rate_dovute = min((mesi_passati // mesi_per_rata) + 1, numero_rate)
    dovuto_oggi = rata * rate_dovute
    scoperto_rate = max(dovuto_oggi - pagato, 0)
    residuo_totale = max(importo - pagato, 0)

    prossima_rata_num = min(rate_dovute + 1, numero_rate)
    prossima_scadenza = add_months(inizio, mesi_per_rata * (prossima_rata_num - 1)) if prossima_rata_num <= numero_rate else None

    return {
        "importo": importo,
        "pagato": pagato,
        "numero_rate": numero_rate,
        "rata": rata,
        "rate_dovute": rate_dovute,
        "dovuto_oggi": dovuto_oggi,
        "scoperto_rate": scoperto_rate,
        "residuo_totale": residuo_totale,
        "prossima_scadenza": prossima_scadenza,
    }


def cliente_in_regola_pagamenti(cliente):
    situazione = calcola_situazione_rate(cliente)
    if situazione["scoperto_rate"] > 0:
        return False, f"Rata non coperta: risultano da pagare {euro(situazione['scoperto_rate'])} rispetto al dovuto alla data di oggi."
    return True, "Pagamenti/rate in regola alla data di oggi."


def cliente_puo_prenotare_settimana(cliente_id, target_date):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato."
    max_sett = get_accessi_settimanali_cliente(cliente)
    usate_sett = count_prenotazioni_settimana(cliente_id, target_date)
    if max_sett <= 0:
        return False, "Nessun accesso/lezione disponibile: pacchetto personalizzato da configurare lato staff."
    if usate_sett >= max_sett:
        return False, f"Limite settimanale raggiunto: {usate_sett}/{max_sett} prenotazioni già presenti in questa settimana."
    return True, f"Disponibili ancora {max_sett - usate_sett} prenotazioni questa settimana."

def genera_slot_giornalieri(data_slot, tipo_slot, trainer, max_posti):
    # Genera slot da 1 ora dalle 07:30 alle 20:00 per PT; per coaching crea blocco unico giornaliero.
    s = get_kreo_settings()
    apertura = s["apertura"]
    chiusura = s["chiusura"]
    sb = get_supabase()

    if tipo_slot == "COACHING IN SEDE":
        ok, msg = create_slot_disponibilita(data_slot, apertura, chiusura, "Libero utilizzo attrezzi", tipo_slot, max_posti, "Slot coaching in sede generato da impostazioni KREO")
        return 1, "Creato slot unico coaching in sede."

    start_h, start_m = map(int, apertura.split(":"))
    end_h, end_m = map(int, chiusura.split(":"))
    current = datetime.combine(data_slot, datetime.min.time()).replace(hour=start_h, minute=start_m)
    end_dt = datetime.combine(data_slot, datetime.min.time()).replace(hour=end_h, minute=end_m)
    durata = s["durata_slot_pt_minuti"]

    created = 0
    while current + timedelta(minutes=durata) <= end_dt:
        start_str = current.strftime("%H:%M")
        end_str = (current + timedelta(minutes=durata)).strftime("%H:%M")
        # Evita duplicati identici
        existing = sb.table("disponibilita_calendario").select("*").eq("data_slot", str(data_slot)).eq("ora_inizio", start_str).eq("trainer", trainer).eq("tipo_slot", tipo_slot).execute().data
        if not existing:
            create_slot_disponibilita(data_slot, start_str, end_str, trainer, tipo_slot, max_posti, "Slot generato automaticamente da impostazioni KREO")
            created += 1
        current += timedelta(minutes=durata)

    return created, f"Creati {created} slot da {durata} minuti."


def genera_slot_fascia_oraria(data_slot, ora_da, ora_a, tipo_slot, trainer, max_posti, modalita="slot_automatici"):
    """
    modalita:
    - slot_automatici: divide la fascia in slot secondo durata_slot_pt_minuti
    - blocco_unico: crea un unico slot dalla ora_da alla ora_a
    """
    s = get_kreo_settings()
    durata = s["durata_slot_pt_minuti"]
    sb = get_supabase()

    ora_da_str = ora_da.strftime("%H:%M") if hasattr(ora_da, "strftime") else str(ora_da)[:5]
    ora_a_str = ora_a.strftime("%H:%M") if hasattr(ora_a, "strftime") else str(ora_a)[:5]

    start_h, start_m = map(int, ora_da_str.split(":"))
    end_h, end_m = map(int, ora_a_str.split(":"))

    current = datetime.combine(data_slot, datetime.min.time()).replace(hour=start_h, minute=start_m)
    end_dt = datetime.combine(data_slot, datetime.min.time()).replace(hour=end_h, minute=end_m)

    if end_dt <= current:
        return 0, "L'orario finale deve essere successivo all'orario iniziale."

    # Coaching: di default crea blocco unico per la fascia scelta
    if tipo_slot == "COACHING IN SEDE" or modalita == "blocco_unico":
        existing = sb.table("disponibilita_calendario").select("*").eq("data_slot", str(data_slot)).eq("ora_inizio", ora_da_str).eq("ora_fine", ora_a_str).eq("trainer", trainer).eq("tipo_slot", tipo_slot).execute().data
        if existing:
            return 0, "Slot già presente per questa fascia."
        create_slot_disponibilita(data_slot, ora_da_str, ora_a_str, trainer, tipo_slot, max_posti, "Slot creato manualmente per fascia oraria")
        return 1, f"Creato 1 slot dalle {ora_da_str} alle {ora_a_str}."

    created = 0
    while current + timedelta(minutes=durata) <= end_dt:
        start_str = current.strftime("%H:%M")
        end_str = (current + timedelta(minutes=durata)).strftime("%H:%M")
        existing = sb.table("disponibilita_calendario").select("*").eq("data_slot", str(data_slot)).eq("ora_inizio", start_str).eq("trainer", trainer).eq("tipo_slot", tipo_slot).execute().data
        if not existing:
            create_slot_disponibilita(data_slot, start_str, end_str, trainer, tipo_slot, max_posti, f"Slot generato per fascia oraria {ora_da_str}-{ora_a_str}")
            created += 1
        current += timedelta(minutes=durata)

    return created, f"Creati {created} slot nella fascia {ora_da_str}-{ora_a_str}."




def week_dates_from_monday(start_date):
    start = start_of_week(start_date)
    return [start + timedelta(days=i) for i in range(7)]


def generate_time_slots_for_day():
    s = get_kreo_settings()
    apertura = s["apertura"]
    chiusura = s["chiusura"]
    durata = s["durata_slot_pt_minuti"]

    start_h, start_m = map(int, apertura.split(":"))
    end_h, end_m = map(int, chiusura.split(":"))

    today_base = date.today()
    current = datetime.combine(today_base, datetime.min.time()).replace(hour=start_h, minute=start_m)
    end_dt = datetime.combine(today_base, datetime.min.time()).replace(hour=end_h, minute=end_m)

    slots = []
    while current + timedelta(minutes=durata) <= end_dt:
        start_str = current.strftime("%H:%M")
        end_str = (current + timedelta(minutes=durata)).strftime("%H:%M")
        slots.append((start_str, end_str))
        current += timedelta(minutes=durata)

    return slots


def get_slot_for_cell(data_slot, ora_inizio, tipo_slot=None):
    try:
        slots = load_disponibilita()
    except Exception:
        return pd.DataFrame()
    if slots.empty:
        return slots

    mask = (
        (slots["data_slot"].astype(str) == str(data_slot)) &
        (slots["ora_inizio"].astype(str).str[:5] == str(ora_inizio)[:5]) &
        (slots["attivo"] == True)
    )
    if tipo_slot:
        mask &= (slots["tipo_slot"].astype(str) == tipo_slot)
    return slots[mask]


def cell_status_html(data_slot, ora_inizio):
    existing = get_slot_for_cell(data_slot, ora_inizio)
    if existing.empty:
        return '<div style="font-size:12px;opacity:.45;text-align:center;padding-top:18px;">Libero</div>'

    parts = []
    for _, s in existing.iterrows():
        occ = posti_occupati_slot(int(s["id"]))
        maxp = int(s.get("max_posti") or 1)
        tipo = s.get("tipo_slot", "")
        if tipo == "COACHING IN SEDE":
            color = "#dbeafe"; border = "#2563eb"; label = "Coaching"
        elif tipo == "ONE TO ONE":
            color = "#ecfdf5"; border = "#10b981"; label = "Luxury"
        elif tipo == "TWO TO ONE":
            color = "#fff7ed"; border = "#f97316"; label = "Gold"
        elif tipo == "THREE TO ONE":
            color = "#f5f3ff"; border = "#7c3aed"; label = "VIP"
        else:
            color = "#f8fafc"; border = "#64748b"; label = tipo

        parts.append(
            f'<div style="background:{color};border-left:4px solid {border};padding:5px 7px;border-radius:9px;margin:3px 0;font-size:11px;font-weight:800;">{label}<br>{occ}/{maxp}</div>'
        )
    return "".join(parts)


def create_slot_from_planner(data_slot, ora_inizio, ora_fine, tipo_slot):
    s = get_kreo_settings()

    if tipo_slot == "COACHING IN SEDE":
        trainer = "Libero utilizzo attrezzi"
        max_posti = s["max_posti_coaching"]
    elif tipo_slot == "ONE TO ONE":
        trainer = s["trainer_default"]
        max_posti = s["max_posti_luxury"]
    elif tipo_slot == "TWO TO ONE":
        trainer = s["trainer_default"]
        max_posti = s["max_posti_gold"]
    elif tipo_slot == "THREE TO ONE":
        trainer = s["trainer_default"]
        max_posti = s["max_posti_vip"]
    else:
        trainer = s["trainer_default"]
        max_posti = 1

    existing = get_slot_for_cell(data_slot, ora_inizio, tipo_slot)
    if not existing.empty:
        return False, "Questo slot/tipologia è già presente."

    ok, msg = create_slot_disponibilita(
        data_slot,
        ora_inizio,
        ora_fine,
        trainer,
        tipo_slot,
        max_posti,
        "Creato da planner settimanale"
    )
    return ok, msg



def calendar_color_for_type(tipo, stato=None):
    stato = (stato or "").upper()
    tipo = (tipo or "").upper()

    if "RICHIESTA" in stato:
        return "#f97316"  # arancione
    if "PRESENTE" in stato:
        return "#10b981"  # verde
    if "ANNULLATO" in stato or "ASSENTE" in stato:
        return "#ef4444"  # rosso

    if "COACHING" in tipo:
        return "#2563eb"  # blu
    if "ONE TO ONE" in tipo or "LUXURY" in tipo:
        return "#d4af37"  # oro
    if "TWO TO ONE" in tipo or "GOLD" in tipo:
        return "#0ea5e9"  # azzurro
    if "THREE TO ONE" in tipo or "VIP" in tipo:
        return "#7c3aed"  # viola

    return "#64748b"


def build_premium_calendar_events():
    events = []

    try:
        slots = load_disponibilita()
    except Exception:
        slots = pd.DataFrame()

    try:
        lez = load_lezioni()
    except Exception:
        lez = pd.DataFrame()

    # Occupazione per slot e nomi clienti
    clienti_map = {}
    try:
        clienti_df = load_clienti()
        if not clienti_df.empty:
            for _, c in clienti_df.iterrows():
                clienti_map[int(c["id"])] = f"{c.get('nome','')} {c.get('cognome','')}".strip()
    except Exception:
        clienti_map = {}

    pren_by_slot = {}
    if not lez.empty and "slot_id" in lez.columns:
        lez_valid = lez[~lez["stato"].isin(["ANNULLATO"])].copy()
        for _, r in lez_valid.iterrows():
            sid = r.get("slot_id")
            if pd.isna(sid):
                continue
            sid = int(sid)
            pren_by_slot.setdefault(sid, []).append(r.to_dict())

    if not slots.empty:
        for _, s in slots.iterrows():
            try:
                sid = int(s["id"])
                data_slot = str(s.get("data_slot"))
                start = str(s.get("ora_inizio"))[:5]
                end = str(s.get("ora_fine"))[:5]
                tipo = s.get("tipo_slot", "")
                trainer = s.get("trainer", "")
                maxp = int(s.get("max_posti") or 1)
                pren = pren_by_slot.get(sid, [])
                occ = len(pren)
                liberi = max(maxp - occ, 0)
                title = f"{tipo} · {occ}/{maxp}"
                if trainer:
                    title += f" · {trainer}"

                color = calendar_color_for_type(tipo, "PIENO" if liberi <= 0 else "")

                events.append({
                    "id": f"slot-{sid}",
                    "title": title,
                    "start": f"{data_slot}T{start}:00",
                    "end": f"{data_slot}T{end}:00",
                    "backgroundColor": color,
                    "borderColor": color,
                    "extendedProps": {
                        "kind": "slot",
                        "slot_id": sid,
                        "tipo": tipo,
                        "trainer": trainer,
                        "posti": f"{occ}/{maxp}",
                        "clienti": ", ".join([clienti_map.get(int(p.get("cliente_id")), "Cliente") for p in pren if p.get("cliente_id")]),
                    }
                })
            except Exception:
                continue

    # Lezioni senza slot_id, così non si perdono prenotazioni manuali vecchie
    if not lez.empty:
        for _, r in lez.iterrows():
            try:
                if "slot_id" in r and not pd.isna(r.get("slot_id")):
                    continue
                lid = int(r["id"])
                data_l = str(r.get("data_lezione"))
                start = str(r.get("ora_inizio"))[:5]
                end = str(r.get("ora_fine"))[:5]
                stato = r.get("stato", "")
                trainer = r.get("trainer", "")
                cliente_nome = clienti_map.get(int(r.get("cliente_id")), "Cliente")
                title = f"{cliente_nome} · {stato}"
                color = calendar_color_for_type("", stato)

                events.append({
                    "id": f"lezione-{lid}",
                    "title": title,
                    "start": f"{data_l}T{start}:00",
                    "end": f"{data_l}T{end}:00",
                    "backgroundColor": color,
                    "borderColor": color,
                    "extendedProps": {
                        "kind": "lezione",
                        "lezione_id": lid,
                        "cliente": cliente_nome,
                        "trainer": trainer,
                        "stato": stato,
                    }
                })
            except Exception:
                continue

    return events



def time_to_minutes(t):
    if hasattr(t, "hour"):
        return int(t.hour) * 60 + int(t.minute)
    s = str(t)[:5]
    h, m = s.split(":")
    return int(h) * 60 + int(m)


def minutes_to_hhmm(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def intervals_overlap(start_a, end_a, start_b, end_b):
    return start_a < end_b and start_b < end_a


def slot_occupazione_trainer(tipo_slot):
    tipo = (tipo_slot or "").upper()
    return "COACHING" not in tipo


def tipo_slot_da_cliente(cliente):
    tipo = pacchetto_tipo(cliente.get("pacchetto", ""))
    if tipo == "LUXURY":
        return "ONE TO ONE"
    if tipo == "GOLD":
        return "TWO TO ONE"
    if tipo == "VIP":
        return "THREE TO ONE"
    if tipo == "COACHING":
        return "COACHING IN SEDE"
    return "ONE TO ONE"


def lezioni_trainer_occupate(data_slot, trainer=None):
    try:
        lez = load_lezioni()
    except Exception:
        return pd.DataFrame()

    if lez.empty:
        return lez

    trainer = trainer or get_kreo_settings().get("trainer_default", "Vincenzo Crinisio")

    tmp = lez.copy()
    tmp = tmp[
        (tmp["data_lezione"].astype(str) == str(data_slot)) &
        (~tmp["stato"].isin(["ANNULLATO", "ASSENTE"]))
    ].copy()

    if tmp.empty:
        return tmp

    # Se il trainer è "Libero utilizzo attrezzi" o coaching, non occupa PT.
    if "trainer" in tmp.columns:
        tmp = tmp[tmp["trainer"].astype(str).str.upper() != "LIBERO UTILIZZO ATTREZZI"]

    if "trainer" in tmp.columns:
        tmp = tmp[
            (tmp["trainer"].astype(str).str.upper() == str(trainer).upper()) |
            (tmp["trainer"].isna())
        ]

    return tmp


def slot_pt_libero(data_slot, ora_inizio, ora_fine, trainer=None):
    trainer = trainer or get_kreo_settings().get("trainer_default", "Vincenzo Crinisio")
    start_new = time_to_minutes(ora_inizio)
    end_new = time_to_minutes(ora_fine)

    lez = lezioni_trainer_occupate(data_slot, trainer)
    if lez.empty:
        return True, ""

    for _, r in lez.iterrows():
        try:
            start_old = time_to_minutes(r.get("ora_inizio"))
            end_old = time_to_minutes(r.get("ora_fine"))
        except Exception:
            continue

        if intervals_overlap(start_new, end_new, start_old, end_old):
            cliente_nome = "altro cliente"
            try:
                c = get_cliente(int(r.get("cliente_id")))
                if c:
                    cliente_nome = f"{c.get('nome','')} {c.get('cognome','')}".strip()
            except Exception:
                pass
            return False, f"Trainer occupato dalle {minutes_to_hhmm(start_old)} alle {minutes_to_hhmm(end_old)} con {cliente_nome}."

    return True, ""


def genera_slot_intelligenti_cliente(cliente, data_slot=None, giorni=7):
    settings = get_kreo_settings()
    apertura = settings.get("apertura", "07:30")
    chiusura = settings.get("chiusura", "20:00")
    durata = int(settings.get("durata_slot_pt_minuti", 60) or 60)
    step = int(get_setting("step_slot_prenotazione_minuti", "30") or 30)
    trainer = settings.get("trainer_default", "Vincenzo Crinisio")

    tipo_slot = tipo_slot_da_cliente(cliente)
    occupa_trainer = slot_occupazione_trainer(tipo_slot)

    start_day = data_slot or date.today()
    open_min = time_to_minutes(apertura)
    close_min = time_to_minutes(chiusura)

    results = []
    for i in range(int(giorni)):
        d = start_day + timedelta(days=i)
        current = open_min
        while current + durata <= close_min:
            start_str = minutes_to_hhmm(current)
            end_str = minutes_to_hhmm(current + durata)

            if d == date.today():
                now_min = datetime.now().hour * 60 + datetime.now().minute
                if current <= now_min:
                    current += step
                    continue

            libero = True
            if occupa_trainer:
                libero, _ = slot_pt_libero(d, start_str, end_str, trainer)

            if libero:
                results.append({
                    "data_slot": str(d),
                    "data_slot_it": d.strftime("%d/%m/%Y"),
                    "ora_inizio": start_str,
                    "ora_fine": end_str,
                    "trainer": trainer if occupa_trainer else "Libero utilizzo attrezzi",
                    "tipo_slot": tipo_slot,
                    "posti_liberi": max_posti_per_pacchetto(cliente.get("pacchetto", "")),
                    "origine": "DISPONIBILITÀ AUTOMATICA",
                })

            current += step

    return pd.DataFrame(results)


def richiesta_prenotazione_intelligente_cliente(cliente_id, data_slot, ora_inizio, ora_fine, tipo_slot, note_cliente=""):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato."

    ok_pag, msg_pag = cliente_in_regola_pagamenti(cliente)
    if not ok_pag:
        return False, msg_pag

    ok_week, msg_week = cliente_puo_prenotare_settimana(cliente_id, parse_date(data_slot, date.today()))
    if not ok_week:
        return False, msg_week

    trainer = get_kreo_settings().get("trainer_default", "Vincenzo Crinisio")
    if slot_occupazione_trainer(tipo_slot):
        libero, motivo = slot_pt_libero(parse_date(data_slot, date.today()), ora_inizio, ora_fine, trainer)
        if not libero:
            return False, motivo
    else:
        trainer = "Libero utilizzo attrezzi"

    sb = get_supabase()
    sb.table("lezioni").insert({
        "cliente_id": int(cliente_id),
        "data_lezione": str(data_slot),
        "ora_inizio": str(ora_inizio),
        "ora_fine": str(ora_fine),
        "trainer": trainer,
        "stato": "RICHIESTA CLIENTE",
        "note": note_cliente,
        "creata_da": f"Cliente: {cliente.get('nome','')} {cliente.get('cognome','')}",
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }).execute()

    insert_history(
        cliente_id,
        "richiesta prenotazione smart",
        "",
        f"{format_date_it(data_slot)} {ora_inizio}-{ora_fine}",
        f"Richiesta prenotazione automatica da area cliente | Tipo: {tipo_slot} | Trainer: {trainer}"
    )
    return True, "Richiesta prenotazione inviata allo staff."



def safe_cliente_or_warning(cliente_id, context="cliente"):
    cliente = get_cliente(cliente_id)
    if not cliente:
        st.warning(f"Impossibile caricare {context}. Supabase potrebbe aver avuto un timeout temporaneo. Riprova o aggiorna la pagina.")
        return None
    return cliente


def render_calendario_unificato_staff():
    st.header("Calendario unificato")
    st.caption("Disponibilità automatica del trainer + prenotazioni clienti + coaching in sede.")


    with st.expander("➕ Inserimento rapido lezione cliente", expanded=False):
        st.caption("Usalo se cliccando uno slot del calendario non si apre correttamente il form. Registra una lezione/prestazione direttamente.")
        dfc_quick = load_clienti()
        if dfc_quick.empty:
            st.info("Nessun cliente presente.")
        else:
            dfc_quick = dfc_quick.sort_values("id", ascending=True).copy()
            labels_quick = (dfc_quick["id"].astype(str) + " - " + dfc_quick["nome"].fillna("") + " " + dfc_quick["cognome"].fillna("")).tolist()
            q1, q2, q3 = st.columns(3)
            with q1:
                selected_quick = st.selectbox("Cliente", labels_quick, key="cal_quick_cliente")
