                if conferma_del and st.button("🗑️ Elimina presenza / lezione", key=f"delete_presenza_btn_{cliente_id}"):
                    lezione_id = int(selected_del.split(" - ")[0])
                    ok, msg = elimina_presenza_lezione_cliente(lezione_id)
