def load_documenti(cliente_id=None):
    sb = get_supabase()
    q = sb.table("documenti_cliente").select("*").order("id", desc=True)
    if cliente_id is not None:
        q = q.eq("cliente_id", int(cliente_id))
    data = q.execute().data
    df = pd.DataFrame(data)
    if not df.empty and "created_at" in df.columns:
        df["created_at_it"] = df["created_at"].apply(lambda x: pd.to_datetime(x).strftime("%d/%m/%Y %H:%M") if x else "")
    return df


def upload_documento_cliente(cliente_id, file, tipo_documento, note_documento=""):
    """
    V37.05: ripristina la logica documenti che funzionava.
    Tabella: documenti_cliente
    Colonne: cliente_id, tipo_documento, nome_file, storage_path, public_url, caricato_da, note, created_at
    Bucket preferito: documenti, con fallback documenti_privati/documenti-clienti.
    """
    if file is None:
        return False, "Nessun file caricato."

    if not file.name.lower().endswith(".pdf"):
        return False, "Per ora sono ammessi solo file PDF."

    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato."

    sb = get_supabase()

    bucket_name, bucket_ok, existing_buckets = kreo_document_bucket_status()
    if not bucket_ok:
        return False, kreo_bucket_missing_text(bucket_name, existing_buckets)

    safe_name = file.name.replace(" ", "_").replace("/", "_").replace("\\", "_")
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    path = f"cliente_{cliente_id}/{tipo_documento.lower().replace(' ', '_')}_{timestamp}_{safe_name}"

    try:
        sb.storage.from_(bucket_name).upload(
            path,
            file.getvalue(),
            {"content-type": "application/pdf", "x-upsert": "true"}
        )
    except Exception as e:
        err = str(e)
        if "Bucket not found" in err or "bucket" in err.lower():
            return False, kreo_bucket_missing_text(bucket_name, existing_buckets)
        return False, f"Errore upload documento: {e}"

    public_url = ""
    try:
        public_url = sb.storage.from_(bucket_name).get_public_url(path) or ""
    except Exception:
        public_url = ""

    payload = {
        "cliente_id": int(cliente_id),
        "tipo_documento": tipo_documento,
        "nome_file": file.name,
        "storage_path": path,
        "public_url": public_url,
        "caricato_da": user_label(),
        "note": note_documento,
        "created_at": now_iso(),
    }

    sb.table("documenti_cliente").insert(payload).execute()

    if tipo_documento == "CERTIFICATO MEDICO":
        sb.table("clienti").update({
            "certificato_medico": "SI",
            "updated_at": now_iso(),
        }).eq("id", int(cliente_id)).execute()

    insert_history(
        cliente_id,
        f"upload documento - {tipo_documento}",
        "",
        file.name,
        f"Documento caricato da {user_label()}"
    )

    return True, "Documento caricato correttamente."


def delete_documento(documento_id):
    if not is_admin():
        return False, "Operazione riservata all'amministratore."

    sb = get_supabase()
    data = sb.table("documenti_cliente").select("*").eq("id", int(documento_id)).limit(1).execute().data

    if not data:
        return False, "Documento non trovato."

    doc = data[0]
    cliente_id = int(doc.get("cliente_id"))
    storage_path = doc.get("storage_path")

    try:
        if storage_path:
            sb.storage.from_(DOCUMENTI_BUCKET_PRIVATO).remove([storage_path])
    except Exception:
        # Se il file non viene trovato nello storage, elimino comunque il record dal database.
        pass

    sb.table("documenti_cliente").delete().eq("id", int(documento_id)).execute()

    insert_history(
        cliente_id,
        f"eliminazione documento - {doc.get('tipo_documento', '')}",
        doc.get("nome_file", ""),
        "",
        f"Documento eliminato da {user_label()}"
    )

    return True, "Documento eliminato correttamente."


