def build_alert_dashboard(df):
    rows, seen = [], set()
    for _, r in df.iterrows():
        for key, (priorita, msg) in get_cliente_alerts(r.to_dict()).items():
            uniq = (int(r["id"]), key)
            if uniq in seen:
                continue
            seen.add(uniq)
            rows.append({
                "Priorità": priorita,
                "ID": int(r["id"]),
                "Cliente": f"{r.get('nome','')} {r.get('cognome','')}",
                "Cellulare": r.get("cellulare", ""),
                "Pacchetto": r.get("pacchetto", ""),
                "Alert": msg,
                "Scadenza abbonamento": r.get("scadenza_abbonamento_it", ""),
                "Scadenza certificato": r.get("scadenza_certificato_it", ""),
                "Residuo": euro(r.get("residuo", 0)),
            })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["sort"] = out["Priorità"].map({"ALTA": 0, "MEDIA": 1})
        out = out.sort_values(["sort", "Cliente"]).drop(columns=["sort"])
    return out




def is_pacchetto_standard_auto(pacchetto):
    """
    Pacchetti soggetti a ricalcolo automatico settimanale.
    I personalizzati sono sempre esclusi.
    """
    p = str(pacchetto or "").upper()
    if "PERSONALIZZATO" in p:
        return False
    return any(x in p for x in ["LUXURY", "GOLD", "VIP", "COACHING"])


def is_pacchetto_settimanale_kreo(pacchetto):
    """
    Pacchetti con diritto automatico a 3 lezioni settimanali cumulative.
    Esclude il pacchetto personalizzato.
    """
    p = str(pacchetto or "").upper()
    if "PERSONALIZZATO" in p:
        return False
    return any(x in p for x in ["LUXURY", "GOLD", "VIP", "COACHING"])


def lezioni_settimanali_base_da_pacchetto(pacchetto):
    return 3 if is_pacchetto_settimanale_kreo(pacchetto) else 0


def lunedi_settimana(d=None):
    d = parse_date(d, date.today())
    return d - timedelta(days=d.weekday())


def settimane_da_inizio(data_inizio, data_ref=None):
    start = lunedi_settimana(data_inizio)
    end = lunedi_settimana(data_ref or date.today())
    diff = (end - start).days // 7
    return max(diff + 1, 1)


def lezioni_maturate_cumulative(cliente, data_ref=None):
    """
    Regola nuova:
    Pacchetti Luxury/Gold/VIP/Coaching maturano 3 lezioni ogni settimana
    e le lezioni non usate si portano avanti.
    """
    if not cliente:
        return 0

    pac = cliente.get("pacchetto", "")
    if not is_pacchetto_settimanale_kreo(pac):
        try:
            return int(float(cliente.get("numero_lezioni") or cliente.get("numero_lezioni_totali") or 0))
        except Exception:
            return 0

    data_inizio = cliente.get("data_inizio_pacchetto") or cliente.get("data_iscrizione") or date.today()
    settimane = settimane_da_inizio(data_inizio, data_ref or date.today())
    return settimane * 3


def lezioni_usate_totali_cliente(cliente_id, data_da=None, data_a=None):
    """
    Conta le presenze effettive del cliente.

    Regola anti-doppio-scarico:
    se per errore esistono due righe PRESENTE nello stesso giorno
    (es. badge + recupero retroattivo), viene conteggiata UNA sola lezione
    per quel giorno.
    """
    try:
        lez = load_lezioni()
        if lez.empty:
            return 0
        tmp = lez.copy()
        tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
        tmp["stato_norm"] = tmp["stato"].astype(str).str.upper()
        tmp = tmp[
            (tmp["cliente_id_num"] == int(cliente_id)) &
            (tmp["stato_norm"] == "PRESENTE")
        ]
        if data_da:
            tmp = tmp[tmp["data_lezione"].astype(str) >= str(parse_date(data_da, date.today()))]
        if data_a:
            tmp = tmp[tmp["data_lezione"].astype(str) <= str(parse_date(data_a, date.today()))]

        if tmp.empty:
            return 0

        # 1 accesso/presenza = 1 lezione scalata al giorno.
        return int(tmp["data_lezione"].astype(str).nunique())
    except Exception:
        return 0


def contatori_cumulativi_cliente(cliente_id, data_ref=None):
    cliente = get_cliente(int(cliente_id))
    if not cliente:
        return 0, 0, 0

    pac = cliente.get("pacchetto", "")
    if is_pacchetto_settimanale_kreo(pac):
        totale = lezioni_maturate_cumulative(cliente, data_ref or date.today())
        data_da = cliente.get("data_inizio_pacchetto") or cliente.get("data_iscrizione")
        usate = lezioni_usate_totali_cliente(cliente_id, data_da=data_da, data_a=data_ref or date.today())
        residue = max(int(totale) - int(usate), 0)
        return int(totale), int(usate), int(residue)

    try:
        totale = int(float(cliente.get("numero_lezioni") or cliente.get("numero_lezioni_totali") or 0))
    except Exception:
        totale = 0
    usate = lezioni_usate_totali_cliente(cliente_id)
    residue = max(totale - usate, 0)
    return int(totale), int(usate), int(residue)


def aggiorna_contatori_cumulativi_clienti():
    """
    Ricalcolo settimanale sicuro:
    - aggiorna solo pacchetti automatici: Luxury / Gold / VIP / Coaching in sede
    - esclude completamente i pacchetti personalizzati
    """
    sb = get_supabase()
    clienti = load_clienti()
    if clienti.empty:
        return {"aggiornati": 0, "personalizzati_ignorati": 0, "saltati": 0}

    aggiornati = 0
    personalizzati_ignorati = 0
    saltati = 0

    for _, c in clienti.iterrows():
        try:
            pac = c.get("pacchetto", "")
            if not is_pacchetto_standard_auto(pac):
                personalizzati_ignorati += 1
                continue

            cid = int(c.get("id"))
            totale, usate, residue = contatori_cumulativi_cliente(cid)

            ok_update, _ = safe_update_cliente_contatori(cid, totale, usate, residue) if "safe_update_cliente_contatori" in globals() else (False, "")
            if not ok_update:
                sb.table("clienti").update({
                    "numero_lezioni": int(totale),
                    "lezioni_utilizzate": int(usate),
                    "lezioni_residue": int(residue),
                    "updated_at": now_iso(),
                }).eq("id", cid).execute()

            aggiornati += 1
        except Exception:
            saltati += 1

    return {
        "aggiornati": aggiornati,
        "personalizzati_ignorati": personalizzati_ignorati,
        "saltati": saltati,
    }

def dataframe_clienti_con_contatori_cumulativi(df):
    if df.empty:
        return df
    out = df.copy()
    for col in ["numero_lezioni", "lezioni_utilizzate", "lezioni_residue"]:
        if col not in out.columns:
            out[col] = 0

    for idx, row in out.iterrows():
        try:
            cid = int(row.get("id"))
            totale, usate, residue = contatori_cumulativi_cliente(cid)
            out.at[idx, "numero_lezioni"] = totale
            out.at[idx, "lezioni_utilizzate"] = usate
            out.at[idx, "lezioni_residue"] = residue
        except Exception:
            continue

    return out


def render_lezioni_cumulative_admin():
    st.subheader("Ricalcolo lezioni cumulative")
    st.caption("Luxury / Gold / VIP / Coaching maturano 3 lezioni ogni settimana. Le lezioni non utilizzate si sommano alle settimane successive.")

    st.markdown("""
    **Nuova regola KREO**
    - Pacchetti standard: +3 lezioni ogni settimana
    - Le lezioni non usate restano disponibili
    - Pacchetto personalizzato: escluso dal ricalcolo automatico
    """)

    if st.button("🔄 Ricalcola lezioni cumulative", key="ricalcola_lezioni_cumulative"):
        res = aggiorna_contatori_cumulativi_clienti()
        st.success(f"Ricalcolo completato. Automatici aggiornati: {res['aggiornati']} | personalizzati ignorati: {res.get('personalizzati_ignorati', 0)} | saltati: {res['saltati']}")
        st.rerun()


def cliente_form(prefix, defaults=None, unique_suffix=""):
    defaults = defaults or {}
    k = lambda name: f"{prefix}_{unique_suffix}_{name}"

    st.subheader("Dati anagrafici")
    c1, c2 = st.columns(2)
    with c1:
        nome = st.text_input("Nome *", value=defaults.get("nome", ""), key=k("nome"))
        cognome = st.text_input("Cognome *", value=defaults.get("cognome", ""), key=k("cognome"))
        cellulare = st.text_input("Cellulare", value=defaults.get("cellulare", ""), key=k("cellulare"))
    with c2:
        email = st.text_input("Email", value=defaults.get("email", ""), key=k("email"))
        codice_fiscale = st.text_input("Codice fiscale", value=defaults.get("codice_fiscale", ""), key=k("cf"))

    st.subheader("Pacchetto e pagamento")
    c3, c4 = st.columns(2)
    with c3:
        pac_def = defaults.get("pacchetto", "PACCHETTO LUXURY")
        pacchetto = st.selectbox("Pacchetto", list(PACCHETTI.keys()), index=list(PACCHETTI.keys()).index(pac_def) if pac_def in PACCHETTI else 0, key=k("pacchetto"))
        abb_def = defaults.get("tipologia_abbonamento", "ANNUALE")
        tipologia_abbonamento = st.selectbox("Tipologia abbonamento", TIPOLOGIE_ABBONAMENTO, index=TIPOLOGIE_ABBONAMENTO.index(abb_def) if abb_def in TIPOLOGIE_ABBONAMENTO else 3, key=k("tipologia_abbonamento"))
        tip_def = defaults.get("tipologia_pagamento", "MENSILE")
        tipologia = st.selectbox("Tipologia pagamento", TIPOLOGIE_PAGAMENTO, index=TIPOLOGIE_PAGAMENTO.index(tip_def) if tip_def in TIPOLOGIE_PAGAMENTO else 0, key=k("tipologia"))
        lezioni_base_auto_form = lezioni_settimanali_base_da_pacchetto(pacchetto)
        if lezioni_base_auto_form > 0:
            numero_lezioni_default_form = lezioni_base_auto_form
        else:
            numero_lezioni_default_form = int(defaults.get("numero_lezioni", 0) or 0)
        numero_lezioni = st.number_input("Numero lezioni totali", min_value=0, step=1, value=int(defaults.get("numero_lezioni") or 0), key=k("num_lez"))
        lezioni_utilizzate = st.number_input("Lezioni già utilizzate", min_value=0, step=1, value=int(defaults.get("lezioni_utilizzate") or 0), key=k("lez_usate"))

    with c4:
        default_importo = float(defaults.get("importo") if defaults.get("importo") not in [None, ""] else PACCHETTI[pacchetto])
        if prefix == "new" and pacchetto != "PACCHETTO PERSONALIZZATO":
            default_importo = float(PACCHETTI[pacchetto])
        importo = st.number_input("Importo contratto / periodo (€)", min_value=0.0, step=10.0, value=default_importo, key=k("importo"))
        importo_pagato = st.number_input("Importo pagato (€)", min_value=0.0, step=10.0, value=float(defaults.get("importo_pagato") or 0), key=k("pagato"))
        st.success(f"Residuo aggiornato: {euro(max(importo - importo_pagato, 0))}")
        st.info(f"Lezioni residue: {max(int(numero_lezioni) - int(lezioni_utilizzate), 0)}")

    st.subheader("Date e documenti")
    data_iscr_default = parse_date(defaults.get("data_iscrizione"), date.today())
    data_inizio_default = parse_date(defaults.get("data_inizio_pacchetto"), date.today())
    c5, c6, c7 = st.columns(3)
    with c5:
        data_iscrizione = st.date_input("Data iscrizione", value=data_iscr_default, format="DD/MM/YYYY", key=k("data_iscr"))
        data_inizio = st.date_input("Data inizio pacchetto", value=data_inizio_default, format="DD/MM/YYYY", key=k("data_inizio"))
    with c6:
        cert_def = defaults.get("certificato_medico", "NO")
        certificato = st.selectbox("Certificato medico consegnato", SI_NO, index=SI_NO.index(cert_def) if cert_def in SI_NO else 1, key=k("cert"))
        scadenza_certificato = st.date_input("Scadenza certificato", value=parse_date(defaults.get("scadenza_certificato"), date.today()+timedelta(days=365)), format="DD/MM/YYYY", key=k("scad_cert"))
    with c7:
        cons_def = defaults.get("consenso_foto_video", "NO")
        consenso = st.selectbox("Consenso foto/video", SI_NO, index=SI_NO.index(cons_def) if cons_def in SI_NO else 1, key=k("consenso"))
        stato_def = defaults.get("stato_cliente", "ATTIVO")
        stato = st.selectbox("Stato cliente", STATI_CLIENTE, index=STATI_CLIENTE.index(stato_def) if stato_def in STATI_CLIENTE else 0, key=k("stato"))

    # Scadenza abbonamento automatica blindata.
    data_inizio_pacchetto = data_inizio
    scadenza_auto_calc = calcola_scadenza_abbonamento_blindata(data_inizio_pacchetto, tipologia_abbonamento, pacchetto)

    scad_key_dynamic = k(
        "scad_abb_"
        + str(data_inizio_pacchetto)
        + "_"
        + str(tipologia_abbonamento).replace(" ", "_")
        + "_"
        + str(pacchetto).replace(" ", "_")
    )

    if scadenza_auto_calc is not None:
        scadenza_abbonamento = st.date_input(
            "Scadenza abbonamento / prossima rata",
            value=scadenza_auto_calc,
            format="DD/MM/YYYY",
            key=scad_key_dynamic,
        )
    else:
        scadenza_abbonamento = st.date_input(
            "Scadenza abbonamento / prossima rata",
            value=parse_date(defaults.get("scadenza_abbonamento"), data_inizio_pacchetto),
            format="DD/MM/YYYY",
            key=scad_key_dynamic,
        )

    st.info(label_scadenza_abbonamento_blindata(data_inizio_pacchetto, tipologia_abbonamento, pacchetto))
    note = st.text_area("Note", value=defaults.get("note", ""), key=k("note"))

    return {
        "nome": nome.strip(),
        "cognome": cognome.strip(),
        "cellulare": cellulare.strip(),
        "email": email.strip(),
        "codice_fiscale": codice_fiscale.strip(),
        "pacchetto": pacchetto,
        "tipologia_abbonamento": tipologia_abbonamento,
        "tipologia_pagamento": tipologia,
        "numero_lezioni": int(lezioni_base_auto_form if lezioni_base_auto_form > 0 else numero_lezioni),
        "lezioni_utilizzate": int(lezioni_utilizzate),
        "importo": float(importo),
        "importo_pagato": float(importo_pagato),
        "data_iscrizione": str(data_iscrizione),
        "data_inizio_pacchetto": str(data_inizio),
        "scadenza_abbonamento": (None if scadenza_auto_calc is None else str(scadenza_auto_calc)),
        "certificato_medico": certificato,
        "scadenza_certificato": str(scadenza_certificato),
        "consenso_foto_video": consenso,
        "stato_cliente": stato,
        "note": note.strip(),
    }


def login_gate():
    st.markdown("### Scegli tipo di accesso")
    access_type = st.radio(
        "Accesso",
        ["Staff KREO", "Cliente"],
        horizontal=True,
        label_visibility="collapsed"
    )

    if access_type == "Cliente":
        cliente_login_gate()
        return False

    if "logged_in" not in st.session_state:
        st.session_state.logged_in = False
    if st.session_state.logged_in and st.session_state.get("user"):
        return True

    st.title("Accesso gestionale KREO")
    st.caption("Inserisci le credenziali personali assegnate allo staff.")

    username = st.text_input("Username")
    password = st.text_input("Password", type="password")

    if st.button("Entra"):
        if not username or not password:
            st.error("Inserisci username e password.")
            return False

        sb = get_supabase()
        data = (
            sb.table("utenti")
            .select("*")
            .eq("username", username.strip().lower())
            .eq("attivo", True)
            .limit(1)
            .execute()
            .data
        )

        if not data:
            st.error("Utente non trovato o non attivo.")
            return False

        user = data[0]
        if user.get("password_hash") != hash_password(password):
            st.error("Password errata.")
            return False

        st.session_state.logged_in = True
        st.session_state.user = {
            "id": user.get("id"),
            "nome": user.get("nome"),
            "username": user.get("username"),
            "ruolo": user.get("ruolo"),
        }
        st.rerun()

    return False






