def kreo_is_pacchetto_personalizzato_strict(pacchetto):
    """
    Pacchetto personalizzato = gestione manuale.
    Non deve subire ricalcoli automatici settimanali/cumulativi.
    """
    return "PERSONALIZZATO" in str(pacchetto or "").upper()


def kreo_is_pacchetto_standard_cumulativo(pacchetto):
    """
    Pacchetti che maturano automaticamente 3 lezioni ogni settimana.
    Personalizzato sempre escluso.
    """
    p = str(pacchetto or "").upper()
    if "PERSONALIZZATO" in p:
        return False
    return any(x in p for x in ["LUXURY", "GOLD", "VIP", "COACHING"])


def kreo_data_inizio_contatori_cliente(cliente):
    """
    Data da cui iniziare il conteggio cumulativo.
    Priorità:
    1. data_inizio_pacchetto
    2. data_iscrizione
    3. created_at
    4. oggi
    """
    for k in ["data_inizio_pacchetto", "data_iscrizione", "created_at"]:
        v = cliente.get(k) if isinstance(cliente, dict) else None
        if v not in [None, "", "nan"]:
            try:
                return parse_date(v, date.today())
            except Exception:
                pass
    return date.today()


def kreo_settimane_maturate_da_inizio(data_inizio, data_ref=None):
    data_ref = parse_date(data_ref or date.today(), date.today())
    start = parse_date(data_inizio, date.today())
    start_monday = start - timedelta(days=start.weekday())
    ref_monday = data_ref - timedelta(days=data_ref.weekday())
    weeks = ((ref_monday - start_monday).days // 7) + 1
    return max(int(weeks), 1)


def kreo_lezioni_presenti_cliente(cliente_id, data_da=None, data_a=None):
    """
    Conta lezioni PRESENTE valide.
    Esclude righe annullate e stati tecnici.
    Fonte primaria per il consumo.
    """
    try:
        lez = load_lezioni()
        if lez.empty:
            return 0

        tmp = lez.copy()
        tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
        tmp["stato_norm"] = tmp["stato"].fillna("").astype(str).str.upper()

        tmp = tmp[
            (tmp["cliente_id_num"] == int(cliente_id)) &
            (tmp["stato_norm"] == "PRESENTE")
        ]

        if "note" in tmp.columns:
            note_norm = tmp["note"].fillna("").astype(str).str.upper()
            tmp = tmp[~note_norm.str.contains("ANNULLATO|RIMOSSA PRESENZA", na=False)]

        if data_da is not None and "data_lezione" in tmp.columns:
            tmp = tmp[tmp["data_lezione"].astype(str) >= str(parse_date(data_da, date.today()))]
        if data_a is not None and "data_lezione" in tmp.columns:
            tmp = tmp[tmp["data_lezione"].astype(str) <= str(parse_date(data_a, date.today()))]

        return int(len(tmp))
    except Exception:
        return 0


def registra_movimento_lezione(cliente_id, tipo, quantita=1, motivo="", accesso_id=None, lezione_id=None, note=""):
    """
    Ledger centrale movimenti lezione.

    Tipi consigliati:
    - SCALA
    - RESTITUISCI
    - EXTRA_AUTORIZZATA
    - ANNULLA
    - RETTIFICA_MANUALE

    Se la tabella movimenti_lezioni non esiste, salva fallback in cronologia.
    """
    try:
        cid = int(float(cliente_id)) if cliente_id not in [None, "", "nan"] else None
    except Exception:
        cid = None

    payload = {
        "cliente_id": cid,
        "tipo": str(tipo or "").upper(),
        "quantita": int(quantita or 1),
        "motivo": motivo or "",
        "accesso_id": accesso_id,
        "lezione_id": lezione_id,
        "note": note or "",
        "created_at": datetime.now().isoformat(),
    }

    try:
        user_name = kreo_current_user_display_name() if "kreo_current_user_display_name" in globals() else ""
        if user_name:
            payload["created_by"] = user_name
    except Exception:
        pass

    sb = get_supabase()

    try:
        sb.table("movimenti_lezioni").insert(payload).execute()
        return True, "Movimento lezione registrato."
    except Exception:
        # fallback: cronologia
        try:
            sb.table("cronologia").insert({
                "cliente_id": cid,
                "azione": f"MOVIMENTO_LEZIONE_{payload['tipo']}",
                "dettaglio": f"Quantità {payload['quantita']} | {payload['motivo']} | accesso_id={accesso_id} | lezione_id={lezione_id} | {note}",
                "created_at": datetime.now().isoformat()
            }).execute()
            return True, "Movimento salvato in cronologia."
        except Exception as e:
            return False, f"Movimento non salvato: {e}"



# ============================================================
# KREO PRESENZE - MOTORE UNICO ANTI-DOPPIONE
# ============================================================

def kreo_movimento_lezione_esiste(cliente_id, tipo=None, accesso_id=None, lezione_id=None):
    """
    Evita doppio scarico/restituzione.
    Cerca nel ledger movimenti_lezioni un movimento già registrato
    per stesso cliente + stesso accesso o stessa lezione.
    """
    try:
        sb = get_supabase()
        q = sb.table("movimenti_lezioni").select("*").eq("cliente_id", int(float(cliente_id)))
        if tipo:
            q = q.eq("tipo", str(tipo).upper())
        if accesso_id not in [None, "", "nan"]:
            q = q.eq("accesso_id", int(float(accesso_id)))
        if lezione_id not in [None, "", "nan"]:
            q = q.eq("lezione_id", int(float(lezione_id)))
        rows = q.limit(1).execute().data or []
        return bool(rows)
    except Exception:
        return False


def kreo_registra_movimento_lezione_unico(cliente_id, tipo, quantita=1, motivo="", accesso_id=None, lezione_id=None, note=""):
    """
    Wrapper sicuro: registra SCALA/RESTITUISCI una sola volta per lo stesso evento.
    """
    tipo_norm = str(tipo or "").upper()
    if tipo_norm in ["SCALA", "RESTITUISCI"] and kreo_movimento_lezione_esiste(cliente_id, tipo_norm, accesso_id, lezione_id):
        return True, f"Movimento {tipo_norm} già presente: nessun doppio conteggio."
    return registra_movimento_lezione(cliente_id, tipo_norm, quantita, motivo, accesso_id=accesso_id, lezione_id=lezione_id, note=note)


def kreo_find_lezione_collegata(cliente_id, accesso_id=None, data_lezione=None):
    """
    Trova lezione collegata a un accesso o, in fallback, la presenza/prenotazione del giorno.
    """
    try:
        sb = get_supabase()
        rows = []
        if accesso_id not in [None, "", "nan"]:
            # Non sempre abbiamo una colonna accesso_id: il collegamento è spesso nelle note.
            all_rows = sb.table("lezioni").select("*").eq("cliente_id", int(float(cliente_id))).execute().data or []
            aid = str(int(float(accesso_id)))
            for r in all_rows:
                note = str(r.get("note") or "")
                if f"access_id={aid}" in note or f"accesso_id={aid}" in note or f"ACCESSO ID {aid}" in note:
                    rows.append(r)
            if rows:
                return rows[0]

        if data_lezione:
            day_rows = sb.table("lezioni").select("*").eq("cliente_id", int(float(cliente_id))).eq("data_lezione", str(data_lezione)).execute().data or []
            # preferisci prenotata o presente nello stesso giorno
            for stato in ["PRENOTATO", "PRENOTATA", "PRESENTE"]:
                for r in day_rows:
                    if str(r.get("stato") or "").upper() == stato:
                        return r
            if len(day_rows) == 1:
                return day_rows[0]
    except Exception:
        pass
    return None


def kreo_crea_lezione_presenza_da_accesso(cliente_id, accesso_row=None, motivo="Presenza da accesso tornello"):
    """
    Crea una riga lezioni PRESENTE quando non esiste una lezione da confermare.
    Usata da check-in/tornello solo tramite motore unico.
    """
    try:
        accesso_row = accesso_row or {}
        data_acc = accesso_row.get("data_accesso") or date.today()
        ora_acc = str(accesso_row.get("ora_accesso") or datetime.now().strftime("%H:%M"))[:5]
        accesso_id = accesso_row.get("id")
        cliente = get_cliente(int(float(cliente_id))) or {}
        pac = cliente.get("pacchetto", "")
        try:
            start = round_time_up_hhmm(ora_acc, 30) if "round_time_up_hhmm" in globals() else ora_acc
            end = add_minutes_hhmm(start, 60) if "add_minutes_hhmm" in globals() else start
        except Exception:
            start, end = ora_acc, ora_acc
        try:
            trainer = trainer_from_pacchetto_app(pac) if "trainer_from_pacchetto_app" in globals() else "Reception"
        except Exception:
            trainer = "Reception"

        note = f"{motivo}. Creata da motore unico presenze. access_id={accesso_id}. Pacchetto: {pac}"
        ok, msg = insert_lezione(
            cliente_id=int(float(cliente_id)),
            data_lezione=str(data_acc),
            ora_inizio=str(start),
            ora_fine=str(end),
            trainer=trainer,
            stato="PRESENTE",
            note=note,
        )
        if not ok:
            return None
        return kreo_find_lezione_collegata(cliente_id, accesso_id=accesso_id, data_lezione=data_acc)
    except Exception:
        return None


def kreo_registra_presenza_no_scala(cliente_id, accesso_id=None, motivo="Presenza autorizzata senza consumo", note=""):
    """
    Traccia una presenza/ingresso che NON consuma lezioni.
    """
    try:
        sb = get_supabase()
        payload = {
            "cliente_id": int(float(cliente_id)) if cliente_id not in [None, "", "nan"] else None,
            "data_presenza": str(date.today()),
            "ora_presenza": datetime.now().strftime("%H:%M:%S"),
            "tipo": "PRESENZA_NO_SCALA",
            "note": (note or motivo),
        }
        try:
            sb.table("presenze_clienti").insert(payload).execute()
        except Exception:
            sb.table("cronologia").insert({
                "cliente_id": payload["cliente_id"],
                "azione": "PRESENZA_NO_SCALA",
                "dettaglio": note or motivo,
                "created_at": datetime.now().isoformat()
            }).execute()
        if accesso_id not in [None, "", "nan"]:
            sb.table("accessi_tornello").update({
                "stato_accesso": "PRESENZA_AUTORIZZATA_NO_SCALA",
                "note": (str(note or "") + f" | {motivo}").strip(" |"),
            }).eq("id", int(float(accesso_id))).execute()
        return True, "Presenza autorizzata senza scalare lezioni."
    except Exception as e:
        return False, f"Errore presenza senza scala: {e}"


def kreo_gestisci_presenza(cliente_id, lezione_id=None, accesso_id=None, accesso_row=None, azione="CONFERMA", consuma_lezione=True, motivo="", source="KREO"):
    """
    MOTORE UNICO PRESENZE.

    Da usare per Agenda, Reception, Tornello, Manuale.
    Regole:
    - Tornello/accesso non scala mai da solo.
    - Solo questa funzione può trasformare evento/prenotazione in presenza.
    - Se consuma_lezione=True: lezione -> PRESENTE + ledger SCALA una sola volta + ricalcolo contatori.
    - Se consuma_lezione=False: traccia presenza no scala, senza toccare lezioni residue.
    - RIMOZIONE: lezione -> PRENOTATO/ANNULLATA + ledger RESTITUISCI una sola volta + ricalcolo.
    """
    try:
        sb = get_supabase()
        cid = int(float(cliente_id)) if cliente_id not in [None, "", "nan"] else None
        if not cid:
            return False, "Cliente non valido."

        accesso_row = accesso_row or {}
        if accesso_id in [None, "", "nan"] and accesso_row:
            accesso_id = accesso_row.get("id")
        data_ref = accesso_row.get("data_accesso") or date.today()
        motivo_finale = motivo or f"Presenza gestita da {source}"

        if str(azione).upper() in ["RIMUOVI", "ANNULLA", "CANCELLA"]:
            lezione = None
            if lezione_id not in [None, "", "nan"]:
                rows = sb.table("lezioni").select("*").eq("id", int(float(lezione_id))).limit(1).execute().data or []
                lezione = rows[0] if rows else None
            if not lezione:
                lezione = kreo_find_lezione_collegata(cid, accesso_id=accesso_id, data_lezione=data_ref)
            if lezione:
                old_note = str(lezione.get("note") or "")
                # Da Agenda torna PRENOTATO; da accesso annullato diventa ANNULLATA.
                nuovo_stato = "PRENOTATO" if source.upper().startswith("AGENDA") else "ANNULLATA"
                sb.table("lezioni").update({
                    "stato": nuovo_stato,
                    "updated_at": now_iso(),
                    "note": (old_note + f" | Presenza rimossa da {source}: {motivo_finale}").strip(" |")
                }).eq("id", int(float(lezione.get("id")))).execute()
                kreo_registra_movimento_lezione_unico(cid, "RESTITUISCI", 1, motivo_finale, accesso_id=accesso_id, lezione_id=lezione.get("id"), note=f"source={source}")
            if accesso_id not in [None, "", "nan"]:
                try:
                    sb.table("accessi_tornello").update({
                        "stato_accesso": "ANNULLATO_DA_NON_RICALCOLARE",
                        "note": f"{motivo_finale} | Gestito da motore unico presenze"
                    }).eq("id", int(float(accesso_id))).execute()
                except Exception:
                    pass
            aggiorna_contatori_dopo_presenza_lezione(cid)
            if "kreo_recalcola_contatori_ledger_cliente" in globals():
                kreo_recalcola_contatori_ledger_cliente(cid)
            try: st.cache_data.clear()
            except Exception: pass
            return True, "Presenza rimossa/annullata con logica unica."

        # Presenza autorizzata ma NON scala.
        if not consuma_lezione:
            ok, msg = kreo_registra_presenza_no_scala(cid, accesso_id=accesso_id, motivo=motivo_finale, note=f"source={source}")
            try: st.cache_data.clear()
            except Exception: pass
            return ok, msg

        # Presenza che consuma lezione.
        lezione = None
        if lezione_id not in [None, "", "nan"]:
            rows = sb.table("lezioni").select("*").eq("id", int(float(lezione_id))).limit(1).execute().data or []
            lezione = rows[0] if rows else None
        if not lezione:
            lezione = kreo_find_lezione_collegata(cid, accesso_id=accesso_id, data_lezione=data_ref)
        if not lezione:
            lezione = kreo_crea_lezione_presenza_da_accesso(cid, accesso_row=accesso_row, motivo=motivo_finale)

        if not lezione:
            return False, "Nessuna lezione trovata o creata per registrare la presenza."

        old_note = str(lezione.get("note") or "")
        sb.table("lezioni").update({
            "stato": "PRESENTE",
            "updated_at": now_iso(),
            "note": (old_note + f" | Presenza confermata da {source}: {motivo_finale}").strip(" |")
        }).eq("id", int(float(lezione.get("id")))).execute()

        kreo_registra_movimento_lezione_unico(cid, "SCALA", 1, motivo_finale, accesso_id=accesso_id, lezione_id=lezione.get("id"), note=f"source={source}")
        if accesso_id not in [None, "", "nan"]:
            try:
                sb.table("accessi_tornello").update({
                    "stato_accesso": "PRESENZA_CONFERMATA_SCALA",
                    "note": f"{motivo_finale} | Gestito da motore unico presenze"
                }).eq("id", int(float(accesso_id))).execute()
            except Exception:
                pass

        aggiorna_contatori_dopo_presenza_lezione(cid)
        if "kreo_recalcola_contatori_ledger_cliente" in globals():
            kreo_recalcola_contatori_ledger_cliente(cid)
        try:
            insert_history(cid, "presenza confermata", "", "Lezione scalata", f"{motivo_finale} | source={source} | accesso_id={accesso_id} | lezione_id={lezione.get('id')}")
        except Exception:
            pass
        try: st.cache_data.clear()
        except Exception: pass
        return True, "Presenza confermata. Lezione scalata una sola volta."
    except Exception as e:
        return False, f"Errore motore unico presenze: {e}"

def kreo_movimenti_rettifica_cliente(cliente_id, data_da=None, data_a=None):
    """
    Legge solo rettifiche manuali dal ledger.
    Non conta automaticamente SCALA legata a lezioni PRESENTE, per evitare doppio conteggio.
    """
    try:
        sb = get_supabase()
        q = sb.table("movimenti_lezioni").select("*").eq("cliente_id", int(cliente_id))
        res = q.execute()
        rows = res.data or []
        if not rows:
            return 0

        delta_usate = 0
        for r in rows:
            tipo = str(r.get("tipo") or "").upper()
            qty = int(float(r.get("quantita") or 1))
            created = str(r.get("created_at") or "")[:10]

            if data_da and created and created < str(parse_date(data_da, date.today())):
                continue
            if data_a and created and created > str(parse_date(data_a, date.today())):
                continue

            # Solo movimenti che non hanno lezione_id/accesso_id, cioè rettifiche manuali pure
            if r.get("lezione_id") or r.get("accesso_id"):
                continue

            if tipo in ["SCALA", "EXTRA_AUTORIZZATA", "RETTIFICA_SCALA"]:
                delta_usate += qty
            elif tipo in ["RESTITUISCI", "ANNULLA", "RETTIFICA_RESTITUISCI"]:
                delta_usate -= qty

        return int(delta_usate)
    except Exception:
        return 0


def contatori_cumulativi_cliente(cliente_id, pacchetto=None, data_ref=None):
    """
    NUOVA LOGICA KREO V36.00

    Pacchetti standard:
    - Luxury / Gold / VIP / Coaching in sede
    - maturano 3 lezioni ogni settimana
    - le lezioni non usate restano disponibili
    - totale = settimane maturate * 3
    - usate = lezioni PRESENTE valide + rettifiche manuali
    - residue = totale - usate

    Pacchetti personalizzati:
    - esclusi dal ricalcolo automatico
    - mantengono i valori presenti in anagrafica
    - gestiti manualmente
    """
    data_ref = parse_date(data_ref or date.today(), date.today())

    try:
        c = get_cliente(int(cliente_id))
    except Exception:
        c = None

    if not c:
        return 0, 0, 0, 0

    pac = pacchetto if pacchetto is not None else c.get("pacchetto", "")

    # Personalizzato: non ricalcolare, non sovrascrivere.
    if kreo_is_pacchetto_personalizzato_strict(pac):
        try:
            totale = int(float(c.get("numero_lezioni") or c.get("numero_lezioni_totali") or 0))
        except Exception:
            totale = 0
        try:
            usate = int(float(c.get("lezioni_utilizzate") or 0))
        except Exception:
            usate = 0
        try:
            residue = int(float(c.get("lezioni_residue") or max(totale - usate, 0)))
        except Exception:
            residue = max(totale - usate, 0)
        extra = max(usate - totale, 0) if totale > 0 else 0
        return int(totale), int(usate), int(residue), int(extra)

    # Standard cumulativo.
    if kreo_is_pacchetto_standard_cumulativo(pac):
        data_inizio = kreo_data_inizio_contatori_cliente(c)
        settimane = kreo_settimane_maturate_da_inizio(data_inizio, data_ref)
        totale = int(settimane * 3)

        usate_da_lezioni = kreo_lezioni_presenti_cliente(
            int(cliente_id),
            data_da=data_inizio,
            data_a=data_ref
        )
        rettifiche = kreo_movimenti_rettifica_cliente(
            int(cliente_id),
            data_da=data_inizio,
            data_a=data_ref
        )
        usate = max(int(usate_da_lezioni) + int(rettifiche), 0)
        residue = max(totale - usate, 0)
        extra = max(usate - totale, 0)
        return int(totale), int(usate), int(residue), int(extra)

    # Altri pacchetti non riconosciuti: comportamento manuale conservativo.
    try:
        totale = int(float(c.get("numero_lezioni") or c.get("numero_lezioni_totali") or 0))
    except Exception:
        totale = 0
    try:
        usate = int(float(c.get("lezioni_utilizzate") or 0))
    except Exception:
        usate = kreo_lezioni_presenti_cliente(int(cliente_id), data_a=data_ref)
    residue = max(totale - usate, 0)
    extra = max(usate - totale, 0) if totale > 0 else 0
    return int(totale), int(usate), int(residue), int(extra)


def aggiorna_contatori_dopo_presenza_lezione(cliente_id):
    """
    Aggiorna i contatori cliente usando la logica cumulativa centrale.
    Non sovrascrive i personalizzati.
    """
    try:
        c = get_cliente(int(cliente_id))
        if c and kreo_is_pacchetto_personalizzato_strict(c.get("pacchetto", "")):
            return True

        totale, usate, residue, extra = contatori_cumulativi_cliente(int(cliente_id))
        ok_update, _ = safe_update_cliente_contatori(int(cliente_id), totale, usate, residue)
        return bool(ok_update)
    except Exception:
        return False


def aggiorna_contatori_cumulativi_clienti():
    """
    Ricalcolo cumulativo automatico:
    - aggiorna solo pacchetti standard cumulativi
    - salta i personalizzati
    """
    sb = get_supabase()
    clienti = load_clienti()
    if clienti.empty:
        return {"aggiornati": 0, "personalizzati_ignorati": 0, "saltati": 0}

    aggiornati = 0
    personalizzati_ignorati = 0
    saltati = 0

    for _, c in clienti.iterrows():
        try:
            cid = int(c.get("id"))
            pac = c.get("pacchetto", "")

            if kreo_is_pacchetto_personalizzato_strict(pac):
                personalizzati_ignorati += 1
                continue

            if not kreo_is_pacchetto_standard_cumulativo(pac):
                saltati += 1
                continue

            totale, usate, residue, extra = contatori_cumulativi_cliente(cid, pac)
            ok_update, _ = safe_update_cliente_contatori(cid, totale, usate, residue)
            if ok_update:
                aggiornati += 1
            else:
                saltati += 1
        except Exception:
            saltati += 1

    return {
        "aggiornati": aggiornati,
        "personalizzati_ignorati": personalizzati_ignorati,
        "saltati": saltati,
    }


def ricalcola_contatori_settimanali_clienti_robust(data_ref=None):
    """
    Compatibilità con vecchi pulsanti:
    ora usa il ricalcolo cumulativo, non il reset settimanale a 3.
    """
    return aggiorna_contatori_cumulativi_clienti()


def normalize_status_text(x):
    return str(x or "").strip().upper()


def cliente_weekly_access_dates(cliente_id, data_ref=None):
    """
    Fonte alternativa robusta: accessi_tornello associati al cliente nella settimana.
    Conta max 1 accesso/giorno come presenza utile, salvo che esistano più lezioni PRESENTE reali.
    """
    data_ref = data_ref or date.today()
    try:
        start, end = week_start_end(data_ref)
    except Exception:
        start = data_ref - timedelta(days=data_ref.weekday())
        end = start + timedelta(days=6)

    accessi = enrich_accessi_with_cliente(load_accessi_tornello())
    if accessi.empty or "cliente_id" not in accessi.columns:
        return set()

    tmp = accessi.copy()
    tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
    tmp = tmp[
        (tmp["cliente_id_num"] == int(cliente_id)) &
        (tmp["data_accesso"].astype(str) >= str(start)) &
        (tmp["data_accesso"].astype(str) <= str(end))
    ]

    if tmp.empty:
        return set()

    # Escludo accessi chiaramente negati, ma tengo REGISTRATO/REGISTRATO_ASSOCIATO
    if "stato_accesso" in tmp.columns:
        tmp["stato_norm"] = tmp["stato_accesso"].apply(normalize_status_text)
        tmp = tmp[~tmp["stato_norm"].str.contains("NEGATO", na=False)]

    return set(tmp["data_accesso"].astype(str).tolist())


def cliente_weekly_present_lessons(cliente_id, data_ref=None):
    """
    Conta lezioni PRESENTE da calendario nella settimana.
    Ritorna sia conteggio sia giorni.
    """
    data_ref = data_ref or date.today()
    try:
        start, end = week_start_end(data_ref)
    except Exception:
        start = data_ref - timedelta(days=data_ref.weekday())
        end = start + timedelta(days=6)

    lezioni = load_lezioni()
    if lezioni.empty:
        return 0, set()

    tmp = lezioni.copy()
    tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
    tmp["stato_norm"] = tmp["stato"].apply(normalize_status_text)

    tmp = tmp[
        (tmp["cliente_id_num"] == int(cliente_id)) &
        (tmp["data_lezione"].astype(str) >= str(start)) &
        (tmp["data_lezione"].astype(str) <= str(end)) &
        (tmp["stato_norm"] == "PRESENTE")
    ]

    if tmp.empty:
        return 0, set()

    return len(tmp), set(tmp["data_lezione"].astype(str).tolist())


def contatori_cumulativi_cliente(cliente_id, pacchetto=None, data_ref=None):
    """
    Conta reale robusto:
    - usa lezioni PRESENTE se presenti;
    - integra con accessi tornello associati;
    - per Luxury/Gold/VIP/Coaching totale = 3 non cumulabile;
    - per personalizzati totale = anagrafica.
    """
    data_ref = data_ref or date.today()
    if pacchetto is None:
        c = get_cliente(int(cliente_id))
        pacchetto = c.get("pacchetto", "") if c else ""

    lez_count, lez_days = cliente_weekly_present_lessons(cliente_id, data_ref)
    access_days = cliente_weekly_access_dates(cliente_id, data_ref)

    # Se una giornata ha accesso ma non lezione PRESENTE, la considero comunque presenza utile.
    merged_days = set(lez_days) | set(access_days)
    used = max(int(lez_count), len(merged_days))

    if is_weekly_quota_package_app(pacchetto):
        totale = 3
        usate = min(used, 3)
        residue = max(3 - usate, 0)
        extra = max(used - 3, 0)
        return totale, usate, residue, extra

    try:
        c = get_cliente(int(cliente_id))
        totale = int(float(c.get("numero_lezioni") or c.get("numero_lezioni_totali") or 0)) if c else 0
    except Exception:
        totale = 0

    usate = int(used)
    residue = max(totale - usate, 0) if totale > 0 else 0
    extra = max(usate - totale, 0) if totale > 0 else 0
    return totale, usate, residue, extra


def ricalcola_contatori_settimanali_clienti_robust(data_ref=None):
    data_ref = data_ref or date.today()
    clienti = load_clienti()
    sb = get_supabase()

    if clienti.empty:
        return {"aggiornati": 0, "saltati": 0}

    updated = 0
    skipped = 0

    for _, c in clienti.iterrows():
        try:
            cid = int(c.get("id"))
            pac = c.get("pacchetto", "")
            totale, usate, residue, extra = contatori_cumulativi_cliente(cid, pac, data_ref)

            # aggiorno tutti: standard e personalizzati, così la tabella resta coerente
            ok_update, _msg_update = safe_update_cliente_contatori(cid, totale, usate, residue)
            if ok_update:
                updated += 1
            else:
                skipped += 1
        except Exception:
            skipped += 1

    return {"aggiornati": updated, "saltati": skipped}


def dataframe_clienti_con_contatori_cumulativi(df, data_ref=None):
    if df.empty:
        return df

    out = df.copy()
    for col in ["numero_lezioni", "lezioni_utilizzate", "lezioni_residue"]:
        if col not in out.columns:
            out[col] = 0

    for idx, row in out.iterrows():
        try:
            cid = int(row.get("id"))
            pac = row.get("pacchetto", "")
            totale, usate, residue, extra = contatori_cumulativi_cliente(cid, pac, data_ref or date.today())
            out.at[idx, "numero_lezioni"] = totale
            out.at[idx, "lezioni_utilizzate"] = usate
            out.at[idx, "lezioni_residue"] = residue
        except Exception:
            continue

    return out


def render_diagnostica_contatori_cliente():
    st.markdown("### Diagnostica contatori")
    st.caption("Mostra da dove arrivano le presenze: calendario e accessi tornello.")

    clienti = load_clienti()
    if clienti.empty:
        st.info("Nessun cliente.")
        return

    labels = (clienti["id"].astype(str) + " - " + clienti["nome"].fillna("").astype(str) + " " + clienti["cognome"].fillna("").astype(str)).tolist()
    selected = st.selectbox("Cliente", labels, key="diag_contatore_cliente")
    cid = int(selected.split(" - ")[0])
    data_ref = st.date_input("Settimana", value=date.today(), format="DD/MM/YYYY", key="diag_contatore_data")

    c = get_cliente(cid)
    pac = c.get("pacchetto", "") if c else ""

    lez_count, lez_days = cliente_weekly_present_lessons(cid, data_ref)
    access_days = cliente_weekly_access_dates(cid, data_ref)
    totale, usate, residue, extra = contatori_cumulativi_cliente(cid, pac, data_ref)

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Totale settimana", totale)
    c2.metric("Usate", usate)
    c3.metric("Residue", residue)
    c4.metric("Extra", extra)

    st.write("Giorni con lezioni PRESENTE:", sorted(list(lez_days)))
    st.write("Giorni con accessi tornello:", sorted(list(access_days)))

    if st.button("🔧 Aggiorna questo cliente", key="diag_update_one"):
        ok_update, msg_update = safe_update_cliente_contatori(cid, totale, usate, residue)
        if ok_update:
            st.success(msg_update)
            st.rerun()
        else:
            st.error(msg_update)


def contatori_cumulativi_cliente(cliente_id, pacchetto=None, data_ref=None):
    """
    Fonte vera: tabella lezioni.
    Per pacchetti Luxury/Gold/VIP/Coaching:
    - totale settimana = 3
    - usate = lezioni PRESENTE nella settimana corrente
    - residue = max(3 - usate, 0)
    - non cumulabili
    """
    data_ref = data_ref or date.today()

    try:
        start, end = week_start_end(data_ref)
    except Exception:
        start = data_ref - timedelta(days=data_ref.weekday())
        end = start + timedelta(days=6)

    try:
        lezioni = load_lezioni()
    except Exception:
        lezioni = pd.DataFrame()

    used = 0
    if not lezioni.empty:
        tmp = lezioni.copy()
        tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
        tmp = tmp[
            (tmp["cliente_id_num"] == int(cliente_id)) &
            (tmp["data_lezione"].astype(str) >= str(start)) &
            (tmp["data_lezione"].astype(str) <= str(end)) &
            (tmp["stato"].astype(str).str.upper() == "PRESENTE")
        ]
        used = len(tmp)

    if pacchetto is None:
        try:
            c = get_cliente(int(cliente_id))
            pacchetto = c.get("pacchetto", "") if c else ""
        except Exception:
            pacchetto = ""

    if is_weekly_quota_package_app(pacchetto):
        totale = 3
        usate = min(int(used), 3)
        residue = max(totale - usate, 0)
        extra = max(int(used) - 3, 0)
        return totale, usate, residue, extra

    # pacchetti personalizzati: usa anagrafica come totale, ma usate da lezioni PRESENTE
    try:
        c = get_cliente(int(cliente_id))
        totale = int(float(c.get("numero_lezioni") or c.get("numero_lezioni_totali") or 0)) if c else 0
    except Exception:
        totale = 0

    usate = int(used)
    residue = max(totale - usate, 0) if totale > 0 else 0
    extra = max(usate - totale, 0) if totale > 0 else 0
    return totale, usate, residue, extra


def dataframe_clienti_con_contatori_cumulativi(df):
    """
    Aggiorna la tabella visualizzata dei clienti con contatori reali da calendario.
    """
    if df.empty:
        return df

    out = df.copy()
    for col in ["numero_lezioni", "lezioni_utilizzate", "lezioni_residue"]:
        if col not in out.columns:
            out[col] = 0

    for idx, row in out.iterrows():
        try:
            cid = int(row.get("id"))
            pac = row.get("pacchetto", "")
            totale, usate, residue, extra = contatori_cumulativi_cliente(cid, pac)
            out.at[idx, "numero_lezioni"] = totale
            out.at[idx, "lezioni_utilizzate"] = usate
            out.at[idx, "lezioni_residue"] = residue
            if "lezioni_extra_settimana" in out.columns:
                out.at[idx, "lezioni_extra_settimana"] = extra
        except Exception:
            continue

    return out



def kreo_beep_html():
    """
    Suono browser semplice, senza file esterni.
    Viene attivato quando la pagina si carica e c'è almeno un alert live.
    """
    return """
    <script>
    try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        const ctx = new AudioContext();
        function beep(freq, duration, delay) {
            setTimeout(() => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.frequency.value = freq;
                osc.type = "sine";
                gain.gain.setValueAtTime(0.001, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.35, ctx.currentTime + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration / 1000);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + duration / 1000);
            }, delay);
        }
        beep(880, 220, 0);
        beep(660, 220, 280);
        beep(880, 220, 560);
    } catch(e) {}
    </script>
    """


def get_recent_accessi(minutes=10):
    accessi = enrich_accessi_with_cliente(load_accessi_tornello())
    if accessi.empty:
        return accessi

    df = accessi.copy()
    if "created_at" not in df.columns:
        return df.head(20)

    try:
        df["created_dt"] = pd.to_datetime(df["created_at"], errors="coerce")
        cutoff = pd.Timestamp.now(tz=None) - pd.Timedelta(minutes=int(minutes))
        # se timezone mismatch, fallback ultimi record
        recent = df[df["created_dt"].dt.tz_localize(None) >= cutoff]
        if recent.empty:
            return df.sort_values("id", ascending=False).head(20)
        return recent.sort_values("created_dt", ascending=False)
    except Exception:
        return df.sort_values("id", ascending=False).head(20)


def accesso_alerts_for_row(row):
    """
    Genera alert live usando:
    - stato accesso PerfectGym/KREO
    - cliente associato
    - certificato
    - residuo economico
    - lezioni residue settimanali
    """
    alerts = []
    cid = row.get("cliente_id")

    stato_accesso = str(row.get("stato_accesso") or "").upper()
    if "NEGATO" in stato_accesso or "VERIFICARE" in stato_accesso or "EXTRA" in stato_accesso:
        alerts.append(("ALTA", "Accesso da verificare", f"Stato accesso: {row.get('stato_accesso')}"))

    if cid in [None, "", "None"] or pd.isna(cid):
        alerts.append(("ALTA", "Badge non associato", f"Badge/ID {row.get('badge_uid')} non collegato a nessun cliente KREO."))
        return alerts

    try:
        cliente = get_cliente(int(cid))
    except Exception:
        cliente = None

    if not cliente:
        alerts.append(("ALTA", "Cliente non trovato", f"cliente_id {cid} non presente in anagrafica."))
        return alerts

    nome_cliente = f"{cliente.get('nome','')} {cliente.get('cognome','')}".strip()

    # certificato
    cert = str(cliente.get("certificato_medico", cliente.get("certificato_medico_consegnato", "")) or "").upper()
    if cert not in ["SI", "SÌ", "YES", "OK"]:
        alerts.append(("ALTA", "Certificato medico mancante", f"{nome_cliente}: certificato medico non consegnato/non valido."))

    # residuo economico
    try:
        residuo = float(cliente.get("residuo") or cliente.get("residuo_pagamento") or 0)
    except Exception:
        try:
            importo = float(cliente.get("importo") or 0)
            pagato = float(cliente.get("importo_pagato") or 0)
            residuo = max(importo - pagato, 0)
        except Exception:
            residuo = 0

    if residuo > 0.01:
        alerts.append(("MEDIA", "Residuo economico aperto", f"{nome_cliente}: residuo € {residuo:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")))

    # lezioni residue settimanali
    try:
        data_ref = row.get("data_accesso") or date.today()
        totale, usate, residue, extra = contatori_cumulativi_cliente(int(cid), cliente.get("pacchetto", ""), parse_date(data_ref, date.today()))
        if is_weekly_quota_package_app(cliente.get("pacchetto", "")):
            if residue <= 0:
                alerts.append(("ALTA", "Lezioni settimanali esaurite", f"{nome_cliente}: {usate}/{totale} lezioni usate questa settimana."))
            if extra > 0:
                alerts.append(("ALTA", "Accesso extra oltre quota", f"{nome_cliente}: extra settimana = {extra}."))
    except Exception:
        pass

    return alerts


def build_alert_accessi_live(minutes=30):
    recent = get_recent_accessi(minutes)
    if recent.empty:
        return pd.DataFrame()

    rows = []
    for _, r in recent.iterrows():
        alerts = accesso_alerts_for_row(r)
        if not alerts:
            continue

        cliente_label = r.get("cliente", "")
        if not cliente_label or str(cliente_label) == "nan":
            cid = r.get("cliente_id")
            if cid not in [None, "", "None"] and not pd.isna(cid):
                try:
                    c = get_cliente(int(cid))
                    cliente_label = f"{c.get('nome','')} {c.get('cognome','')}".strip() if c else ""
                except Exception:
                    cliente_label = ""

        for priorita, tipo, msg in alerts:
            rows.append({
                "priorita": priorita,
                "tipo_alert": tipo,
                "messaggio": msg,
                "cliente": cliente_label or "NON ASSOCIATO",
                "badge_uid": r.get("badge_uid", ""),
                "data_accesso": r.get("data_accesso", ""),
                "ora_accesso": r.get("ora_accesso", ""),
                "stato_accesso": r.get("stato_accesso", ""),
                "accesso_id": r.get("id", ""),
            })

    return pd.DataFrame(rows)


def render_alert_accessi_live_widget():
    st.subheader("Alert accessi live")
    st.caption("Controllo immediato sugli accessi recenti: lezioni esaurite, certificato, residuo, badge non associati.")

    c1, c2, c3 = st.columns([1,1,2])
    with c1:
        minutes = st.number_input("Minuti da controllare", min_value=5, max_value=240, value=60, step=5)
    with c2:
        sound_enabled = st.checkbox("Suono alert", value=True)
    with c3:
        auto_refresh = st.checkbox("Auto-refresh 15 sec", value=False)

    alerts = build_alert_accessi_live(minutes)

    if alerts.empty:
        st.success("Nessun alert sugli accessi recenti.")
    else:
        alte = len(alerts[alerts["priorita"] == "ALTA"]) if "priorita" in alerts.columns else 0
        medie = len(alerts[alerts["priorita"] == "MEDIA"]) if "priorita" in alerts.columns else 0

        k1, k2, k3 = st.columns(3)
        k1.metric("Alert totali", len(alerts))
        k2.metric("Priorità alta", alte)
        k3.metric("Priorità media", medie)

        if sound_enabled and alte > 0:
            st.components.v1.html(kreo_beep_html(), height=0)

        st.error("⚠️ Ci sono accessi da verificare.")
        st.dataframe(alerts, use_container_width=True, hide_index=True)

    if auto_refresh:
        st.markdown("""
        <script>
        setTimeout(function(){ window.location.reload(); }, 15000);
        </script>
        """, unsafe_allow_html=True)


def render_accessi_live_dashboard():
    st.subheader("Dashboard accessi live")
    st.caption("Vista operativa per reception/staff.")

    recent = get_recent_accessi(240)
