def annulla_accesso_e_presenza(accesso_id, motivo="Annullamento manuale da KREO"):
    """
    Annulla accesso/presenza usando il motore unico.
    Marca l'accesso come ANNULLATO_DA_NON_RICALCOLARE e restituisce una lezione solo se trova presenza collegata.
    """
    try:
        sb = get_supabase()
        rows = sb.table("accessi_tornello").select("*").eq("id", int(accesso_id)).limit(1).execute().data or []
        if not rows:
            return False, "Accesso non trovato."
        accesso = rows[0]
        cliente_id = accesso.get("cliente_id")
        if cliente_id in [None, "", "nan"]:
            sb.table("accessi_tornello").update({
                "stato_accesso": "ANNULLATO_DA_NON_RICALCOLARE",
                "note": f"ANNULLATO: {motivo}"
            }).eq("id", int(accesso_id)).execute()
            return True, "Accesso annullato. Nessun cliente/presenza collegata."
        return kreo_gestisci_presenza(
            cliente_id=cliente_id,
            accesso_id=accesso_id,
            accesso_row=accesso,
            azione="RIMUOVI",
            consuma_lezione=True,
            motivo=motivo,
            source="Annullamento accesso"
        )
    except Exception as e:
        return False, f"Errore annullamento accesso/presenza: {e}"

