def kreo_autorizza_presenza_extra(accesso_row=None):
    st.markdown("### ✅ Autorizza presenza / extra")
    st.caption("Unica logica: scegli se l’autorizzazione deve scalare o non scalare una lezione.")

    try:
        accessi = enrich_accessi_with_cliente(load_accessi_tornello())
    except Exception:
        accessi = pd.DataFrame()

    if accessi.empty:
        st.info("Nessun accesso disponibile.")
        return

    try:
        accessi["id_num"] = pd.to_numeric(accessi["id"], errors="coerce").fillna(0).astype(int)
        accessi = accessi.sort_values("id_num", ascending=False)
    except Exception:
        pass

    labels = []
    row_by_label = {}
    for _, r in accessi.head(20).iterrows():
        label = kreo_accesso_label_umano(r)
        labels.append(label)
        row_by_label[label] = r.to_dict()

    selected = st.selectbox("Accesso/badge da gestire", labels, key="extra_accesso_select")
    row = row_by_label.get(selected, {})
    resolved = kreo_resolve_access_client_row(row)

    cliente_id = resolved.get("cliente_id")
    cliente = resolved.get("cliente") or kreo_cliente_nome_by_id_safe(cliente_id) or "Cliente non associato"
    badge = resolved.get("badge_uid") or "-"
    accesso_id = resolved.get("id")

    motivi = [
        "Recupero lezione autorizzato - scala 1 lezione",
        "Presenza valida autorizzata - scala 1 lezione",
        "Prova / ingresso omaggio - non scala",
        "Errore lettura badge / PerfectGym - non scala",
        "Cliente autorizzato dalla direzione - non scala",
        "Altro - non scala"
    ]
    motivo = st.selectbox("Motivazione", motivi, key="extra_motivo_select")
    consuma = ("SCALA" in motivo.upper()) and ("NON SCALA" not in motivo.upper())
    if consuma:
        st.warning("Questa autorizzazione scalerà 1 lezione.")
    else:
        st.info("Questa autorizzazione NON scalerà lezioni.")

    nota = st.text_area("Nota interna", value=f"Autorizzazione per {cliente} - badge {badge}. Motivo: {motivo}", key="extra_nota_text")

    st.markdown(
        f"""
        <div style="border:1.5px solid #2ecc71;background:#f3fff7;border-radius:16px;padding:14px 16px;margin:10px 0;">
            <div style="font-size:18px;font-weight:950;">{cliente}</div>
            <div style="font-size:12px;color:#444;">Badge: {badge} · Accesso ID: {accesso_id}</div>
        </div>
        """,
        unsafe_allow_html=True
    )

    if st.button("✅ Conferma autorizzazione", use_container_width=True, key="btn_autorizza_presenza_extra"):
        if cliente_id in [None, "", "nan"]:
            st.error("Cliente non associato: prima associa il badge al cliente.")
            return
        ok, msg = kreo_gestisci_presenza(
            cliente_id=cliente_id,
            accesso_id=accesso_id,
            accesso_row=resolved,
            azione="CONFERMA",
            consuma_lezione=consuma,
            motivo=nota,
            source="Autorizzazione Reception"
        )
        if ok:
            st.success(msg)
            st.rerun()
        else:
            st.error(msg)

