def kreo_call_first_available(function_names, friendly_name):
    """
    Chiama la prima funzione esistente tra più nomi possibili.
    Evita NameError tra admin/staff e versioni storiche del codice.
    """
    for fn_name in function_names:
        fn = globals().get(fn_name)
        if callable(fn):
            fn()
            return True

    st.warning(f"Modulo '{friendly_name}' non disponibile in questa build.")
    st.caption("La vista non è stata aperta perché la funzione tecnica collegata non è presente con il nome atteso.")
    return False


def kreo_render_reception_internal_view_if_any():
    """
    Router interno Reception ultra-difensivo.
    Permette allo staff di usare i pulsanti senza mandare in crash l'app.
    """
    view = st.session_state.get("reception_internal_view")
    if not view:
        return False

    if view == "v36_checkin":
        render_v36_checkin_core()
        return True

    if st.button("⬅️ Torna alla Reception", key=f"reception_internal_back_{view}"):
        kreo_reception_go_home()

    if view == "nuovo_cliente":
        kreo_call_first_available(
            [
                "render_nuovo_cliente",
                "render_nuovo_cliente_page",
                "render_crea_cliente",
                "render_creazione_cliente",
                "render_clienti_page",
                "render_database_clienti",
            ],
            "Nuovo cliente"
        )
        return True

    if view == "modifica_cliente":
        render_staff_modifica_cliente()
        return True

    if view == "incasso":
        render_staff_incasso()
        return True

    if view == "tornello":
        kreo_call_first_available(
            [
                "render_accessi_tornello_operativo_page",
                "render_checkin_center",
                "render_tornello",
                "render_accessi_tornello",
            ],
            "Accesso tornello"
        )
        return True

    if view == "agenda":
        kreo_call_first_available(
            [
                "render_agenda_light_launch",
                "render_agenda_luxury",
                "render_agenda",
                "render_calendario_unificato_staff",
            ],
            "Agenda"
        )
        return True

    if view == "ricevuta":
        render_staff_ricevuta()
        return True

    if view == "messaggio":
        render_staff_messaggio_cliente()
        return True

    if view == "cliente_360":
        kreo_call_first_available(
            [
                "render_cliente_360_page",
                "render_clienti_page",
                "render_database_clienti",
            ],
            "Cliente 360"
        )
        return True

    if view == "alert_center":
        kreo_call_first_available(
            [
                "render_alert_center_page",
                "render_reception_alert_side_panel",
            ],
            "Alert Center"
        )
        return True

    st.warning(f"Vista Reception non riconosciuta: {view}")
    return True



# ============================================================
# KREO V36 CORE STABLE
# Accessi -> Presenze -> Ledger lezioni
# ============================================================

def v36_sb():
    try:
        return get_supabase()
    except Exception:
        try:
            return supabase
        except Exception as e:
            raise RuntimeError(f"Supabase non disponibile: {e}")


def v36_now_iso():
    try:
        return now_iso()
    except Exception:
        return datetime.now().isoformat()


def v36_user_label():
    try:
        return user_label()
    except Exception:
        return str(st.session_state.get("username") or st.session_state.get("user") or "KREO")


def v36_is_personalizzato(pacchetto):
    return "PERSONALIZZATO" in str(pacchetto or "").upper()


def v36_is_standard_cumulativo(pacchetto):
    p = str(pacchetto or "").upper()
    if "PERSONALIZZATO" in p:
        return False
    return any(x in p for x in ["LUXURY", "GOLD", "VIP", "COACHING"])


def v36_cliente_by_id(cliente_id):
    try:
        if cliente_id in [None, "", "nan"]:
            return {}
        try:
            c = get_cliente(int(float(cliente_id)))
            if c:
                return c
        except Exception:
            pass
        res = v36_sb().table("clienti").select("*").eq("id", int(float(cliente_id))).limit(1).execute()
        rows = res.data or []
        return rows[0] if rows else {}
    except Exception:
        return {}


def v36_cliente_nome(cliente):
    if not cliente:
        return ""
    return (f"{cliente.get('nome','')} {cliente.get('cognome','')}".strip()
            or str(cliente.get("cliente") or cliente.get("ragione_sociale") or ""))


def v36_cliente_by_badge(badge_uid):
    badge = str(badge_uid or "").strip()
    if not badge:
        return None, {}
    for table in ["badge_clienti", "clienti_badge", "badge"]:
        for col in ["badge_uid", "badge", "codice_badge", "uid"]:
            try:
                res = v36_sb().table(table).select("*").eq(col, badge).limit(1).execute()
                rows = res.data or []
                if rows:
                    cid = rows[0].get("cliente_id") or rows[0].get("id_cliente")
                    return cid, v36_cliente_by_id(cid)
            except Exception:
                pass
    try:
        clienti = load_clienti()
        if clienti is not None and not clienti.empty:
            for col in ["badge_uid", "badge", "codice_badge", "id_badge", "tessera", "codice_tessera"]:
                if col in clienti.columns:
                    sub = clienti[clienti[col].fillna("").astype(str).str.strip() == badge]
                    if not sub.empty:
                        row = sub.iloc[0].to_dict()
                        return row.get("id"), row
    except Exception:
        pass
    return None, {}


def v36_accesso_status(accesso):
    stato = str(accesso.get("stato_accesso") or accesso.get("stato") or "").upper()
    no_accesso = str(accesso.get("no_accesso") or accesso.get("No_accesso") or "").upper()
    if "ANNULL" in stato:
        return "ANNULLATO"
    if "NEGATO" in stato or "VERIFICARE" in stato or no_accesso in ["1", "TRUE", "SI", "SÌ", "YES"]:
        return "DA_VERIFICARE"
    if "OK" in stato or "REGISTRATO" in stato or "ASSOCIATO" in stato:
        return "OK"
    return "DA_VERIFICARE"


def v36_registra_ledger(cliente_id, delta, tipo, motivo="", accesso_id=None, lezione_id=None, note=""):
    payload = {
        "cliente_id": int(float(cliente_id)) if cliente_id not in [None, "", "nan"] else None,
        "tipo": str(tipo or "").upper(),
        "quantita": abs(int(delta or 0)),
        "delta": int(delta or 0),
        "motivo": motivo or "",
        "accesso_id": accesso_id,
        "lezione_id": lezione_id,
        "note": note or "",
        "created_by": v36_user_label(),
        "created_at": v36_now_iso(),
    }
    try:
        v36_sb().table("movimenti_lezioni").insert(payload).execute()
        return True, "Movimento registrato nel ledger."
    except Exception:
        try:
            v36_sb().table("cronologia").insert({
                "cliente_id": payload["cliente_id"],
                "azione": f"LEDGER_{payload['tipo']}",
                "dettaglio": f"delta={payload['delta']} | {payload['motivo']} | accesso_id={accesso_id}",
                "created_at": v36_now_iso(),
            }).execute()
            return True, "Movimento registrato in cronologia."
        except Exception as e:
            return False, f"Movimento non salvato: {e}"


def v36_ledger_cliente(cliente_id):
    try:
        res = v36_sb().table("movimenti_lezioni").select("*").eq("cliente_id", int(float(cliente_id))).order("created_at", desc=False).execute()
        return pd.DataFrame(res.data or [])
    except Exception:
        return pd.DataFrame()


def v36_maturazioni_standard(cliente_id, cliente=None, data_ref=None):
    cliente = cliente or v36_cliente_by_id(cliente_id)
    if not cliente:
        return 0
    pac = cliente.get("pacchetto", "")
    if v36_is_personalizzato(pac):
        return None
    if not v36_is_standard_cumulativo(pac):
        return None
    data_ref = data_ref or date.today()
    start = None
    for k in ["data_inizio_pacchetto", "data_iscrizione", "created_at"]:
        v = cliente.get(k)
        if v not in [None, "", "nan"]:
            try:
                start = pd.to_datetime(v, errors="coerce").date()
                if start:
                    break
            except Exception:
                pass
    if not start:
        start = date.today()
    start_monday = start - timedelta(days=start.weekday())
    ref_monday = data_ref - timedelta(days=data_ref.weekday())
    weeks = max(((ref_monday - start_monday).days // 7) + 1, 1)
    return int(weeks * 3)


def v36_saldo_lezioni(cliente_id):
    cliente = v36_cliente_by_id(cliente_id)
    if not cliente:
        return {"totale": 0, "usate": 0, "residue": 0, "manuale": True}
    if v36_is_personalizzato(cliente.get("pacchetto", "")):
        totale = int(float(cliente.get("numero_lezioni") or 0))
        residue = int(float(cliente.get("lezioni_residue") or 0))
        usate = int(float(cliente.get("lezioni_utilizzate") or max(totale - residue, 0)))
        return {"totale": totale, "usate": usate, "residue": residue, "manuale": True}

    maturate = v36_maturazioni_standard(cliente_id, cliente)
    if maturate is None:
        maturate = int(float(cliente.get("numero_lezioni") or 0))

    ledger = v36_ledger_cliente(cliente_id)
    delta = 0
    if ledger is not None and not ledger.empty:
        if "delta" in ledger.columns:
            delta = int(pd.to_numeric(ledger["delta"], errors="coerce").fillna(0).sum())
        else:
            for _, r in ledger.iterrows():
                tipo = str(r.get("tipo") or "").upper()
                q = int(float(r.get("quantita") or 1))
                if any(k in tipo for k in ["SCALA", "PRESENZA", "RECUPERO", "UTILIZZO"]):
                    delta -= q
                elif any(k in tipo for k in ["RESTITUISCI", "ANNULLA", "RIMOSSA", "BONUS", "ACQUISTO"]):
                    delta += q
    residue = max(int(maturate) + int(delta), 0)
    usate = max(int(maturate) - residue, 0)
    return {"totale": int(maturate), "usate": int(usate), "residue": int(residue), "manuale": False}


def v36_aggiorna_saldo_cliente(cliente_id):
    cliente = v36_cliente_by_id(cliente_id)
    if not cliente or v36_is_personalizzato(cliente.get("pacchetto", "")):
        return True
    saldo = v36_saldo_lezioni(cliente_id)
    try:
        v36_sb().table("clienti").update({
            "numero_lezioni": saldo["totale"],
            "lezioni_utilizzate": saldo["usate"],
            "lezioni_residue": saldo["residue"],
            "updated_at": v36_now_iso(),
        }).eq("id", int(float(cliente_id))).execute()
        try:
            st.cache_data.clear()
        except Exception:
            pass
        return True
    except Exception:
        return False



def kreo_ledger_delta_cliente(cliente_id):
    """
    Somma i movimenti lezione in modo robusto.
    Supporta sia colonna delta sia vecchia struttura tipo/quantita.
    SCALA/PRESENZA = -1
    RESTITUISCI/RIMOSSA/BONUS/ACQUISTO = +1
    """
    try:
        sb = get_supabase()
        rows = sb.table("movimenti_lezioni").select("*").eq("cliente_id", int(float(cliente_id))).execute().data or []
        total = 0
        for r in rows:
            # Se delta esiste e non è vuoto, è la fonte più chiara.
            if r.get("delta") not in [None, "", "nan"]:
                try:
                    total += int(float(r.get("delta") or 0))
                    continue
                except Exception:
                    pass

            tipo = str(r.get("tipo") or r.get("movimento") or "").upper()
            try:
                q = int(float(r.get("quantita") or r.get("numero_lezioni") or 1))
            except Exception:
                q = 1

            if any(k in tipo for k in ["RESTITUISCI", "RIMOSSA", "RIMOZIONE", "BONUS", "AGGIUNTA", "ACQUISTO"]):
                total += q
            elif any(k in tipo for k in ["SCALA", "PRESENZA", "RECUPERO", "UTILIZZO"]):
                total -= q
        return int(total)
    except Exception:
        return 0


def kreo_recalcola_contatori_ledger_cliente(cliente_id):
    """
    Aggiorna numero_lezioni / lezioni_utilizzate / lezioni_residue usando il ledger come verità.
    È il fix del caso: autorizzo presenza ma il residuo non cambia.
    """
    try:
        cliente = get_cliente(int(float(cliente_id)))
        if not cliente:
            return False, "Cliente non trovato."

        pac = cliente.get("pacchetto", "")

        if "is_pacchetto_settimanale_kreo" in globals() and is_pacchetto_settimanale_kreo(pac):
            totale = lezioni_maturate_cumulative(cliente, date.today())
        else:
            try:
                totale = int(float(cliente.get("numero_lezioni") or cliente.get("numero_lezioni_totali") or 0))
            except Exception:
                totale = 0

        delta = kreo_ledger_delta_cliente(cliente_id)
        residue = max(int(totale) + int(delta), 0)
        usate = max(int(totale) - int(residue), 0)

        if "safe_update_cliente_contatori" in globals():
            ok, _ = safe_update_cliente_contatori(int(float(cliente_id)), totale, usate, residue)
            if ok:
                try:
                    st.cache_data.clear()
                except Exception:
                    pass
                return True, f"Contatori aggiornati da ledger: {usate}/{totale}, residue {residue}"

        sb = get_supabase()
        sb.table("clienti").update({
            "numero_lezioni": int(totale),
            "lezioni_utilizzate": int(usate),
            "lezioni_residue": int(residue),
            "updated_at": now_iso(),
        }).eq("id", int(float(cliente_id))).execute()

        try:
            st.cache_data.clear()
        except Exception:
            pass
        return True, f"Contatori aggiornati da ledger: {usate}/{totale}, residue {residue}"
    except Exception as e:
        return False, f"Errore ricalcolo ledger cliente: {e}"


def v36_registra_presenza(cliente_id, accesso_id=None, tipo_presenza="PRESENZA_VALIDA", scala_lezione=True, motivo="", note=""):
    """
    V37.05: registra la presenza da accesso con anti-duplicato.
    Un accesso badge può avere una sola decisione operativa.
    """
    try:
        motivo_finale = motivo or tipo_presenza or "Presenza autorizzata da Check-in V36"
        if accesso_id not in [None, "", "nan"]:
            return kreo_decidi_accesso_una_volta(
                cliente_id=cliente_id,
                accesso_id=accesso_id,
                scala_lezione=bool(scala_lezione),
                motivo=motivo_finale,
            )

        # presenza manuale senza badge: ammessa, ma senza accesso_id non applica anti-duplicato accesso
        delta = -1 if scala_lezione else 0
        tipo = "PRESENZA_MANUALE_SCALATA" if scala_lezione else "PRESENZA_MANUALE_NO_SCALA"
        if "v36_registra_ledger" in globals():
            v36_registra_ledger(cliente_id, delta, tipo, motivo=motivo_finale, accesso_id=None, note=note)
        else:
            get_supabase().table("movimenti_lezioni").insert({
                "cliente_id": int(float(cliente_id)),
                "delta": int(delta),
                "tipo": tipo,
                "motivo": motivo_finale,
                "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
            }).execute()
        ok_calc, msg_calc = kreo_ricalcola_cliente_dopo_click(cliente_id)
        return True, f"Presenza manuale registrata. {msg_calc}"
    except Exception as e:
        return False, f"Errore registrazione presenza V37.05: {e}"


def v36_annulla_accesso(cliente_id, accesso_id=None, motivo="Accesso annullato da Reception"):
    ok, msg = v36_registra_ledger(cliente_id, +1, "ANNULLA_RESTITUISCI", motivo=motivo, accesso_id=accesso_id)
    try:
        if accesso_id not in [None, "", "nan"]:
            v36_sb().table("accessi_tornello").update({
                "stato_accesso": "ANNULLATO_DA_NON_RICALCOLARE",
                "note": motivo,
            }).eq("id", int(float(accesso_id))).execute()
    except Exception:
        pass
    v36_aggiorna_saldo_cliente(cliente_id)
    return ok, msg


def v36_tipo_autorizzazione_ui(key_suffix=""):
    tipo = st.selectbox(
        "Tipo autorizzazione",
        [
            "Presenza valida - scala 1 lezione",
            "Recupero autorizzato - scala 1 lezione",
            "Extra omaggio / prova - non scala",
            "Errore tornello / verifica manuale - non scala",
            "Accesso tecnico / visita - non scala",
        ],
        key=f"v36_tipo_autorizzazione_{key_suffix}"
    )
    upper = tipo.upper()
    scala = ("SCALA" in upper) and ("NON SCALA" not in upper)
    if scala:
        st.warning("Questa scelta scalerà 1 lezione dal cliente.")
    else:
        st.info("Questa scelta non scalerà lezioni. Verrà solo tracciata.")
    return tipo, scala



# ============================================================
# KREO V37.05 - Presenze anti-duplicato / accesso chiuso
# ============================================================

KREO_ACCESSO_STATI_CHIUSI = [
    "PRESENZA_SCALATA",
    "PRESENZA_CONFERMATA_SCALA",
    "PRESENZA_VALIDA_SCALATA",
    "PRESENZA_NO_SCALA",
    "PRESENZA_AUTORIZZATA_NO_SCALA",
    "ANNULLATO",
]

def kreo_norm_status(value):
    return str(value or "").strip().upper().replace(" ", "_")

def kreo_accesso_is_chiuso(accesso):
    stato = kreo_norm_status(accesso.get("stato_accesso") or accesso.get("stato") or "")
    return any(s in stato for s in KREO_ACCESSO_STATI_CHIUSI)

def kreo_get_accesso(accesso_id):
    try:
        if accesso_id in [None, "", "nan"]:
            return {}
        rows = get_supabase().table("accessi_tornello").select("*").eq("id", int(float(accesso_id))).limit(1).execute().data or []
        return rows[0] if rows else {}
    except Exception:
        return {}

def kreo_movimenti_accesso(accesso_id, cliente_id=None):
    try:
        if accesso_id in [None, "", "nan"]:
            return []
        q = get_supabase().table("movimenti_lezioni").select("*").eq("accesso_id", int(float(accesso_id)))
        if cliente_id not in [None, "", "nan"]:
            q = q.eq("cliente_id", int(float(cliente_id)))
        return q.execute().data or []
    except Exception:
        return []

def kreo_accesso_has_scala(accesso_id, cliente_id=None):
    rows = kreo_movimenti_accesso(accesso_id, cliente_id)
    for r in rows:
        delta = r.get("delta")
        if delta not in [None, "", "nan"]:
            try:
                if int(float(delta)) < 0:
                    return True
            except Exception:
                pass
        tipo = kreo_norm_status(r.get("tipo") or r.get("movimento") or "")
        if any(k in tipo for k in ["SCALA", "PRESENZA", "RECUPERO", "UTILIZZO"]) and not any(k in tipo for k in ["NO_SCALA", "RESTITUISCI", "ANNULLA", "RIMOSSA"]):
            return True
    return False

def kreo_accesso_has_decisione(accesso_id, cliente_id=None):
    accesso = kreo_get_accesso(accesso_id)
    if accesso and kreo_accesso_is_chiuso(accesso):
        return True
    rows = kreo_movimenti_accesso(accesso_id, cliente_id)
    return bool(rows)

def kreo_update_accesso_stato(accesso_id, stato, note=""):
    try:
        payload = {"stato_accesso": stato}
        if note is not None:
            payload["note"] = note
        get_supabase().table("accessi_tornello").update(payload).eq("id", int(float(accesso_id))).execute()
        return True
    except Exception:
        return False

def kreo_registra_movimento_unico_accesso(cliente_id, accesso_id, delta, tipo, motivo=""):
    """
    Registra al massimo un movimento operativo per accesso.
    Se il movimento esiste già, non duplica.
    """
    try:
        rows = kreo_movimenti_accesso(accesso_id, cliente_id)
        # Se esiste già un movimento decisionale per questo accesso, blocca.
        for r in rows:
            tipo_old = kreo_norm_status(r.get("tipo") or r.get("movimento") or "")
            if any(k in tipo_old for k in ["SCALA", "PRESENZA", "NO_SCALA", "ANNULLA", "RESTITUISCI"]):
                return False, "Questo accesso ha già una decisione registrata."

        payloads = [
            {
                "cliente_id": int(float(cliente_id)),
                "accesso_id": int(float(accesso_id)) if accesso_id not in [None, "", "nan"] else None,
                "delta": int(delta),
                "tipo": tipo,
                "motivo": motivo,
                "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
            },
            {
                "cliente_id": int(float(cliente_id)),
                "accesso_id": int(float(accesso_id)) if accesso_id not in [None, "", "nan"] else None,
                "quantita": abs(int(delta)) if int(delta) != 0 else 0,
                "tipo": tipo,
                "motivo": motivo,
                "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
            },
        ]
        last = None
        for p in payloads:
            try:
                get_supabase().table("movimenti_lezioni").insert(p).execute()
                return True, "Movimento registrato."
            except Exception as e:
                last = e
        return False, f"Errore registrazione movimento: {last}"
    except Exception as e:
        return False, f"Errore movimento unico: {e}"

def kreo_ricalcola_cliente_dopo_click(cliente_id):
    """
    Conseguenze da verificare dopo ogni click:
    1. ledger aggiornato
    2. lezioni residue aggiornate
    3. cache pulita
    """
    try:
        if "kreo_recalcola_contatori_ledger_cliente" in globals():
            ok, msg = kreo_recalcola_contatori_ledger_cliente(cliente_id)
        elif "v36_aggiorna_saldo_cliente" in globals():
            ok, msg = v36_aggiorna_saldo_cliente(cliente_id)
        else:
            ok, msg = True, "Ricalcolo non disponibile, movimento salvato."

        try:
            st.cache_data.clear()
        except Exception:
            pass
        return ok, msg
    except Exception as e:
        return False, f"Errore ricalcolo post-click: {e}"

def kreo_decidi_accesso_una_volta(cliente_id, accesso_id, scala_lezione=True, motivo=""):
    """
    Motore definitivo per click da Check-in:
    - blocca doppio click;
    - aggiorna accesso;
    - registra movimento unico;
    - ricalcola contatori.
    """
    accesso = kreo_get_accesso(accesso_id)
    if not accesso:
        return False, "Accesso non trovato."

    if kreo_accesso_has_decisione(accesso_id, cliente_id):
        return False, "Questo accesso è già stato gestito. Usa 'Correggi decisione' invece di autorizzare di nuovo."

    stato = "PRESENZA_SCALATA" if scala_lezione else "PRESENZA_NO_SCALA"
    delta = -1 if scala_lezione else 0
    tipo = "PRESENZA_SCALATA" if scala_lezione else "PRESENZA_NO_SCALA"

    ok_mov, msg_mov = kreo_registra_movimento_unico_accesso(cliente_id, accesso_id, delta, tipo, motivo)
    if not ok_mov:
        return False, msg_mov

    kreo_update_accesso_stato(accesso_id, stato, motivo)
    ok_calc, msg_calc = kreo_ricalcola_cliente_dopo_click(cliente_id)

    return True, f"{stato}. {msg_calc}"

def kreo_correggi_decisione_accesso(cliente_id, accesso_id, nuova_azione, motivo="Correzione decisione accesso"):
    """
    Corregge una decisione senza duplicare:
    - se prima aveva scalato e ora annulli/no scala => restituisce +1;
    - se prima non aveva scalato e ora scala => scala -1;
    - aggiorna lo stato accesso.
    """
    try:
        had_scala = kreo_accesso_has_scala(accesso_id, cliente_id)

        if nuova_azione == "ANNULLA":
            delta = 1 if had_scala else 0
            tipo = "CORREZIONE_ANNULLA_RESTITUISCI" if had_scala else "CORREZIONE_ANNULLA_NO_SCALA"
            stato = "ANNULLATO"
        elif nuova_azione == "NO_SCALA":
            delta = 1 if had_scala else 0
            tipo = "CORREZIONE_NO_SCALA_RESTITUISCI" if had_scala else "CORREZIONE_NO_SCALA"
            stato = "PRESENZA_NO_SCALA"
        elif nuova_azione == "SCALA":
            delta = 0 if had_scala else -1
            tipo = "CORREZIONE_SCALA_GIA_PRESENTE" if had_scala else "CORREZIONE_SCALA"
            stato = "PRESENZA_SCALATA"
        else:
            return False, "Azione correzione non valida."

        # La correzione può avere più righe, ma sempre dichiarate come correzione, non come nuova presenza.
        payloads = [
            {
                "cliente_id": int(float(cliente_id)),
                "accesso_id": int(float(accesso_id)),
                "delta": int(delta),
                "tipo": tipo,
                "motivo": motivo,
                "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
            },
            {
                "cliente_id": int(float(cliente_id)),
                "accesso_id": int(float(accesso_id)),
                "quantita": abs(int(delta)) if int(delta) != 0 else 0,
                "tipo": tipo,
                "motivo": motivo,
                "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
            },
        ]
        last = None
        for p in payloads:
            try:
                get_supabase().table("movimenti_lezioni").insert(p).execute()
                last = None
                break
            except Exception as e:
                last = e
        if last:
            return False, f"Errore salvataggio correzione: {last}"

        kreo_update_accesso_stato(accesso_id, stato, motivo)
        ok_calc, msg_calc = kreo_ricalcola_cliente_dopo_click(cliente_id)
        return True, f"Decisione corretta: {stato}. {msg_calc}"
    except Exception as e:
        return False, f"Errore correzione decisione: {e}"


def render_v36_checkin_core():
    st.header("🚦 Check-in / Tornello V36")
    st.caption("Il tornello genera eventi. KREO decide se trasformarli in presenza e se scalare una lezione.")

    try:
        accessi = enrich_accessi_with_cliente(load_accessi_tornello())
    except Exception:
        try:
            res = v36_sb().table("accessi_tornello").select("*").order("id", desc=True).limit(50).execute()
            accessi = pd.DataFrame(res.data or [])
        except Exception:
            accessi = pd.DataFrame()

    if accessi is None or accessi.empty:
        st.info("Nessun accesso rilevato.")
        return

    try:
        accessi["id_sort"] = pd.to_numeric(accessi["id"], errors="coerce").fillna(0).astype(int)
        accessi = accessi.sort_values("id_sort", ascending=False)
    except Exception:
        pass

    labels, rows = [], {}
    for _, r in accessi.head(25).iterrows():
        d = r.to_dict()
        badge = d.get("badge_uid") or d.get("badge") or ""
        cid = d.get("cliente_id")
        cliente = v36_cliente_by_id(cid) if cid not in [None, "", "nan"] else {}
        if not cliente and badge:
            cid, cliente = v36_cliente_by_badge(badge)
            if cid:
                d["cliente_id"] = cid
        nome = v36_cliente_nome(cliente) or "Badge non associato"
        label = f"{d.get('id','-')} | {d.get('data_accesso_it') or d.get('data_accesso') or '-'} {d.get('ora_accesso') or '-'} | {nome} | badge {badge}"
        labels.append(label)
        rows[label] = d

    selected = st.selectbox("Accesso da gestire", labels, key="v36_accesso_select")
    accesso = rows.get(selected, {})
    badge = accesso.get("badge_uid") or accesso.get("badge") or ""
    cliente_id = accesso.get("cliente_id")
    cliente = v36_cliente_by_id(cliente_id) if cliente_id else {}
    if not cliente and badge:
        cliente_id, cliente = v36_cliente_by_badge(badge)

    nome = v36_cliente_nome(cliente) or "Badge non associato"
    status = v36_accesso_status(accesso)

    st.markdown(
        f"""
        <div style="border:2px solid #d4af37;border-radius:18px;background:#fffdf7;padding:16px 20px;margin:12px 0;">
            <div style="font-size:13px;color:#666;">Accesso selezionato</div>
            <div style="font-size:24px;font-weight:950;color:#111;">{nome}</div>
            <div style="font-size:12px;color:#555;">Badge: {badge} · Stato tornello: {status} · Accesso ID: {accesso.get('id')}</div>
        </div>
        """,
        unsafe_allow_html=True
    )

    if not cliente_id:
        st.error("Badge non associato: associa prima il badge a un cliente.")
        return

    tipo, scala = v36_tipo_autorizzazione_ui("checkin")
    motivo = st.text_area("Motivo / nota operativa", value=tipo, key="v36_motivo_checkin")

    c1, c2 = st.columns(2)
    with c1:
        if st.button("✅ Autorizza presenza", use_container_width=True, key="v36_autorizza_presenza"):
            ok, msg = v36_registra_presenza(cliente_id, accesso_id=accesso.get("id"), tipo_presenza=tipo, scala_lezione=scala, motivo=tipo, note=motivo)
            if ok:
                st.success(msg)
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("❌ Annulla accesso", use_container_width=True, key="v36_annulla_accesso"):
            ok, msg = v36_annulla_accesso(cliente_id, accesso_id=accesso.get("id"), motivo=motivo or "Accesso annullato da Reception")
            if ok:
                st.success("Accesso annullato / lezione restituita se necessario.")
                st.rerun()
            else:
                st.error(msg)

    st.markdown("---")
    try:
        if "kreo_render_accessi_cards" in globals():
            kreo_render_accessi_cards(accessi.head(20))
        else:
            st.dataframe(accessi.head(20), use_container_width=True, hide_index=True)
    except Exception:
        st.dataframe(accessi.head(20), use_container_width=True)


def render_v36_admin_ledger_tools():
    st.header("🧮 V36 Ledger & Ricalcolo")
    st.caption("Luxury/Gold/VIP/Coaching maturano +3/settimana. Personalizzati esclusi.")
    if st.button("Ricalcola tutti i clienti standard", use_container_width=True, key="v36_ricalcolo_tutti"):
        try:
            clienti = load_clienti()
            agg = pers = salt = 0
            for _, c in clienti.iterrows():
                cid = c.get("id")
                pac = c.get("pacchetto", "")
                if v36_is_personalizzato(pac):
                    pers += 1
                elif v36_is_standard_cumulativo(pac):
                    agg += 1 if v36_aggiorna_saldo_cliente(cid) else 0
                else:
                    salt += 1
            st.success(f"Aggiornati: {agg} | Personalizzati ignorati: {pers} | Saltati: {salt}")
        except Exception as e:
            st.error(f"Errore ricalcolo: {e}")



