# KREO V37.05 - Reception navigation safe router
# ============================================================

def kreo_reception_clear_navigation():
    """
    V37.05: reset sicuro.
    Non modifica più v32_macro_nav / v32_sub_nav perché sono chiavi di widget Streamlit
    e causavano StreamlitAPIException dopo il click.
    """
    keys_to_clear = [
        "reception_view",
        "reception_internal_view",
        "reception_alert_focus",
        "kreo_internal_view",
        "clienti_internal_view",
        "selected_reception_action",
        "active_reception_module",
        "active_view",
        "subview",
        "view",
        "checkin_mode",
        "cliente360",
        "cliente_360",
        "selected_action",
        "modulo_attivo",
        "pagina",
        "submenu",
    ]
    for k in keys_to_clear:
        try:
            if k in st.session_state:
                del st.session_state[k]
        except Exception:
            pass

    # Solo chiave ponte NON legata direttamente a widget.
    st.session_state["kreo_go_reception_home"] = True
    st.session_state["reception_home"] = True


def kreo_reception_go_home():
    kreo_reception_clear_navigation()
    st.rerun()


def kreo_reception_open(view_name):
    """
    V37.05: apre sottoviste senza toccare chiavi widget del menu laterale.
    """
    # Pulisce solo le sottoviste precedenti
    for k in [
        "reception_view",
        "reception_internal_view",
        "reception_alert_focus",
        "kreo_internal_view",
        "clienti_internal_view",
        "selected_reception_action",
        "active_reception_module",
        "active_view",
        "subview",
        "view",
        "checkin_mode",
        "cliente360",
        "cliente_360",
        "selected_action",
        "modulo_attivo",
        "pagina",
        "submenu",
    ]:
        try:
            if k in st.session_state:
                del st.session_state[k]
        except Exception:
            pass

    st.session_state["reception_view"] = view_name
    st.session_state["reception_home"] = False
    st.rerun()


