                    importo_pagato = float(cliente.get("importo_pagato") or 0)
                    residuo_totale = max(importo_totale - importo_pagato, 0)

                    k1, k2, k3, k4 = st.columns(4)
                    k1.metric("Contratto", euro(importo_totale))
                    k2.metric("Già pagato", euro(importo_pagato))
