def render_v37_nuovo_cliente():
    st.header("➕ Nuovo cliente")
    st.caption("Registrazione rapida: cliente + eventuale primo incasso.")

    with st.form("v37_nuovo_cliente_form"):
        c1, c2, c3 = st.columns(3)
        with c1:
            nome = st.text_input("Nome")
            cognome = st.text_input("Cognome")
            cellulare = st.text_input("Telefono / WhatsApp")
        with c2:
            email = st.text_input("Email")
            pacchetto = st.selectbox("Pacchetto", [
                "PACCHETTO LUXURY",
                "PACCHETTO GOLD",
                "PACCHETTO VIP",
                "PACCHETTO COACHING IN SEDE",
                "PACCHETTO PERSONALIZZATO",
            ])
            numero_lezioni = st.number_input("Lezioni iniziali", min_value=0, max_value=300, value=3)
        with c3:
            importo_totale = st.number_input("Importo totale", min_value=0.0, value=0.0, step=10.0)
            importo_pagato = st.number_input("Importo pagato oggi", min_value=0.0, value=0.0, step=10.0)
            metodo = st.selectbox("Metodo pagamento", ["Contanti", "Carta", "Bonifico", "Altro"])

        note = st.text_area("Note")
        salva = st.form_submit_button("✅ Salva cliente", use_container_width=True)

    if salva:
        if not nome or not cognome:
            st.error("Nome e cognome sono obbligatori.")
            return
        try:
            residuo = max(float(importo_totale or 0) - float(importo_pagato or 0), 0)
            payload = {
                "nome": nome.strip(),
                "cognome": cognome.strip(),
                "cellulare": cellulare.strip(),
                "email": email.strip(),
                "pacchetto": pacchetto,
                "numero_lezioni": int(numero_lezioni),
                "lezioni_utilizzate": 0,
                "lezioni_residue": int(numero_lezioni),
                "importo": float(importo_totale or 0),
                "importo_pagato": float(importo_pagato or 0),
                "residuo": float(residuo),
                "note": note,
            }
            try:
                payload["created_at"] = datetime.now().isoformat()
            except Exception:
                pass

            res = get_supabase().table("clienti").insert(payload).execute()
            new_rows = res.data or []
            new_id = new_rows[0].get("id") if new_rows else None

            if new_id and float(importo_pagato or 0) > 0:
                try:
                    insert_pagamento(
                        int(new_id),
                        date.today(),
                        float(importo_pagato),
                        metodo,
                        "Primo incasso registrato in fase di creazione cliente",
                        rata_num=None,
                        rata_label="Primo incasso"
                    )
                except Exception:
                    try:
                        get_supabase().table("pagamenti").insert({
                            "cliente_id": int(new_id),
                            "data_pagamento": str(date.today()),
                            "importo": float(importo_pagato),
                            "metodo_pagamento": metodo,
                            "note": "Primo incasso registrato in fase di creazione cliente",
                            "created_at": datetime.now().isoformat(),
                        }).execute()
                    except Exception:
                        pass

            try:
                st.cache_data.clear()
            except Exception:
                pass
            st.success("Cliente creato correttamente.")
            st.balloons()
        except Exception as e:
            st.error(f"Errore creazione cliente: {e}")


def render_v37_incasso_rate():
    st.header("💰 Registra incasso")
    st.caption("Incasso rapido con scelta rata/residuo.")

    cid, cliente = v37_select_cliente("Cliente", "v37_incasso_cliente")
    if not cid:
        return

    residuo = float(cliente.get("residuo") or cliente.get("residuo_euro") or 0)
    importo_totale = float(cliente.get("importo") or 0)
    pagato = float(cliente.get("importo_pagato") or 0)

    c0, c1, c2 = st.columns(3)
    c0.metric("Importo totale", f"€ {importo_totale:.2f}")
    c1.metric("Pagato", f"€ {pagato:.2f}")
    c2.metric("Residuo", f"€ {residuo:.2f}")

    opzioni = ["Incasso libero"]
    if residuo > 0:
        opzioni += [f"Saldo residuo € {residuo:.2f}", "Rata 1", "Rata 2", "Rata 3", "Rata personalizzata"]
    scelta = st.selectbox("Cosa stai incassando?", opzioni, key="v37_incasso_rata")

    default_importo = 0.0
    if scelta.startswith("Saldo residuo"):
        default_importo = residuo

    with st.form("v37_incasso_form"):
        c1, c2, c3 = st.columns(3)
        with c1:
            importo = st.number_input("Importo", min_value=0.0, value=float(default_importo), step=10.0)
        with c2:
            metodo = st.selectbox("Metodo", ["Contanti", "Carta", "Bonifico", "Altro"])
        with c3:
            data_pag = st.date_input("Data", value=date.today())
        note = st.text_area("Note", value=scelta)
        salva = st.form_submit_button("✅ Registra incasso", use_container_width=True)

    if salva:
        if float(importo or 0) <= 0:
            st.error("Inserisci un importo maggiore di zero.")
            return
        try:
            ok, msg = insert_pagamento(
                int(cid),
                data_pag,
                float(importo),
                metodo,
                note,
                rata_num=None,
                rata_label=scelta
            )
            if ok:
                try:
                    nuovo_pagato = float(cliente.get("importo_pagato") or 0) + float(importo)
                    nuovo_residuo = max(float(cliente.get("importo") or 0) - nuovo_pagato, 0)
                    get_supabase().table("clienti").update({
                        "importo_pagato": nuovo_pagato,
                        "residuo": nuovo_residuo,
                    }).eq("id", int(cid)).execute()
                except Exception:
                    pass
                try:
                    st.cache_data.clear()
                except Exception:
                    pass
                st.success("Incasso registrato.")
                st.rerun()
            else:
                st.error(msg)
        except Exception as e:
            st.error(f"Errore registrazione incasso: {e}")


def render_v37_agenda_7gg():
    st.header("📅 Agenda / Calendario - 7 giorni")
    st.caption("Vista semplice per Reception: oggi + prossimi 7 giorni.")

    df = v37_df_lezioni()
    if df.empty:
        st.info("Nessuna lezione in agenda.")
        return

    data_col = "data_lezione" if "data_lezione" in df.columns else ("data" if "data" in df.columns else None)
    if not data_col:
        st.dataframe(df.head(50), use_container_width=True, hide_index=True)
        return

    tmp = df.copy()
    tmp["_data"] = pd.to_datetime(tmp[data_col], errors="coerce").dt.date
    start = date.today()
    end = start + timedelta(days=7)
    tmp = tmp[(tmp["_data"] >= start) & (tmp["_data"] <= end)].copy()

    if tmp.empty:
        st.info("Nessuna lezione nei prossimi 7 giorni.")
        return

    for d in sorted(tmp["_data"].dropna().unique()):
        st.markdown(f"### {d.strftime('%d/%m/%Y')}")
        day = tmp[tmp["_data"] == d].copy()
        for _, r in day.head(40).iterrows():
            nome = r.get("cliente") or r.get("nome_cliente") or f"Cliente ID {r.get('cliente_id','')}"
            ora = f"{r.get('ora_inizio','')} - {r.get('ora_fine','')}"
            trainer = r.get("trainer") or r.get("istruttore") or ""
            stato = r.get("stato") or ""
            st.markdown(
                f"""
                <div style="border:1px solid rgba(212,175,55,.65);border-radius:14px;background:#fffdf7;padding:12px;margin:8px 0;">
                    <b>{ora}</b> — <b>{nome}</b><br>
                    <span style="color:#666;">{trainer} · {stato}</span>
                </div>
                """,
                unsafe_allow_html=True
            )


