def contatori_cumulativi_cliente(cliente_id, data_ref=None, pacchetto=None):
    """V37.05: contatori semplici da tabella clienti."""
    try:
        c = get_cliente(int(float(cliente_id)))
        totale = int(float(c.get("numero_lezioni") or c.get("numero_lezioni_totali") or 0))
        usate = int(float(c.get("lezioni_utilizzate") or 0))
        residue_raw = c.get("lezioni_residue")
        residue = int(float(residue_raw)) if residue_raw not in [None, "", "nan"] else max(totale - usate, 0)
        return totale, usate, max(residue, 0)
    except Exception:
        return 0, 0, 0


