def kreo_document_bucket_status():
    """
    V37.05: ripristino logica che funzionava.
    Bucket storico/pubblico: documenti.
    Tabella: documenti_cliente.
    """
    sb = get_supabase()
    candidates = ["documenti", "documenti_cliente", "documenti-clienti", "documenti_privati"]
    try:
        buckets = sb.storage.list_buckets()
        names = []
        for b in buckets:
            if isinstance(b, dict):
                names.append(b.get("name"))
            else:
                names.append(getattr(b, "name", None))
        names = [n for n in names if n]
    except Exception:
        names = []
    for c in candidates:
        if c in names:
            return c, True, names
    return "documenti", False, names


def signed_document_url(storage_path, expires_in=300):
    """V37.05: per i documenti usiamo URL pubblico su bucket documenti; signed URL solo fallback."""
    if not storage_path:
        return ""
    try:
        return get_supabase().storage.from_("documenti").get_public_url(storage_path)
    except Exception:
        try:
            res = get_supabase().storage.from_("documenti").create_signed_url(storage_path, expires_in)
            if isinstance(res, dict):
                return res.get("signedURL") or res.get("signedUrl") or res.get("url") or ""
            return str(res)
        except Exception:
            return ""


def document_url_for_display(row, expires_in=300):
    if row is None:
        return ""
    try:
        public_url = row.get("public_url", "") if hasattr(row, "get") else ""
        if public_url:
            return public_url
        storage_path = row.get("storage_path", "") if hasattr(row, "get") else ""
        if storage_path:
            return signed_document_url(storage_path, expires_in)
    except Exception:
        pass
    return ""


def load_documenti(cliente_id=None):
    """V37.05: tabella storica funzionante: documenti_cliente."""
    sb = get_supabase()
    data = []
    try:
        q = sb.table("documenti_cliente").select("*").order("id", desc=True)
        if cliente_id is not None:
            q = q.eq("cliente_id", int(float(cliente_id)))
        data = q.execute().data or []
    except Exception:
        try:
            q = sb.table("documenti_clienti").select("*").order("id", desc=True)
            if cliente_id is not None:
                q = q.eq("cliente_id", int(float(cliente_id)))
            data = q.execute().data or []
        except Exception:
            data = []
    df = pd.DataFrame(data)
    if not df.empty and "created_at" in df.columns:
        try:
            df["created_at_it"] = df["created_at"].apply(lambda x: pd.to_datetime(x).strftime("%d/%m/%Y %H:%M") if x else "")
        except Exception:
            pass
    return df


def upload_documento_cliente(cliente_id, file, tipo_documento, note_documento=""):
    """V37.05: upload coerente col vecchio storico: bucket documenti + tabella documenti_cliente + public_url."""
    if file is None:
        return False, "Nessun file caricato."
    if not str(file.name).lower().endswith(".pdf"):
        return False, "Per ora sono ammessi solo file PDF."
    cliente = get_cliente(int(float(cliente_id)))
    if not cliente:
        return False, "Cliente non trovato."
    sb = get_supabase()
    bucket_name, bucket_ok, existing_buckets = kreo_document_bucket_status()
    # forza il bucket storico se esiste
    if "documenti" in existing_buckets or bucket_name != "documenti":
        bucket_name = "documenti"
        bucket_ok = "documenti" in existing_buckets or bucket_ok
    if not bucket_ok:
        return False, "Bucket documenti non trovato. Crea/usa il bucket pubblico 'documenti'. Bucket rilevati: " + (", ".join(existing_buckets) if existing_buckets else "nessuno")

    safe_name = str(file.name).replace(" ", "_").replace("/", "_").replace("\\", "_")
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    tipo_slug = str(tipo_documento or "documento").lower().replace(" ", "_")
    path = f"cliente_{int(float(cliente_id))}/{tipo_slug}_{timestamp}_{safe_name}"
    try:
        sb.storage.from_(bucket_name).upload(path, file.getvalue(), {"content-type": "application/pdf", "x-upsert": "true"})
    except Exception as e:
        return False, f"Errore upload documento su bucket '{bucket_name}': {e}"
    try:
        public_url = sb.storage.from_(bucket_name).get_public_url(path)
    except Exception:
        public_url = f"{SUPABASE_URL}/storage/v1/object/public/{bucket_name}/{path}" if "SUPABASE_URL" in globals() else ""

    payload = {
        "cliente_id": int(float(cliente_id)),
        "tipo_documento": tipo_documento,
        "nome_file": file.name,
        "storage_path": path,
        "public_url": public_url,
        "caricato_da": user_label() if "user_label" in globals() else "KREO",
        "note": note_documento or "",
        "created_at": now_iso() if "now_iso" in globals() else datetime.now().isoformat(),
    }
    try:
        sb.table("documenti_cliente").insert(payload).execute()
    except Exception as e:
        return False, f"File caricato, ma errore salvataggio tabella documenti_cliente: {e}"
    try:
        st.cache_data.clear()
    except Exception:
        pass
    return True, "Documento caricato correttamente."


