    view = st.session_state.get("reception_internal_view") or st.session_state.get("reception_view")
    if not view:
        return False
    aliases = {"incassi":"incasso", "registra_incasso":"incasso", "ricevuta":"ricevute_storico", "ricevute":"ricevute_storico", "cliente360":"cliente_360", "clienti":"modifica_cliente", "tornello":"v36_checkin", "accesso_tornello":"v36_checkin", "agenda":"agenda_7gg"}
    view = aliases.get(view, view)
    v37_render_back()
    if view == "nuovo_cliente": render_v37_nuovo_cliente()
