def v3703_today():
    try:
        return date.today()
    except Exception:
        from datetime import date as _date
        return _date.today()


def v3703_now_iso():
    try:
        return now_iso()
    except Exception:
        try:
            return datetime.now().isoformat()
        except Exception:
            from datetime import datetime as _dt
            return _dt.now().isoformat()


def v3703_get_clienti_df():
    try:
        df = v37_df_clienti()
        return df if df is not None else pd.DataFrame()
    except Exception:
        try:
            rows = get_supabase().table("clienti").select("*").order("cognome").execute().data or []
            return pd.DataFrame(rows)
        except Exception:
            return pd.DataFrame()


def v3703_get_cliente(cliente_id):
    try:
        if cliente_id in [None, "", "nan"]:
            return {}
        rows = get_supabase().table("clienti").select("*").eq("id", int(float(cliente_id))).limit(1).execute().data or []
        return rows[0] if rows else {}
    except Exception:
        return {}


def v3703_label_cliente(row):
    try:
        return f"{int(float(row.get('id')))} - {str(row.get('nome') or '').strip()} {str(row.get('cognome') or '').strip()}".strip()
    except Exception:
        return f"{row.get('id','')} - {row.get('nome','')} {row.get('cognome','')}"


def v3703_select_cliente(label="Cliente", key="v3703_cliente"):
    df = v3703_get_clienti_df()
    if df.empty:
        st.info("Nessun cliente presente.")
        return None, {}
    df = df.copy()
    df["__label"] = df.apply(v3703_label_cliente, axis=1)
    selected = st.selectbox(label, df["__label"].tolist(), key=key)
    try:
        cid = int(str(selected).split(" - ")[0])
        row = df[pd.to_numeric(df["id"], errors="coerce") == cid].iloc[0].to_dict()
        return cid, row
    except Exception:
        return None, {}


def v3703_int(v, default=0):
    try:
        if v in [None, "", "nan"]:
            return default
        return int(float(v))
    except Exception:
        return default


def v3703_float(v, default=0.0):
    try:
        if v in [None, "", "nan"]:
            return default
        return float(v)
    except Exception:
        return default


def v3703_lezioni(cliente):
    totale = v3703_int(cliente.get("numero_lezioni"), 0)
    usate = v3703_int(cliente.get("lezioni_utilizzate"), 0)
    residue = max(totale - usate, 0)
    return totale, usate, residue


def v3703_update_cliente(payload, cliente_id):
    """
    Aggiorna solo colonne reali/probabili.
    Esclude sempre lezioni_residue.
    """
    payload = dict(payload or {})
    payload.pop("lezioni_residue", None)
    try:
        payload["updated_at"] = v3703_now_iso()
    except Exception:
        pass
    return get_supabase().table("clienti").update(payload).eq("id", int(float(cliente_id))).execute()


def render_v37_nuovo_cliente():
    """
    Override V37.05: nuovo cliente senza colonna lezioni_residue.
    """
    st.header("➕ Nuovo cliente")
    st.caption("Registrazione rapida: cliente + eventuale primo incasso. Nessuna colonna lezioni_residue.")

    with st.form("v3703_nuovo_cliente_form"):
        c1, c2, c3 = st.columns(3)
        with c1:
            nome = st.text_input("Nome")
            cognome = st.text_input("Cognome")
            cellulare = st.text_input("Telefono / WhatsApp")
        with c2:
            email = st.text_input("Email")
            pacchetto = st.selectbox("Pacchetto", [
                "PACCHETTO LUXURY",
                "PACCHETTO GOLD",
                "PACCHETTO VIP",
                "PACCHETTO COACHING IN SEDE",
                "PACCHETTO PERSONALIZZATO",
            ])
            numero_lezioni = st.number_input("Lezioni iniziali", min_value=0, max_value=300, value=3)
        with c3:
            importo_totale = st.number_input("Importo totale", min_value=0.0, value=0.0, step=10.0)
            importo_pagato = st.number_input("Importo pagato oggi", min_value=0.0, value=0.0, step=10.0)
            metodo = st.selectbox("Metodo pagamento", ["Contanti", "Carta", "Bonifico", "Altro"])
        note = st.text_area("Note")
        salva = st.form_submit_button("✅ Salva cliente", use_container_width=True)

    if salva:
        if not nome or not cognome:
            st.error("Nome e cognome sono obbligatori.")
            return
        try:
            residuo = max(float(importo_totale or 0) - float(importo_pagato or 0), 0)
            payload = {
                "nome": nome.strip(),
                "cognome": cognome.strip(),
                "cellulare": cellulare.strip(),
                "email": email.strip(),
                "pacchetto": pacchetto,
                "numero_lezioni": int(numero_lezioni),
                "lezioni_utilizzate": 0,
                "importo": float(importo_totale or 0),
                "importo_pagato": float(importo_pagato or 0),
                "residuo": float(residuo),
                "note": note,
                "created_at": v3703_now_iso(),
            }

            # Primo tentativo con tutti i campi utili.
            try:
                res = get_supabase().table("clienti").insert(payload).execute()
            except Exception as e:
                # Fallback ultracompatibile se qualche colonna economica non esiste.
                msg = str(e)
                for col in ["importo_pagato", "residuo", "created_at", "note"]:
                    payload.pop(col, None)
                res = get_supabase().table("clienti").insert(payload).execute()

            new_rows = res.data or []
            new_id = new_rows[0].get("id") if new_rows else None

            if new_id and float(importo_pagato or 0) > 0:
                try:
                    insert_pagamento(
                        int(new_id),
                        v3703_today(),
                        float(importo_pagato),
                        metodo,
                        "Primo incasso registrato in fase di creazione cliente",
                        rata_num=None,
                        rata_label="Primo incasso"
                    )
                except Exception:
                    try:
                        get_supabase().table("pagamenti").insert({
                            "cliente_id": int(new_id),
                            "data_pagamento": str(v3703_today()),
                            "importo": float(importo_pagato),
                            "metodo_pagamento": metodo,
                            "note": "Primo incasso registrato in fase di creazione cliente",
                            "created_at": v3703_now_iso(),
                        }).execute()
                    except Exception:
                        pass

            try:
                st.cache_data.clear()
            except Exception:
                pass
            st.success("Cliente creato correttamente.")
            st.balloons()
        except Exception as e:
            st.error(f"Errore creazione cliente: {e}")


def render_staff_modifica_cliente():
    """
    Override V37.05: modifica cliente senza lezioni_residue.
    Mostra residuo calcolato ma non lo salva.
    """
    st.header("✏️ Modifica cliente")
    st.caption("Scheda rapida modificabile: dati, pacchetto, lezioni, importi, stato.")

    cid, cliente = v3703_select_cliente("Cliente da modificare", "v3703_mod_cliente")
    if not cid:
        return

    totale, usate, residue = v3703_lezioni(cliente)

    with st.form(f"v3703_modifica_cliente_form_{cid}"):
        c1, c2, c3 = st.columns(3)
        with c1:
            nome = st.text_input("Nome", value=str(cliente.get("nome") or ""))
            cognome = st.text_input("Cognome", value=str(cliente.get("cognome") or ""))
            cellulare = st.text_input("Telefono / WhatsApp", value=str(cliente.get("cellulare") or cliente.get("telefono") or ""))
            email = st.text_input("Email", value=str(cliente.get("email") or ""))
        with c2:
            pacchetto = st.text_input("Pacchetto", value=str(cliente.get("pacchetto") or ""))
            numero_lezioni = st.number_input("Lezioni totali", min_value=0, max_value=500, value=int(totale))
            lezioni_utilizzate = st.number_input("Lezioni utilizzate", min_value=0, max_value=500, value=int(usate))
            st.metric("Lezioni residue calcolate", max(int(numero_lezioni) - int(lezioni_utilizzate), 0))
        with c3:
            importo = st.number_input("Importo totale", min_value=0.0, value=v3703_float(cliente.get("importo"), 0.0), step=10.0)
            importo_pagato = st.number_input("Importo pagato", min_value=0.0, value=v3703_float(cliente.get("importo_pagato"), 0.0), step=10.0)
            residuo_euro = max(float(importo) - float(importo_pagato), 0)
            st.metric("Residuo € calcolato", f"€ {residuo_euro:.2f}")
            stato = st.selectbox("Stato", ["ATTIVO", "SOSPESO", "SCADUTO", "ARCHIVIATO"], index=0)

        note = st.text_area("Note", value=str(cliente.get("note") or ""))
        salva = st.form_submit_button("💾 Salva modifiche", use_container_width=True)

    if salva:
        try:
            payload = {
                "nome": nome,
                "cognome": cognome,
                "cellulare": cellulare,
                "email": email,
                "pacchetto": pacchetto,
                "numero_lezioni": int(numero_lezioni),
                "lezioni_utilizzate": int(lezioni_utilizzate),
                "importo": float(importo),
                "importo_pagato": float(importo_pagato),
                "residuo": float(residuo_euro),
                "stato": stato,
                "note": note,
            }
            # Fallback se alcune colonne economiche/stato/note non esistono.
            try:
                v3703_update_cliente(payload, cid)
            except Exception:
                for col in ["residuo", "stato", "note", "importo_pagato"]:
                    payload.pop(col, None)
                v3703_update_cliente(payload, cid)

            try:
                st.cache_data.clear()
            except Exception:
                pass
            st.success("Cliente aggiornato correttamente.")
            st.rerun()
        except Exception as e:
            st.error(f"Errore aggiornamento cliente: {e}")


def v3703_lezioni_rows():
    try:
        rows = get_supabase().table("lezioni").select("*").order("data_lezione").execute().data or []
        return pd.DataFrame(rows)
    except Exception:
        try:
            rows = get_supabase().table("lezioni").select("*").order("data").execute().data or []
            return pd.DataFrame(rows)
        except Exception:
            return pd.DataFrame()


def v3703_insert_lezione(payload):
    """
    Inserimento lezione compatibile con schemi diversi.
    """
    candidates = [
        payload,
        {k: v for k, v in payload.items() if k not in ["created_at", "note"]},
        {
            "cliente_id": payload.get("cliente_id"),
            "data_lezione": payload.get("data_lezione"),
            "ora_inizio": payload.get("ora_inizio"),
            "ora_fine": payload.get("ora_fine"),
            "trainer": payload.get("trainer"),
            "stato": payload.get("stato"),
        },
        {
            "cliente_id": payload.get("cliente_id"),
            "data": payload.get("data_lezione"),
            "ora_inizio": payload.get("ora_inizio"),
            "ora_fine": payload.get("ora_fine"),
            "trainer": payload.get("trainer"),
            "stato": payload.get("stato"),
        },
    ]
    last = None
    for p in candidates:
        p = {k: v for k, v in p.items() if v not in [None, ""]}
        try:
            get_supabase().table("lezioni").insert(p).execute()
            return True, "Lezione inserita in agenda."
        except Exception as e:
            last = e
    return False, f"Errore inserimento lezione: {last}"


def render_v37_agenda_7gg():
    """
    Override V37.05: Agenda Luxury operativa.
    Default 7 giorni, modificabile, con inserimento cliente/orario.
    """
    st.header("✨ Agenda Luxury")
    st.caption("Vista Reception: default 7 giorni, modificabile. Puoi inserire subito un cliente in uno slot.")

    with st.expander("➕ Inserisci nuova lezione / prenotazione", expanded=True):
        clienti = v3703_get_clienti_df()
        if clienti.empty:
            st.info("Nessun cliente disponibile.")
        else:
            clienti = clienti.copy()
            clienti["__label"] = clienti.apply(v3703_label_cliente, axis=1)
            with st.form("v3703_nuova_lezione"):
                c1, c2, c3 = st.columns(3)
                with c1:
                    cliente_label = st.selectbox("Cliente", clienti["__label"].tolist())
                    data_lezione = st.date_input("Data", value=v3703_today())
                with c2:
                    ora_inizio = st.text_input("Ora inizio", value="10:00")
                    ora_fine = st.text_input("Ora fine", value="11:00")
                with c3:
                    trainer = st.text_input("Trainer", value="")
                    stato = st.selectbox("Stato", ["PRENOTATO", "PRESENTE", "ASSENTE", "DA VERIFICARE"])
                note = st.text_area("Note agenda", value="")
                salva = st.form_submit_button("✅ Inserisci in agenda", use_container_width=True)

            if salva:
                try:
                    cid = int(str(cliente_label).split(" - ")[0])
                    payload = {
                        "cliente_id": cid,
                        "data_lezione": str(data_lezione),
                        "ora_inizio": ora_inizio,
                        "ora_fine": ora_fine,
                        "trainer": trainer,
                        "stato": stato,
                        "note": note,
                        "created_at": v3703_now_iso(),
                    }
                    ok, msg = v3703_insert_lezione(payload)
                    st.success(msg) if ok else st.error(msg)
                    if ok:
                        try:
                            st.cache_data.clear()
                        except Exception:
                            pass
                        st.rerun()
                except Exception as e:
                    st.error(f"Errore inserimento agenda: {e}")

    giorni = st.selectbox("Giorni da visualizzare", [7, 14, 30, 60], index=0, key="v3703_agenda_days")
    df = v3703_lezioni_rows()

    if df.empty:
        st.info(f"Nessuna lezione nei prossimi {giorni} giorni.")
        return

    data_col = "data_lezione" if "data_lezione" in df.columns else ("data" if "data" in df.columns else None)
    if not data_col:
        st.dataframe(df.head(80), use_container_width=True, hide_index=True)
        return

    tmp = df.copy()
    tmp["_data"] = pd.to_datetime(tmp[data_col], errors="coerce").dt.date
    start = v3703_today()
    end = start + timedelta(days=int(giorni))
    tmp = tmp[(tmp["_data"] >= start) & (tmp["_data"] <= end)].copy()

    if tmp.empty:
        st.info(f"Nessuna lezione nei prossimi {giorni} giorni.")
        return

    clienti = v3703_get_clienti_df()
    nome_map = {}
    if not clienti.empty and "id" in clienti.columns:
        for _, r in clienti.iterrows():
            try:
                nome_map[int(float(r.get("id")))] = f"{r.get('nome','')} {r.get('cognome','')}".strip()
            except Exception:
                pass

    try:
        tmp["_ora_sort"] = tmp.get("ora_inizio", "").astype(str)
        tmp = tmp.sort_values(["_data", "_ora_sort"])
    except Exception:
        pass

    for d in sorted(tmp["_data"].dropna().unique()):
        st.markdown(f"### {d.strftime('%d/%m/%Y')}")
        day = tmp[tmp["_data"] == d].copy()
        for _, r in day.iterrows():
            cid = v3703_int(r.get("cliente_id"), 0)
            cliente_nome = r.get("cliente") or r.get("nome_cliente") or nome_map.get(cid, f"Cliente ID {cid}")
            ora = f"{r.get('ora_inizio','')} - {r.get('ora_fine','')}"
            trainer = r.get("trainer") or r.get("istruttore") or ""
            stato = r.get("stato") or ""
            st.markdown(
                f"""
                <div style="border:1.5px solid rgba(212,175,55,.65);border-radius:16px;background:#fffdf7;padding:14px 16px;margin:8px 0;box-shadow:0 6px 16px rgba(0,0,0,.04);">
                    <div style="display:flex;justify-content:space-between;gap:16px;">
                        <div>
                            <div style="font-size:18px;font-weight:950;">{ora} · {cliente_nome}</div>
                            <div style="font-size:13px;color:#666;">Trainer: {trainer or '-'} · Stato: {stato or '-'}</div>
                        </div>
                        <div style="font-size:12px;font-weight:900;border:1px solid #d4af37;border-radius:999px;padding:7px 10px;height:fit-content;">{stato or 'AGENDA'}</div>
                    </div>
                </div>
                """,
                unsafe_allow_html=True
            )




