def v3704_badge_unassigned_rows():
    accessi = v3704_accessi_df()
    if accessi.empty:
        return pd.DataFrame()
    df = accessi.copy()
    # badge da verificare/non associati: cliente_id nullo oppure stato da verificare/negato
    mask = pd.Series([False]*len(df))
    if "cliente_id" in df.columns:
        mask = mask | df["cliente_id"].isna() | (df["cliente_id"].astype(str).isin(["", "None", "nan"]))
    if "stato_accesso" in df.columns:
        stato = df["stato_accesso"].astype(str).str.upper()
        mask = mask | stato.str.contains("DA_VERIFICARE|NEGATO|NON_ASSOCIATO", na=False)
    return df[mask].copy()


