KREO_DOCUMENTI_BUCKET = "documenti"

def v3705_now():
    try:
        return datetime.now()
    except Exception:
        from datetime import datetime as _dt
        return _dt.now()

def v3705_today():
    try:
        return date.today()
    except Exception:
        from datetime import date as _date
        return _date.today()

