def v3705_render_agenda_oggi_pulita():
    lezioni = v3705_lezioni_df()
    if lezioni.empty:
        st.caption("Nessuna lezione prevista oggi.")
        return
    data_col = "data_lezione" if "data_lezione" in lezioni.columns else ("data" if "data" in lezioni.columns else None)
    if not data_col:
        st.caption("Agenda disponibile ma senza colonna data riconosciuta.")
        return
    today = str(v3705_today())
    day = lezioni[lezioni[data_col].astype(str).str[:10] == today].copy()
    if day.empty:
        st.caption("Nessuna lezione prevista oggi.")
        return
    clienti = v3705_clients_df()
    nome_map = {}
    if not clienti.empty:
        for _, r in clienti.iterrows():
            try:
                nome_map[int(float(r.get("id")))] = v3705_cliente_nome(r)
            except Exception:
                pass
    try:
        day = day.sort_values(by=[c for c in ["ora_inizio", "ora"] if c in day.columns][0])
    except Exception:
        pass
    for _, r in day.head(12).iterrows():
        cid = r.get("cliente_id")
        nome = r.get("cliente") or r.get("nome_cliente") or nome_map.get(int(float(cid)), f"Cliente ID {cid}" if cid not in [None, "", "nan"] else "Cliente non indicato")
        ora = f"{r.get('ora_inizio') or r.get('ora') or ''} - {r.get('ora_fine') or ''}".strip(" -")
        stato = r.get("stato") or "-"
        trainer = r.get("trainer") or r.get("istruttore") or "-"
        v3705_card_cliente(nome, f"{ora} · Trainer: {trainer}", stato)

