# ---- Ricevute professionali Genesis/KREO ----

def v3705_pdf_ricevuta_genesis(cliente_nome, data_pag, importo, metodo, causale):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from io import BytesIO

    buffer = BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, rightMargin=2*cm, leftMargin=2*cm, topMargin=1.7*cm, bottomMargin=1.5*cm)
    styles = getSampleStyleSheet()
    title = ParagraphStyle("kreoTitle", parent=styles["Title"], fontSize=22, leading=26, alignment=1, textColor=colors.black)
    sub = ParagraphStyle("kreoSub", parent=styles["Normal"], fontSize=10, leading=13, alignment=1, textColor=colors.HexColor("#555555"))
    normal = styles["Normal"]
    story = []

    story.append(Paragraph("KREO Your Place", title))
    story.append(Paragraph("GENESIS SRLS", sub))
    story.append(Paragraph("Ricevuta pagamento", ParagraphStyle("h", parent=styles["Heading1"], fontSize=18, leading=22, spaceBefore=18, spaceAfter=12)))
    data = [
        ["Cliente", str(cliente_nome)],
        ["Data", str(data_pag)],
        ["Importo", f"€ {float(importo or 0):.2f}"],
        ["Metodo", str(metodo or "-")],
        ["Causale", str(causale or "-")],
    ]
    table = Table(data, colWidths=[4*cm, 11*cm])
    table.setStyle(TableStyle([
        ("GRID", (0,0), (-1,-1), 0.6, colors.HexColor("#b8a04a")),
        ("BACKGROUND", (0,0), (0,-1), colors.HexColor("#fff7d6")),
        ("FONTNAME", (0,0), (0,-1), "Helvetica-Bold"),
        ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
        ("LEFTPADDING", (0,0), (-1,-1), 8),
        ("RIGHTPADDING", (0,0), (-1,-1), 8),
        ("TOPPADDING", (0,0), (-1,-1), 8),
        ("BOTTOMPADDING", (0,0), (-1,-1), 8),
    ]))
    story.append(table)
    story.append(Spacer(1, 1.2*cm))
    story.append(Paragraph("Documento generato dal gestionale KREO per Genesis SRLS.", normal))
    story.append(Spacer(1, .4*cm))
    story.append(Paragraph("Firma / Timbro ________________________________", normal))
    doc.build(story)
    return buffer.getvalue()

def genera_pdf_ricevuta(cliente_nome, data_pag, importo, metodo, causale, brand=None):
    return v3705_pdf_ricevuta_genesis(cliente_nome, data_pag, importo, metodo, causale)

# ---- Documenti: bucket pubblico documenti senza listing obbligatorio ----

def v3705_upload_documento_storage(cliente_id, file_obj, tipo_documento):
    """
    Non controlla più il listing dei bucket, perché la policy/list buckets può fallire anche se il bucket esiste.
    Usa direttamente bucket pubblico 'documenti'.
    """
    try:
        filename = getattr(file_obj, "name", "documento.pdf")
        safe_tipo = str(tipo_documento or "documento").lower().replace(" ", "_").replace("/", "_")
        ext = filename.split(".")[-1].lower() if "." in filename else "pdf"
        storage_path = f"cliente_{int(float(cliente_id))}/{safe_tipo}_{v3705_now().strftime('%Y%m%d%H%M%S')}.{ext}"
        data = file_obj.getvalue()
        try:
            get_supabase().storage.from_(KREO_DOCUMENTI_BUCKET).upload(storage_path, data, {"content-type": "application/pdf", "upsert": "true"})
        except TypeError:
            get_supabase().storage.from_(KREO_DOCUMENTI_BUCKET).upload(storage_path, data)
        public_url = get_supabase().storage.from_(KREO_DOCUMENTI_BUCKET).get_public_url(storage_path)
        return True, storage_path, public_url
    except Exception as e:
        return False, None, f"Errore upload su bucket '{KREO_DOCUMENTI_BUCKET}': {e}"

def v3705_insert_documento_record(cliente_id, tipo_documento, filename, storage_path, public_url, note=""):
    payloads = [
        {
            "cliente_id": int(float(cliente_id)),
            "tipo_documento": tipo_documento,
            "nome_file": filename,
            "storage_path": storage_path,
            "public_url": public_url,
            "note": note,
            "created_at": v3705_now().isoformat(),
        },
        {
            "cliente_id": int(float(cliente_id)),
            "tipo": tipo_documento,
            "filename": filename,
            "path": storage_path,
            "url": public_url,
            "note": note,
        },
    ]
    last = None
    for payload in payloads:
        try:
            get_supabase().table("documenti_cliente").insert(payload).execute()
            return True, "Documento salvato nello storico cliente."
        except Exception as e:
            last = e
    return False, f"Upload riuscito, ma record documenti_cliente non salvato: {last}"

def render_staff_documenti():
    st.header("📄 Documenti e certificati cliente")
    tab1, tab2 = st.tabs(["Carica documento", "Archivio documenti"])
    with tab1:
        st.subheader("Carica PDF cliente")
        cid, cliente = v3705_select_cliente("Cliente", "v3705_doc_cliente")
        tipo = st.selectbox("Tipo documento", ["CERTIFICATO MEDICO", "CONTRATTO", "PRIVACY", "ALTRO"], key="v3705_tipo_doc")
        file = st.file_uploader("Carica PDF", type=["pdf"], key="v3705_upload_pdf")
        note = st.text_area("Note documento", key="v3705_note_doc")
        if st.button("Carica documento", use_container_width=True):
            if not cid or not file:
                st.error("Seleziona cliente e PDF.")
            else:
                ok, path, url_or_err = v3705_upload_documento_storage(cid, file, tipo)
                if not ok:
                    st.error(url_or_err)
                else:
                    ok2, msg = v3705_insert_documento_record(cid, tipo, getattr(file, "name", "documento.pdf"), path, url_or_err, note)
                    if ok2:
                        st.success("Documento caricato e salvato correttamente.")
                        st.link_button("Apri documento", url_or_err)
                    else:
                        st.warning(msg)
    with tab2:
        st.subheader("Archivio documenti")
        cid, cliente = v3705_select_cliente("Cliente archivio", "v3705_doc_archivio")
        if cid:
            try:
                docs = get_supabase().table("documenti_cliente").select("*").eq("cliente_id", int(cid)).order("id", desc=True).execute().data or []
                if not docs:
                    st.info("Nessun documento in archivio per questo cliente.")
                for d in docs:
                    url = d.get("public_url") or d.get("url")
                    tipo = d.get("tipo_documento") or d.get("tipo") or "Documento"
                    nome = d.get("nome_file") or d.get("filename") or d.get("storage_path") or d.get("path") or ""
                    st.markdown(f"**{tipo}** · {nome}")
                    if url:
                        st.link_button("Apri PDF", url)
            except Exception as e:
                st.error(f"Errore lettura documenti: {e}")

