# ------------------------------------------------------------
# V38 - Utility sicure
# ------------------------------------------------------------

def v38_now_iso():
    try:
        return now_iso()
    except Exception:
        return datetime.now().isoformat()


def v38_today():
    return date.today()


def v38_int(value, default=0):
    try:
        if value in [None, "", "nan", "None", "NaT"]:
            return default
        return int(float(value))
    except Exception:
        return default


def v38_float(value, default=0.0):
    try:
        if value in [None, "", "nan", "None", "NaT"]:
            return default
        return float(value)
    except Exception:
        return default


def v38_euro(value):
    try:
        return f"€ {float(value or 0):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return "€ 0,00"


def v38_cliente_nome(cliente):
    try:
        if cliente is None:
            return "Cliente non associato"
        if isinstance(cliente, pd.Series):
            cliente = cliente.to_dict()
        if not cliente:
            return "Cliente non associato"
        return f"{cliente.get('nome','')} {cliente.get('cognome','')}".strip() or f"Cliente ID {cliente.get('id','')}"
    except Exception:
        return "Cliente non associato"


def v38_get_cliente(cliente_id):
    try:
        if cliente_id in [None, "", "nan", "None", 0, "0", 0.0]:
            return {}
        try:
            c = get_cliente(int(float(cliente_id)))
            if c:
                return c
        except Exception:
            pass
        rows = get_supabase().table("clienti").select("*").eq("id", int(float(cliente_id))).limit(1).execute().data or []
        return rows[0] if rows else {}
    except Exception:
        return {}


def v38_load_clienti():
    try:
        return load_clienti()
    except Exception:
        try:
            rows = get_supabase().table("clienti").select("*").order("cognome").execute().data or []
            return pd.DataFrame(rows)
        except Exception:
            return pd.DataFrame()


def v38_load_accessi(limit=800):
    try:
        return load_accessi_tornello()
    except Exception:
        try:
            rows = get_supabase().table("accessi_tornello").select("*").order("id", desc=True).limit(limit).execute().data or []
            return pd.DataFrame(rows)
        except Exception:
            return pd.DataFrame()


def v38_load_badge():
    try:
        return load_badge_clienti()
    except Exception:
        try:
            rows = get_supabase().table("badge_clienti").select("*").execute().data or []
            return pd.DataFrame(rows)
        except Exception:
            return pd.DataFrame()


def v38_contatori_cliente(cliente):
    try:
        totale = v38_int(cliente.get("numero_lezioni") or cliente.get("numero_lezioni_totali") or 0)
        usate = v38_int(cliente.get("lezioni_utilizzate") or 0)
        raw_res = cliente.get("lezioni_residue")
        if raw_res not in [None, "", "nan", "None"]:
            residue = v38_int(raw_res, max(totale-usate, 0))
        else:
            residue = max(totale - usate, 0)
        return totale, usate, max(residue, 0)
    except Exception:
        return 0, 0, 0


