def v38_upload_documento_storage(cliente_id, file_obj, tipo_documento):
    filename = getattr(file_obj, "name", "documento.pdf")
    safe_tipo = str(tipo_documento or "documento").lower().replace(" ", "_").replace("/", "_")
    ext = filename.split(".")[-1].lower() if "." in filename else "pdf"
    storage_path = f"cliente_{int(float(cliente_id))}/{safe_tipo}_{datetime.now().strftime('%Y%m%d%H%M%S')}.{ext}"
    data = file_obj.getvalue()
    bucket = get_supabase().storage.from_("documenti")

    errors = []
    attempts = [
        lambda: bucket.upload(storage_path, data, {"content-type": "application/pdf", "upsert": "true"}),
        lambda: bucket.upload(path=storage_path, file=data, file_options={"content-type": "application/pdf", "upsert": "true"}),
        lambda: bucket.upload(storage_path, data),
    ]

    for fn in attempts:
        try:
            fn()
            return True, storage_path, bucket.get_public_url(storage_path)
        except Exception as e:
            errors.append(str(e))

    return False, storage_path, " | ".join(errors[-3:])


def v38_insert_documento_record(cliente_id, tipo_documento, filename, storage_path, public_url, note=""):
    payloads = [
        {
            "cliente_id": int(float(cliente_id)),
            "tipo_documento": tipo_documento,
            "nome_file": filename,
            "storage_path": storage_path,
            "public_url": public_url,
            "note": note,
            "created_at": v38_now_iso(),
        },
        {
            "cliente_id": int(float(cliente_id)),
            "tipo": tipo_documento,
            "filename": filename,
            "path": storage_path,
            "url": public_url,
            "note": note,
        },
        {
            "id_cliente": int(float(cliente_id)),
            "tipo_documento": tipo_documento,
            "nome_file": filename,
            "percorso_file": storage_path,
            "url_file": public_url,
        },
    ]

    last = None
    for p in payloads:
        try:
            get_supabase().table("documenti_cliente").insert(p).execute()
            try:
                st.cache_data.clear()
            except Exception:
                pass
            return True, "Documento salvato nello storico cliente."
        except Exception as e:
            last = e
    return False, f"Upload riuscito, ma record documenti_cliente non salvato: {last}"


def render_staff_documenti():
    st.header("📄 Documenti cliente")
    st.caption("V38: upload su bucket pubblico 'documenti' + storico in documenti_cliente.")

    clienti = v38_load_clienti()
    if clienti.empty:
        st.info("Nessun cliente disponibile.")
        return

    clienti = clienti.copy()
    clienti["__label"] = clienti.apply(lambda r: v38_cliente_label(r, show_badge=False), axis=1)

    tab1, tab2 = st.tabs(["Carica documento", "Archivio documenti"])

    with tab1:
        selected = st.selectbox("Cliente", clienti["__label"].tolist(), key="v38_doc_cliente")
        cid = int(str(selected).split(" - ")[0])
        tipo = st.selectbox("Tipo documento", ["CERTIFICATO MEDICO", "CONTRATTO", "PRIVACY", "ALTRO"], key="v38_doc_tipo")
        file = st.file_uploader("Carica PDF", type=["pdf"], key="v38_doc_file")
        note = st.text_area("Note documento", key="v38_doc_note")

        if st.button("Carica documento", use_container_width=True, key="v38_doc_upload_btn"):
            if not file:
                st.error("Seleziona un PDF.")
            else:
                ok, path, url_or_err = v38_upload_documento_storage(cid, file, tipo)
                if not ok:
                    st.error("Upload non riuscito.")
                    st.code(f"Bucket: documenti\nPath: {path}\nErrore reale:\n{url_or_err}")
                else:
                    ok2, msg = v38_insert_documento_record(cid, tipo, getattr(file, "name", "documento.pdf"), path, url_or_err, note)
                    st.success("Documento caricato e associato al cliente.") if ok2 else st.warning(msg)
                    st.link_button("Apri documento", url_or_err)

    with tab2:
        selected2 = st.selectbox("Cliente archivio", clienti["__label"].tolist(), key="v38_doc_arch_cliente")
        cid2 = int(str(selected2).split(" - ")[0])
        docs = []
        for col in ["cliente_id", "id_cliente"]:
            try:
                docs = get_supabase().table("documenti_cliente").select("*").eq(col, cid2).order("id", desc=True).execute().data or []
                if docs:
                    break
            except Exception:
                pass
        if not docs:
            st.info("Nessun documento in archivio per questo cliente.")
        for d in docs:
            url = d.get("public_url") or d.get("url") or d.get("url_file")
            tipo = d.get("tipo_documento") or d.get("tipo") or "Documento"
            nome = d.get("nome_file") or d.get("filename") or d.get("storage_path") or d.get("path") or d.get("percorso_file") or ""
            st.markdown(f"**{tipo}** · {nome}")
            if url:
                st.link_button("Apri PDF", url)


