def v38_alert_certificati_df():
    df = v38_load_clienti()
    if df.empty:
        return pd.DataFrame()

    today = pd.Timestamp(v38_today()).normalize()
    rows = []
    possibili = [
        "scadenza_certificato",
        "certificato_scadenza",
        "data_scadenza_certificato",
        "certificato_medico_scadenza",
        "scadenza_certificato_medico",
        "data_certificato",
    ]

    for _, r in df.iterrows():
        cert_date = None
        for col in possibili:
            if col not in df.columns:
                continue
            raw = r.get(col)
            dt = pd.to_datetime(raw, errors="coerce")
            if not pd.isna(dt):
                cert_date = pd.Timestamp(dt).normalize()
                break

        motivo = None
        if cert_date is None:
            motivo = "Certificato mancante"
        elif cert_date < today:
            motivo = f"Certificato scaduto il {cert_date.strftime('%d/%m/%Y')}"

        if motivo:
            rr = r.to_dict()
            rr["_motivo_certificato"] = motivo
            rows.append(rr)

    return pd.DataFrame(rows)


