def render_alert_badge_associa():
    st.header("🔵 Badge/accessi da associare")
    st.caption("V38.08: badge unici, non già associati. Di default mostra solo clienti attivi.")

    df = v38_badge_da_associare_unici()
    if df.empty:
        st.success("Nessun badge/accesso da associare.")
        return

    show_disabled = st.checkbox("Mostra anche clienti disattivati", value=False, key="v3808_badge_show_disabled")
    clienti = v3808_load_clienti(include_disabled=show_disabled)

    if clienti.empty:
        st.info("Nessun cliente disponibile.")
        return

    clienti = clienti.copy()
    clienti["__label"] = clienti.apply(lambda r: v3808_cliente_label(r, show_badge=True), axis=1)

    for _, row in df.iterrows():
        badge = str(row.get("badge_uid") or row.get("badge") or "").strip()
        st.markdown(
            f"""
            <div style="border:1.7px solid #3b82f6;border-radius:18px;background:#f8fbff;padding:14px 16px;margin:12px 0;">
              <div style="font-size:20px;font-weight:950;">Badge {badge}</div>
              <div style="font-size:13px;color:#555;">Accesso: {row.get('data_accesso','')} {row.get('ora_accesso','')} · Stato: {row.get('stato_accesso') or '-'}</div>
            </div>
            """,
            unsafe_allow_html=True
        )
        selected = st.selectbox("Associa a cliente", clienti["__label"].tolist(), key=f"v3808_assoc_badge_{badge}_{row.get('id')}")
        if st.button("✅ Associa badge/accesso", key=f"v3808_assoc_badge_btn_{badge}_{row.get('id')}", use_container_width=True):
            cid = int(str(selected).split(" - ")[0])
            cliente_sel = v38_get_cliente(cid)
            if not v3808_is_cliente_attivo(cliente_sel):
                st.error("Cliente disattivato: riattivalo prima di associare un badge.")
                continue

            ok, msg = v38_insert_badge(cid, badge)
            if ok:
                try:
                    get_supabase().table("accessi_tornello").update({
                        "cliente_id": cid,
                        "stato_accesso": "REGISTRATO_ASSOCIATO_KREO",
                        "note": f"Badge {badge} associato a cliente {cid} - V38.08",
                    }).eq("id", int(float(row.get("id")))).execute()
                except Exception:
                    pass
            st.success(msg) if ok else st.error(msg)
            if ok:
                st.rerun()


