_old_v38_decidi_accesso = v38_decidi_accesso

def v38_decidi_accesso(accesso, azione):
    cid = accesso.get("cliente_id")
    if cid not in [None, "", "nan", "None", 0, "0", 0.0, "0.0"]:
        cliente = v38_get_cliente(cid)
        if cliente and not v3808_is_cliente_attivo(cliente):
            try:
                get_supabase().table("accessi_tornello").update({
                    "stato_accesso": "CLIENTE_DISATTIVATO_DA_VERIFICARE",
                    "note": "V38.08: cliente disattivato, accesso da verificare/riattivare",
                }).eq("id", int(float(accesso.get("id")))).execute()
            except Exception:
                pass
            return False, "Cliente disattivato: riattivalo prima di confermare/scalare la presenza."
    return _old_v38_decidi_accesso(accesso, azione)

decidi_accesso = v38_decidi_accesso




