# ============================================================
# KREO V38.25 SCADENZE COMPLETE RESIDUI
# Base: V38.09.
# Fix bug importi:
# prima "300.0" diventava "3000" perché veniva sempre rimosso il punto.
# Ora:
# - float/int restano float
# - 300.0 -> 300.0
# - "300.00" -> 300.0
# - "300,00" -> 300.0
# - "1.800,00" -> 1800.0
# - "1,800.00" -> 1800.0
# ============================================================

APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3810_parse_money(value):
    if value is None:
        return 0.0

    # Se Supabase restituisce già numero, NON trattarlo come stringa italiana
    if isinstance(value, (int, float)):
        try:
            return float(value)
        except Exception:
            return 0.0

    s = str(value).strip()
    if not s or s.lower() in ["nan", "none", "null"]:
        return 0.0

    s = (
        s.replace("€", "")
         .replace("EUR", "")
         .replace("eur", "")
         .replace(" ", "")
         .strip()
    )

    # Gestione segno negativo
    neg = False
    if s.startswith("-"):
        neg = True
        s = s[1:]

    # Se ci sono sia punto che virgola, capisco quale è il separatore decimale dall'ultimo simbolo
    if "." in s and "," in s:
        if s.rfind(",") > s.rfind("."):
            # formato italiano: 1.800,50
            s = s.replace(".", "").replace(",", ".")
        else:
            # formato inglese: 1,800.50
            s = s.replace(",", "")
    elif "," in s:
        # solo virgola: 300,50
        s = s.replace(".", "").replace(",", ".")
    elif "." in s:
        # solo punto: potrebbe essere 300.0 oppure 1.800
        parts = s.split(".")
        if len(parts) == 2 and len(parts[1]) in [1, 2]:
            # decimale normale
            pass
        elif len(parts) > 2:
            # migliaia tipo 1.800.000
            s = s.replace(".", "")
        else:
            # se parte decimale lunga o ambigua, lascia float provare
            pass

    try:
        val = float(s)
        return -val if neg else val
    except Exception:
        return 0.0


def v3810_get_raw_cliente_importo(cliente):
    """
    Cerca l'importo contrattuale vero.
    Evita campi derivati come importo_pagato/residuo.
    """
    if not cliente:
        return 0.0
    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    preferred = [
        "importo",
        "importo_totale",
        "importo_contratto",
        "totale_contratto",
        "valore_contratto",
        "prezzo",
    ]
    forbidden = [
        "importo_pagato",
        "pagato",
        "residuo",
        "saldo",
    ]

    for k in preferred:
        if k in cliente and k not in forbidden and cliente.get(k) not in [None, "", "nan", "None"]:
            return v3810_parse_money(cliente.get(k))

    return 0.0


