# KREO V38.19 CERTIFICATO MEDICO AUTO SCADENZA
# Base: V38.18B.
# Quando viene caricato un certificato medico, la scadenza viene
# aggiornata automaticamente a +1 anno dalla data di caricamento.
# ============================================================

APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3819_is_certificato_medico(tipo_documento):
    t = str(tipo_documento or "").strip().upper()
    return "CERT" in t or "MEDICO" in t or "MEDICA" in t


def v3819_add_one_year(d):
    try:
        return d.replace(year=d.year + 1)
    except Exception:
        return d + timedelta(days=365)


def v3819_update_certificato_cliente(cliente_id, data_caricamento=None):
    if data_caricamento is None:
        data_caricamento = date.today()
    scadenza = v3819_add_one_year(data_caricamento)

    payload = {
        "certificato_medico": "SÌ",
        "certificato": "SÌ",
        "certificato_consegnato": "SÌ",
        "data_caricamento_certificato": str(data_caricamento),
        "data_certificato": str(data_caricamento),
        "scadenza_certificato": str(scadenza),
        "data_scadenza_certificato": str(scadenza),
        "certificato_medico_scadenza": str(scadenza),
        "scadenza_certificato_medico": str(scadenza),
        "updated_at": datetime.now().isoformat(),
    }

    updated, skipped = [], []

    # Prova update completo
    try:
        get_supabase().table("clienti").update(payload).eq("id", int(float(cliente_id))).execute()
        try:
            st.cache_data.clear()
        except Exception:
            pass
        return True, f"Certificato medico aggiornato: scadenza {scadenza.strftime('%d/%m/%Y')}."
    except Exception:
        pass

    # Fallback campo-per-campo: ignora colonne non presenti
    for k, v in payload.items():
        try:
            get_supabase().table("clienti").update({k: v}).eq("id", int(float(cliente_id))).execute()
            updated.append(k)
        except Exception:
            skipped.append(k)

    try:
        st.cache_data.clear()
    except Exception:
        pass

    if updated:
        return True, f"Certificato medico aggiornato: scadenza {scadenza.strftime('%d/%m/%Y')}."
    return False, "Documento caricato, ma non sono riuscito ad aggiornare la scadenza certificato nella scheda cliente."


def v3819_log_certificato(cliente_id, scadenza):
    payload = {
        "cliente_id": int(float(cliente_id)),
        "tipo": "CERTIFICATO_MEDICO_CARICATO",
        "quantita": 0,
        "motivo": "Caricamento certificato medico con scadenza annuale automatica",
        "riferimento": f"scadenza_certificato={scadenza}",
        "created_at": datetime.now().isoformat(),
    }
    for table in ["cronologia", "log_operazioni", "movimenti_lezioni"]:
        try:
            get_supabase().table(table).insert(payload).execute()
            return
        except Exception:
            pass


def v3819_after_document_upload(cliente_id, tipo_documento):
    if not v3819_is_certificato_medico(tipo_documento):
        return False, ""
    today = date.today()
    scadenza = v3819_add_one_year(today)
    ok, msg = v3819_update_certificato_cliente(cliente_id, today)
    try:
        v3819_log_certificato(cliente_id, scadenza)
    except Exception:
        pass
    return ok, msg


