    st.header("📄 Documenti e certificati cliente")
    st.caption("V38.19: il certificato medico caricato imposta automaticamente la scadenza annuale.")

    try:
        _old_render_staff_documenti_v3819()
    except Exception as e:
        st.warning(f"Vista documenti precedente non disponibile: {e}")

    st.divider()
    st.markdown("### 🩺 Caricamento rapido certificato medico")
    st.caption("Usa questa sezione per caricare il certificato e aggiornare automaticamente la scadenza a +1 anno.")

    try:
        clienti = v3815_load_clienti_direct() if "v3815_load_clienti_direct" in globals() else v38_load_clienti()
    except Exception:
        clienti = pd.DataFrame()

    if clienti is None or clienti.empty:
        st.info("Nessun cliente disponibile.")
        return

    clienti = clienti.copy()
    try:
        clienti["__label"] = clienti.apply(lambda r: v3808_cliente_label(r, show_badge=False), axis=1)
    except Exception:
        clienti["__label"] = clienti.apply(lambda r: f"{r.get('id')} - {v38_cliente_nome(r)}", axis=1)

    selected = st.selectbox("Cliente", clienti["__label"].tolist(), key="v3819_cert_cliente")
    cliente_id = int(str(selected).split(" - ")[0])

    file = st.file_uploader("Carica certificato medico PDF", type=["pdf"], key=f"v3819_cert_upload_{cliente_id}")
    note = st.text_area("Note certificato", key=f"v3819_cert_note_{cliente_id}")

    if st.button("📄 Carica certificato medico e aggiorna scadenza", key=f"v3819_cert_btn_{cliente_id}", use_container_width=True):
        if not file:
            st.error("Seleziona un PDF.")
            return

        filename = f"certificato_medico_{datetime.now().strftime('%Y%m%d%H%M%S')}_{file.name}"
        storage_path = f"cliente_{cliente_id}/{filename}"
        uploaded = False
        upload_msg = ""

        for bucket in ["documenti", "documenti_pubblici", "documenti_privati"]:
            try:
                get_supabase().storage.from_(bucket).upload(
                    storage_path,
                    file.getvalue(),
                    {"content-type": "application/pdf", "upsert": "true"}
                )
                uploaded = True
                break
            except Exception as e:
                upload_msg = str(e)

        if not uploaded:
            st.error(f"Non sono riuscito a caricare il PDF nel bucket documenti: {upload_msg}")
            return

        doc_payload = {
            "cliente_id": int(float(cliente_id)),
            "tipo_documento": "CERTIFICATO MEDICO",
            "nome_file": filename,
            "storage_path": storage_path,
            "note": note,
            "data_caricamento": str(date.today()),
            "created_at": datetime.now().isoformat(),
        }
        for table in ["documenti_cliente", "documenti_clienti"]:
            try:
                get_supabase().table(table).insert(doc_payload).execute()
                break
            except Exception:
                pass

        ok, msg = v3819_after_document_upload(cliente_id, "CERTIFICATO MEDICO")
        if ok:
            st.success(f"Certificato caricato. {msg}")
        else:
            st.warning(f"Certificato caricato, ma attenzione: {msg}")
        st.rerun()


