def v3820_clienti_overview_df():
    clienti = v3820_load_clienti_direct_safe()
    docs = v3820_load_docs_safe()
    pag = v3820_load_pagamenti_safe()
    rows = []

    if clienti is None or clienti.empty:
        return pd.DataFrame()

    for _, c in clienti.iterrows():
        cid = c.get("id")

        try:
            attivo = "ATTIVO" if v3808_is_cliente_attivo(c) else "DISATTIVATO"
        except Exception:
            attivo = str(c.get("stato") or c.get("stato_cliente") or "ATTIVO")

        try:
            totale, usate, residue = v38_contatori_cliente(c)
        except Exception:
            totale, usate, residue = 0, 0, 0

        try:
            importo_contratto = v3810_get_raw_cliente_importo(c.to_dict())
        except Exception:
            try:
                importo_contratto = float(c.get("importo") or 0)
            except Exception:
                importo_contratto = 0.0

        pagato, n_pag = v3820_pagamenti_sum_safe(pag, cid)
        residuo_calc = max(float(importo_contratto or 0) - float(pagato or 0), 0.0)
        n_docs, tipi_docs, cert_doc = v3820_docs_info_safe(docs, cid)

        docs_c = pd.DataFrame()
        if docs is not None and not docs.empty and cid is not None:
            try:
                if "v3815_doc_cliente_id" in globals():
                    doc_ids = pd.to_numeric(docs.apply(v3815_doc_cliente_id, axis=1), errors="coerce")
                    docs_c = docs[doc_ids == int(float(cid))]
            except Exception:
                docs_c = pd.DataFrame()

        cert_status, cert_scad = v3820_cert_status_safe(c, docs_c)

        rows.append({
            "ID": cid,
            "Cliente": v38_cliente_nome(c),
            "Stato": attivo,
            "Telefono": c.get("cellulare") or c.get("telefono") or "",
            "Email": c.get("email") or "",
            "Pacchetto": c.get("pacchetto") or "",
            "Tipo abbonamento": c.get("tipo_abbonamento") or c.get("tipologia_abbonamento") or "",
            "Scadenza rata": v3820_get_scadenza_rata_cliente(c),
            "Scadenza abbonamento": v3820_get_scadenza_abbonamento_cliente(c),
            "Lezioni totali": totale,
            "Lezioni usate": usate,
            "Lezioni residue": residue,
            "Importo contratto": round(importo_contratto, 2),
            "Pagato": round(pagato, 2),
            "Residuo calcolato": round(residuo_calc, 2),
            "N. pagamenti": n_pag,
            "N. documenti": n_docs,
            "Tipi documenti": tipi_docs,
            "Certificato": cert_status,
            "Scadenza certificato": cert_scad.strftime("%d/%m/%Y") if cert_scad else "",
            "Note": c.get("note") or "",
        })

    return pd.DataFrame(rows)


