def render_v3815_clienti_overview():
    st.header("👥 Database clienti")
    st.caption("V38.20: tabella clienti interattiva con apertura Cliente 360 e scadenza rata da anagrafica.")

    df = v3820_clienti_overview_df()
    if df.empty:
        st.info("Nessun cliente presente.")
        return

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Clienti totali", len(df))
    c2.metric("Attivi", len(df[df["Stato"].astype(str).str.upper() == "ATTIVO"]))
    c3.metric("Disattivati", len(df[df["Stato"].astype(str).str.upper() != "ATTIVO"]))
    c4.metric("Certificati mancanti/scaduti", len(df[df["Certificato"].isin(["MANCANTE", "SCADUTO"])]))

    show_disabled = st.checkbox("Mostra anche clienti disattivati", value=True, key="v3820_overview_show_dis")
    only_cert = st.checkbox(
        "Mostra solo certificati mancanti/scaduti",
        value=st.session_state.get("v3815_overview_cert_only", False),
        key="v3820_overview_cert_only"
    )
    search = st.text_input("Cerca cliente / telefono / email", key="v3820_overview_search")

    view = df.copy()
    if not show_disabled:
        view = view[view["Stato"].astype(str).str.upper() == "ATTIVO"]
    if only_cert:
        view = view[view["Certificato"].isin(["MANCANTE", "SCADUTO"])]
    if search:
        s = search.lower().strip()
        mask = pd.Series(False, index=view.index)
        for col in ["Cliente", "Telefono", "Email", "Pacchetto", "Tipi documenti"]:
            if col in view.columns:
                mask = mask | view[col].astype(str).str.lower().str.contains(s, na=False)
        view = view[mask]

    if view.empty:
        st.info("Nessun cliente trovato con questi filtri.")
        return

    st.markdown("### Apri scheda cliente")
    labels = [
        f"{int(float(r['ID']))} - {r['Cliente']} | tel {r['Telefono']} | rata {r['Scadenza rata'] or '-'}"
        for _, r in view.iterrows()
    ]
    selected = st.selectbox("Seleziona cliente", labels, key="v3820_select_cliente_from_overview")

    cc1, cc2 = st.columns([1, 1])
    with cc1:
        if st.button("👤 Apri Cliente 360", key="v3820_open_cliente360", use_container_width=True):
            cliente_id = int(str(selected).split(" - ")[0])
            st.session_state["cliente_360_id"] = cliente_id
            st.session_state["cliente_preselezionato_id"] = cliente_id
            st.session_state.pop("reception_internal_view", None)
            st.session_state.pop("reception_view", None)
            render_v37_cliente360()
            st.stop()

    with cc2:
        st.download_button(
            "⬇️ Scarica elenco clienti CSV",
            view.to_csv(index=False).encode("utf-8-sig"),
            file_name="kreo_clienti_overview.csv",
            mime="text/csv",
            use_container_width=True,
        )

    st.markdown("### Tabella clienti")
    preferred_cols = [
        "ID", "Cliente", "Stato", "Telefono", "Email", "Pacchetto",
        "Tipo abbonamento", "Scadenza rata", "Scadenza abbonamento",
        "Lezioni totali", "Lezioni usate", "Lezioni residue",
        "Importo contratto", "Pagato", "Residuo calcolato",
        "N. pagamenti", "N. documenti", "Certificato", "Scadenza certificato",
        "Tipi documenti", "Note"
    ]
    cols = [c for c in preferred_cols if c in view.columns]
    st.dataframe(view[cols], use_container_width=True, hide_index=True)

    try:
        v3818b_firma_clienti_corretta()
    except Exception:
        pass




