APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3821_is_missing(value):
    if value is None:
        return True

    try:
        if pd.isna(value):
            return True
    except Exception:
        pass

    s = str(value).strip()
    return s == "" or s.lower() in {
        "none", "nan", "nat", "<na>", "null", "n/a",
    }


def v3821_format_date(value):
    if v3821_is_missing(value):
        return ""

    try:
        d = pd.to_datetime(value, errors="coerce")
        if not pd.isna(d):
            return d.strftime("%d/%m/%Y")
    except Exception:
        pass

    s = str(value).strip()
    return "" if v3821_is_missing(s) else s


def v3820_get_scadenza_rata_cliente(cliente):
    if cliente is None:
        return ""

    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    keys = [
        "scadenza_rata",
        "scadenza_prossima_rata",
        "prossima_scadenza_pagamento",
        "data_scadenza_rata",
        "scadenza_prossima_rata_auto",
        "data_prossima_rata",
        "next_payment_date",
    ]

    for key in keys:
        value = cliente.get(key)
        if v3821_is_missing(value):
            continue

        formatted = v3821_format_date(value)
        if formatted:
            return formatted

    return ""


def v3820_get_scadenza_abbonamento_cliente(cliente):
    if cliente is None:
        return ""

    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    keys = [
        "scadenza_abbonamento",
        "data_scadenza",
        "data_fine_pacchetto",
        "scadenza",
        "data_scadenza_abbonamento",
    ]

    for key in keys:
        value = cliente.get(key)
        if v3821_is_missing(value):
            continue

        formatted = v3821_format_date(value)
        if formatted:
            return formatted

    return ""




# ============================================================
# KREO V38.25 SCADENZE COMPLETE RESIDUI ANAGRAFICA
# Base: V38.21.
# Fix:
# - più nomi colonna supportati
# - priorità alle scadenze modificate manualmente
# - fallback calcolato da data iniziale + tipologia
# ============================================================

APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3822_first_valid_value(cliente, keys):
    if cliente is None:
        return None
    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # confronto case-insensitive per supportare colonne scritte diversamente
    normalized = {str(k).strip().lower(): v for k, v in cliente.items()}

    for key in keys:
        value = cliente.get(key)
        if not v3821_is_missing(value):
            return value

        value = normalized.get(str(key).strip().lower())
        if not v3821_is_missing(value):
            return value

    return None


def v3822_parse_date(value):
    if v3821_is_missing(value):
        return None

    try:
        out = pd.to_datetime(value, errors="coerce", dayfirst=False)
        if not pd.isna(out):
            return out
    except Exception:
        pass

    try:
        out = pd.to_datetime(value, errors="coerce", dayfirst=True)
        if not pd.isna(out):
            return out
    except Exception:
        pass

    return None


def v3822_format_ts(ts):
    if ts is None or pd.isna(ts):
        return ""
    try:
        return ts.strftime("%d/%m/%Y")
    except Exception:
        return str(ts)


def v3822_add_period(start_date, tipologia, context="abbonamento"):
    if start_date is None:
        return None

    tipo = str(tipologia or "").strip().upper()

    if "UNICA" in tipo:
        # per la rata unica non esiste una rata successiva
        return None

    months = None
    days = None

    if "SETTIMAN" in tipo:
        days = 7
    elif "QUINDIC" in tipo:
        days = 15
    elif "MENSIL" in tipo:
        months = 1
    elif "BIMESTR" in tipo:
        months = 2
    elif "TRIMESTR" in tipo:
        months = 3
    elif "QUADRIMESTR" in tipo:
        months = 4
    elif "SEMESTR" in tipo:
        months = 6
    elif "ANNUAL" in tipo:
        months = 12

    if months is not None:
        return start_date + pd.DateOffset(months=months)
    if days is not None:
        return start_date + pd.Timedelta(days=days)

    # Per PERSONALIZZATO non inventiamo una data
    return None


def v3820_get_scadenza_rata_cliente(cliente):
    if cliente is None:
        return ""
    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # 1. Prima le scadenze esplicite/modificate
    explicit_keys = [
        "scadenza_rata_modificata",
        "data_scadenza_rata_modificata",
        "prossima_scadenza_rata_modificata",
        "scadenza_prossima_rata_modificata",
        "scadenza_rata",
        "scadenza_prossima_rata",
        "prossima_scadenza_pagamento",
        "data_scadenza_rata",
        "scadenza_prossima_rata_auto",
        "data_prossima_rata",
        "prossima_rata",
        "scadenza_pagamento",
        "data_prossimo_pagamento",
        "next_payment_date",
        "next_installment_date",
    ]

    explicit = v3822_first_valid_value(cliente, explicit_keys)
    if explicit is not None:
        parsed = v3822_parse_date(explicit)
        if parsed is not None:
            return v3822_format_ts(parsed)

    # 2. Fallback: ricostruzione da data base + tipologia pagamento
    start_keys = [
        "data_ultimo_pagamento",
        "ultima_data_pagamento",
        "data_pagamento",
        "data_inizio_pagamento",
        "data_inizio_rate",
        "data_inizio_pacchetto",
        "data_inizio",
        "data_iscrizione",
        "created_at",
    ]
    tipo_keys = [
        "tipo_pagamento",
        "tipologia_pagamento",
        "frequenza_pagamento",
        "modalita_rate",
        "piano_pagamento",
    ]

    start_val = v3822_first_valid_value(cliente, start_keys)
    tipo_val = v3822_first_valid_value(cliente, tipo_keys)

    start_date = v3822_parse_date(start_val)
    calculated = v3822_add_period(start_date, tipo_val, context="rata")

    return v3822_format_ts(calculated)


def v3820_get_scadenza_abbonamento_cliente(cliente):
    if cliente is None:
        return ""
    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # 1. Prima le scadenze esplicite/modificate
    explicit_keys = [
        "scadenza_abbonamento_modificata",
        "data_scadenza_abbonamento_modificata",
        "scadenza_pacchetto_modificata",
        "scadenza_abbonamento",
        "data_scadenza_abbonamento",
        "data_scadenza",
        "data_fine_pacchetto",
        "scadenza_pacchetto",
        "data_fine_abbonamento",
        "fine_abbonamento",
        "scadenza",
        "subscription_expiry",
        "expiry_date",
    ]

    explicit = v3822_first_valid_value(cliente, explicit_keys)
    if explicit is not None:
        parsed = v3822_parse_date(explicit)
        if parsed is not None:
            return v3822_format_ts(parsed)

    # 2. Fallback: ricostruzione da data inizio + tipologia abbonamento
    start_keys = [
        "data_inizio_pacchetto",
        "data_inizio_abbonamento",
        "inizio_abbonamento",
        "data_inizio",
        "data_iscrizione",
        "created_at",
    ]
    tipo_keys = [
        "tipo_abbonamento",
        "tipologia_abbonamento",
        "durata_abbonamento",
        "frequenza_abbonamento",
    ]

    start_val = v3822_first_valid_value(cliente, start_keys)
    tipo_val = v3822_first_valid_value(cliente, tipo_keys)

    start_date = v3822_parse_date(start_val)
    calculated = v3822_add_period(start_date, tipo_val, context="abbonamento")

    return v3822_format_ts(calculated)




# ============================================================
# KREO V38.25 SCADENZE COMPLETE RESIDUI
# Base: V38.22.
#
# Regole:
# - niente fallback su created_at
# - abbonamento calcolato solo da data inizio pacchetto/abbonamento
# - rata calcolata da ultimo pagamento o data inizio rate/pacchetto
# - scadenze manuali specifiche sempre prioritarie
# - scadenze generiche validate contro durata dichiarata
# ============================================================

APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3823_period_months(tipo):
    t = str(tipo or "").strip().upper()

    if "MENSIL" in t:
        return 1
    if "BIMESTR" in t:
        return 2
    if "TRIMESTR" in t:
        return 3
    if "QUADRIMESTR" in t:
        return 4
    if "SEMESTR" in t:
        return 6
    if "ANNUAL" in t:
        return 12

    return None


def v3823_period_days(tipo):
    t = str(tipo or "").strip().upper()

    if "SETTIMAN" in t:
        return 7
    if "QUINDIC" in t:
        return 15

    return None


def v3823_expected_date(start_date, tipo):
    if start_date is None:
        return None

    months = v3823_period_months(tipo)
    if months is not None:
        return start_date + pd.DateOffset(months=months)

    days = v3823_period_days(tipo)
    if days is not None:
        return start_date + pd.Timedelta(days=days)

    return None


def v3823_dates_are_coherent(saved_date, expected_date, tolerance_days=7):
    if saved_date is None or expected_date is None:
        return True

    try:
        delta = abs((saved_date.normalize() - expected_date.normalize()).days)
        return delta <= tolerance_days
    except Exception:
        return True


def v3823_manual_date(cliente, keys):
    value = v3822_first_valid_value(cliente, keys)
    return v3822_parse_date(value)


def v3820_get_scadenza_abbonamento_cliente(cliente):
    if cliente is None:
        return ""

    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # 1. Override manuale vero e proprio: sempre prioritario.
    manual_keys = [
        "scadenza_abbonamento_modificata",
        "data_scadenza_abbonamento_modificata",
        "scadenza_pacchetto_modificata",
        "manual_scadenza_abbonamento",
    ]
    manual_date = v3823_manual_date(cliente, manual_keys)
    if manual_date is not None:
        return v3822_format_ts(manual_date)

    # 2. Data inizio reale. Non usare created_at o data iscrizione.
    start_keys = [
        "data_inizio_pacchetto",
        "data_inizio_abbonamento",
        "inizio_abbonamento",
        "data_attivazione_abbonamento",
        "data_attivazione_pacchetto",
        "data_inizio",
    ]
    tipo_keys = [
        "tipo_abbonamento",
        "tipologia_abbonamento",
        "durata_abbonamento",
        "frequenza_abbonamento",
    ]

    start_date = v3822_parse_date(v3822_first_valid_value(cliente, start_keys))
    tipo = v3822_first_valid_value(cliente, tipo_keys)
    expected = v3823_expected_date(start_date, tipo)

    # 3. Data salvata generica.
    saved_keys = [
        "scadenza_abbonamento",
        "data_scadenza_abbonamento",
        "data_scadenza",
        "data_fine_pacchetto",
        "scadenza_pacchetto",
        "data_fine_abbonamento",
        "fine_abbonamento",
        "scadenza",
        "subscription_expiry",
        "expiry_date",
    ]
    saved = v3822_parse_date(v3822_first_valid_value(cliente, saved_keys))

    # Se abbiamo data inizio + durata, il dato deve essere coerente.
    if expected is not None:
        if saved is None or not v3823_dates_are_coherent(saved, expected):
            return v3822_format_ts(expected)
        return v3822_format_ts(saved)

    # Se non possiamo calcolare, usiamo una scadenza esplicita già salvata.
    if saved is not None:
        return v3822_format_ts(saved)

    # Nessuna data inventata.
    return ""


def v3820_get_scadenza_rata_cliente(cliente):
    if cliente is None:
        return ""

    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # 1. Override manuale sempre prioritario.
    manual_keys = [
        "scadenza_rata_modificata",
        "data_scadenza_rata_modificata",
        "prossima_scadenza_rata_modificata",
        "scadenza_prossima_rata_modificata",
        "manual_scadenza_rata",
    ]
    manual_date = v3823_manual_date(cliente, manual_keys)
    if manual_date is not None:
        return v3822_format_ts(manual_date)

    tipo_keys = [
        "tipo_pagamento",
        "tipologia_pagamento",
        "frequenza_pagamento",
        "modalita_rate",
        "piano_pagamento",
    ]
    tipo = v3822_first_valid_value(cliente, tipo_keys)

    tipo_upper = str(tipo or "").strip().upper()
    if "UNICA" in tipo_upper:
        return ""

    # 2. Base reale: ultimo pagamento o data avvio rate/pacchetto.
    start_keys = [
        "data_ultimo_pagamento",
        "ultima_data_pagamento",
        "data_inizio_rate",
        "data_inizio_pagamento",
        "data_attivazione_pagamento",
        "data_inizio_pacchetto",
        "data_inizio_abbonamento",
        "data_inizio",
    ]
    start_date = v3822_parse_date(v3822_first_valid_value(cliente, start_keys))
    expected = v3823_expected_date(start_date, tipo)

    # 3. Data rata già salvata.
    saved_keys = [
        "scadenza_rata",
        "scadenza_prossima_rata",
        "prossima_scadenza_pagamento",
        "data_scadenza_rata",
        "scadenza_prossima_rata_auto",
        "data_prossima_rata",
        "prossima_rata",
        "scadenza_pagamento",
        "data_prossimo_pagamento",
        "next_payment_date",
        "next_installment_date",
    ]
    saved = v3822_parse_date(v3822_first_valid_value(cliente, saved_keys))

    if expected is not None:
        if saved is None or not v3823_dates_are_coherent(saved, expected):
            return v3822_format_ts(expected)
        return v3822_format_ts(saved)

    if saved is not None:
        return v3822_format_ts(saved)

    return ""


# Salvataggio manuale: prova anche i campi specifici di override.
_old_v3813_update_cliente_dates_v3823 = v3813_update_cliente_dates

def v3813_update_cliente_dates(cliente_id, scadenza_rata=None, scadenza_abbonamento=None, motivo=""):
    values = {
        "updated_at": datetime.now().isoformat(),
    }

    if scadenza_rata:
        values.update({
            "scadenza_rata_modificata": str(scadenza_rata),
            "data_scadenza_rata_modificata": str(scadenza_rata),
            "scadenza_rata": str(scadenza_rata),
            "scadenza_prossima_rata": str(scadenza_rata),
            "prossima_scadenza_pagamento": str(scadenza_rata),
            "data_scadenza_rata": str(scadenza_rata),
        })

    if scadenza_abbonamento:
        values.update({
            "scadenza_abbonamento_modificata": str(scadenza_abbonamento),
            "data_scadenza_abbonamento_modificata": str(scadenza_abbonamento),
            "scadenza_abbonamento": str(scadenza_abbonamento),
            "data_scadenza_abbonamento": str(scadenza_abbonamento),
            "data_scadenza": str(scadenza_abbonamento),
            "data_fine_pacchetto": str(scadenza_abbonamento),
        })

    try:
        ok, updated, skipped = v3813_update_cliente_safe_local(cliente_id, values)
    except Exception:
        ok, updated, skipped = False, [], []

    payload_log = {
        "cliente_id": int(float(cliente_id)),
        "tipo": "MODIFICA_SCADENZE",
        "quantita": 0,
        "motivo": motivo,
        "riferimento": (
            f"scadenza_rata={scadenza_rata}; "
            f"scadenza_abbonamento={scadenza_abbonamento}"
        ),
        "created_at": datetime.now().isoformat(),
    }

    for table in ["cronologia", "log_operazioni", "movimenti_lezioni"]:
        try:
            get_supabase().table(table).insert(payload_log).execute()
            break
        except Exception:
            pass

    try:
        st.cache_data.clear()
    except Exception:
        pass

    if ok:
        return True, "Scadenze manuali aggiornate correttamente."

    # Fallback alla logica precedente, se nessun campo è aggiornabile.
    try:
        return _old_v3813_update_cliente_dates_v3823(
            cliente_id,
            scadenza_rata,
            scadenza_abbonamento,
            motivo,
        )
    except Exception:
        return False, "Non sono riuscito ad aggiornare le scadenze."




# ============================================================
# KREO V38.24 RECEPTION & CLIENTI UX FIX
# Base: V38.23
#
# Fix:
# 1. Se il cliente ha saldato tutto, scadenza rata = scadenza abbonamento
# 2. Normalizzazione pacchetti duplicati
# 3. Scadenza abbonamento calcolata anche da data iscrizione, mai da created_at
# 4. Box Clienti stessa altezza degli altri KPI
# 5. Tabella clienti più elegante e meno tecnica
# ============================================================

APP_VERSION = "KREO V38.25 SCADENZE COMPLETE RESIDUI"


def v3824_normalize_package(value):
    raw = str(value or "").strip()
    upper = raw.upper()

    aliases = {
        "PACCHETTO COACHING IN SEDE": "COACHING IN SEDE",
        "COACHING IN SEDE": "COACHING IN SEDE",
        "PACCHETTO LUXURY": "LUXURY",
        "LUXURY": "LUXURY",
        "PACCHETTO GOLD": "GOLD",
        "GOLD": "GOLD",
        "PACCHETTO VIP": "VIP",
        "VIP": "VIP",
        "PACCHETTO PERSONALIZZATO": "PERSONALIZZATO",
        "PERSONALIZZATO": "PERSONALIZZATO",
    }

    return aliases.get(upper, raw or "-")


def v3824_money(value):
    try:
        number = float(value or 0)
    except Exception:
        number = 0.0

    formatted = f"{number:,.2f}"
    formatted = formatted.replace(",", "X").replace(".", ",").replace("X", ".")
    return f"€ {formatted}"


def v3824_is_fully_paid(contract_amount, paid_amount):
    try:
        contract_amount = float(contract_amount or 0)
        paid_amount = float(paid_amount or 0)
    except Exception:
        return False

    if contract_amount <= 0:
        return False

    return paid_amount >= contract_amount - 0.01


def v3820_get_scadenza_abbonamento_cliente(cliente):
    if cliente is None:
        return ""

    if isinstance(cliente, pd.Series):
        cliente = cliente.to_dict()

    # 1. Override manuale: sempre prioritario.
    manual_keys = [
        "scadenza_abbonamento_modificata",
        "data_scadenza_abbonamento_modificata",
        "scadenza_pacchetto_modificata",
        "manual_scadenza_abbonamento",
    ]
    manual_date = v3823_manual_date(cliente, manual_keys)
    if manual_date is not None:
        return v3822_format_ts(manual_date)

    # 2. Tipologia abbonamento.
    tipo_keys = [
        "tipo_abbonamento",
        "tipologia_abbonamento",
        "durata_abbonamento",
        "frequenza_abbonamento",
    ]
    tipo = v3822_first_valid_value(cliente, tipo_keys)

    # 3. Data iniziale reale.
    # Data iscrizione è ammessa solo come ultimo fallback operativo.
    # created_at resta escluso.
    start_keys = [
        "data_inizio_pacchetto",
        "data_inizio_abbonamento",
        "inizio_abbonamento",
        "data_attivazione_abbonamento",
        "data_attivazione_pacchetto",
        "data_inizio",
        "data_iscrizione",
    ]
    start_date = v3822_parse_date(v3822_first_valid_value(cliente, start_keys))
    expected = v3823_expected_date(start_date, tipo)

    # 4. Data esplicita salvata.
    saved_keys = [
        "scadenza_abbonamento",
        "data_scadenza_abbonamento",
        "data_scadenza",
        "data_fine_pacchetto",
        "scadenza_pacchetto",
        "data_fine_abbonamento",
        "fine_abbonamento",
        "scadenza",
        "subscription_expiry",
        "expiry_date",
    ]
    saved = v3822_parse_date(v3822_first_valid_value(cliente, saved_keys))

    # Se il sistema può calcolare una data coerente, la usa quando
    # quella salvata manca o è incompatibile con la durata.
    if expected is not None:
        if saved is None or not v3823_dates_are_coherent(saved, expected):
            return v3822_format_ts(expected)
        return v3822_format_ts(saved)

    if saved is not None:
        return v3822_format_ts(saved)

    return ""


def v3824_clienti_overview_df():
    clienti = v3820_load_clienti_direct_safe()
    docs = v3820_load_docs_safe()
    pagamenti = v3820_load_pagamenti_safe()
    rows = []

    if clienti is None or clienti.empty:
        return pd.DataFrame()

    for _, cliente in clienti.iterrows():
        cliente_id = cliente.get("id")

        try:
            active = v3808_is_cliente_attivo(cliente)
        except Exception:
            stato_raw = str(
                cliente.get("stato")
                or cliente.get("stato_cliente")
                or "ATTIVO"
            ).upper()
            active = stato_raw not in {"DISATTIVATO", "INATTIVO", "ARCHIVIATO"}

        stato = "🟢 Attivo" if active else "⚪ Disattivato"

        try:
            lezioni_totali, lezioni_usate, lezioni_residue = v38_contatori_cliente(cliente)
        except Exception:
            lezioni_totali, lezioni_usate, lezioni_residue = 0, 0, 0

        try:
            importo_contratto = float(v3810_get_raw_cliente_importo(cliente.to_dict()) or 0)
        except Exception:
            try:
                importo_contratto = float(cliente.get("importo") or 0)
            except Exception:
                importo_contratto = 0.0

        pagato, numero_pagamenti = v3820_pagamenti_sum_safe(
            pagamenti,
            cliente_id,
        )
        residuo = max(importo_contratto - float(pagato or 0), 0.0)

        numero_documenti, tipi_documenti, _ = v3820_docs_info_safe(
            docs,
            cliente_id,
        )

        documenti_cliente = pd.DataFrame()
        if docs is not None and not docs.empty and cliente_id is not None:
            try:
                if "v3815_doc_cliente_id" in globals():
                    document_ids = pd.to_numeric(
                        docs.apply(v3815_doc_cliente_id, axis=1),
                        errors="coerce",
                    )
                    documenti_cliente = docs[
                        document_ids == int(float(cliente_id))
                    ]
            except Exception:
                documenti_cliente = pd.DataFrame()

        stato_certificato, scadenza_certificato = v3820_cert_status_safe(
            cliente,
            documenti_cliente,
        )

        scadenza_abbonamento = v3820_get_scadenza_abbonamento_cliente(cliente)
        scadenza_rata = v3820_get_scadenza_rata_cliente(cliente)

        # Regola contabile definitiva:
        # se tutto il contratto è saldato, non esiste una rata intermedia
        # e la data rata coincide con la fine dell'abbonamento.
        if v3824_is_fully_paid(importo_contratto, pagato):
            scadenza_rata = scadenza_abbonamento

        rows.append({
            "ID": cliente_id,
            "Cliente": v38_cliente_nome(cliente),
            "Stato": stato,
            "Telefono": cliente.get("cellulare") or cliente.get("telefono") or "-",
            "Email": cliente.get("email") or "-",
            "Pacchetto": v3824_normalize_package(cliente.get("pacchetto")),
            "Abbonamento": (
                cliente.get("tipo_abbonamento")
                or cliente.get("tipologia_abbonamento")
                or "-"
            ),
            "Prossima rata": scadenza_rata or "-",
            "Scadenza abbonamento": scadenza_abbonamento or "-",
            "Lezioni": f"{int(lezioni_residue)}/{int(lezioni_totali)}",
            "Contratto": v3824_money(importo_contratto),
            "Pagato": v3824_money(pagato),
            "Residuo": v3824_money(residuo),
            "Pagamenti": int(numero_pagamenti),
            "Documenti": int(numero_documenti),
            "Certificato": stato_certificato or "-",
            "Scadenza certificato": (
                scadenza_certificato.strftime("%d/%m/%Y")
                if scadenza_certificato
                else "-"
            ),
            "Tipi documenti": tipi_documenti or "-",
            "Note": cliente.get("note") or "",
            # campi di supporto non mostrati
            "_attivo": active,
            "_residuo_num": residuo,
        })

    return pd.DataFrame(rows)


# La nuova vista diventa la fonte unica per overview e alert.
v3820_clienti_overview_df = v3824_clienti_overview_df
v3815_clienti_overview_df = v3824_clienti_overview_df


