def render_v3815_clienti_overview():
    st.header("👥 Clienti KREO")
    st.caption(
        "Anagrafica operativa con abbonamenti, rate, documenti e situazione contabile."
    )

    df = v3824_clienti_overview_df()
    if df.empty:
        st.info("Nessun cliente presente.")
        return

    total = len(df)
    active_count = int(df["_attivo"].fillna(False).sum())
    disabled_count = total - active_count
    cert_alerts = int(
        df["Certificato"].astype(str).str.upper().isin(
            ["MANCANTE", "SCADUTO"]
        ).sum()
    )

    m1, m2, m3, m4 = st.columns(4)
    m1.metric("Clienti", total)
    m2.metric("Attivi", active_count)
    m3.metric("Disattivati", disabled_count)
    m4.metric("Certificati da gestire", cert_alerts)

    f1, f2 = st.columns([2.2, 1])
    with f1:
        search = st.text_input(
            "Cerca per cliente, telefono, email o pacchetto",
            key="v3824_client_search",
            placeholder="Scrivi nome, telefono, email...",
        )
    with f2:
        show_disabled = st.checkbox(
            "Mostra disattivati",
            value=False,
            key="v3824_show_disabled",
        )

    view = df.copy()

    if not show_disabled:
        view = view[view["_attivo"] == True]

    if search:
        needle = search.strip().lower()
        mask = pd.Series(False, index=view.index)
        for column in ["Cliente", "Telefono", "Email", "Pacchetto"]:
            mask = mask | view[column].astype(str).str.lower().str.contains(
                needle,
                na=False,
                regex=False,
            )
        view = view[mask]

    if view.empty:
        st.info("Nessun cliente corrisponde ai filtri selezionati.")
        return

    st.markdown("### Apri scheda cliente")
    labels = [
        (
            f"{int(float(row['ID']))} - {row['Cliente']} · "
            f"{row['Pacchetto']} · rata {row['Prossima rata']}"
        )
        for _, row in view.iterrows()
    ]
    selected = st.selectbox(
        "Cliente",
        labels,
        key="v3824_select_client",
        label_visibility="collapsed",
    )

    action_col, export_col = st.columns(2)

    with action_col:
        if st.button(
            "👤 Apri Cliente 360",
            key="v3824_open_client_360",
            use_container_width=True,
        ):
            selected_client_id = int(str(selected).split(" - ")[0])
            st.session_state["cliente_360_id"] = selected_client_id
            st.session_state["cliente_preselezionato_id"] = selected_client_id
            st.session_state.pop("reception_internal_view", None)
            st.session_state.pop("reception_view", None)
            render_v37_cliente360()
            st.stop()

    with export_col:
        export_view = view.drop(
            columns=["_attivo", "_residuo_num"],
            errors="ignore",
        )
        st.download_button(
            "⬇️ Esporta clienti CSV",
            export_view.to_csv(index=False).encode("utf-8-sig"),
            file_name="kreo_clienti.csv",
            mime="text/csv",
            use_container_width=True,
        )

    st.markdown("### Situazione clienti")
    v3824_render_table(view)

    try:
        v3818b_firma_clienti_corretta()
    except Exception:
        pass


