def render_reception_center():
    internal_view = st.session_state.get("reception_internal_view")

    if internal_view in [
        "clienti_overview",
        "clienti_overview_cert",
        "clienti_overview_residui",
    ]:
        if internal_view == "clienti_overview_cert":
            st.session_state["v3815_overview_cert_only"] = True
        render_v3815_clienti_overview()
        return

    if internal_view == "badge_alert":
        render_alert_badge_associa()
        return

    if internal_view == "documenti":
        render_staff_documenti()
        return

    if kreo_render_reception_internal_view_if_any():
        return

    st.header("🏠 Reception Center")
    st.caption("Dashboard operativa KREO.")

    clienti = v3820_load_clienti_direct_safe()
    total_clienti = 0 if clienti is None or clienti.empty else len(clienti)

    try:
        accessi = v38_load_accessi()
    except Exception:
        accessi = pd.DataFrame()

    agenda_count = 0
    accessi_count = 0
    incassi_oggi = 0.0

    try:
        lezioni = load_lezioni()
        date_column = (
            "data_lezione"
            if "data_lezione" in lezioni.columns
            else "data" if "data" in lezioni.columns else None
        )
        if date_column:
            agenda_count = len(
                lezioni[
                    lezioni[date_column].astype(str).str[:10]
                    == str(v38_today())
                ]
            )
    except Exception:
        pass

    try:
        if (
            accessi is not None
            and not accessi.empty
            and "data_accesso" in accessi.columns
        ):
            accessi_count = len(
                accessi[
                    accessi["data_accesso"].astype(str).str[:10]
                    == str(v38_today())
                ]
            )
    except Exception:
        pass

    try:
        pagamenti = v3820_load_pagamenti_safe()
        payment_date_column = (
            "data_pagamento"
            if "data_pagamento" in pagamenti.columns
            else "data" if "data" in pagamenti.columns else None
        )
        if payment_date_column and "importo" in pagamenti.columns:
            today_rows = pagamenti[
                pagamenti[payment_date_column].astype(str).str[:10]
                == str(v38_today())
            ]
            incassi_oggi = sum(
                v3809_importo_pagamento(row.to_dict())
                for _, row in today_rows.iterrows()
            )
    except Exception:
        pass

    st.markdown(
        """
        <style>
        div[data-testid="stButton"] > button[kind="secondary"] {
            min-height:92px;
            border-radius:16px;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    k1, k2, k3, k4 = st.columns(4)

    with k1:
        if st.button(
            f"👥 Clienti\n\n{total_clienti}",
            key="v3824_clients_kpi",
            use_container_width=True,
        ):
            st.session_state["reception_internal_view"] = "clienti_overview"
            st.rerun()

    with k2:
        st.markdown(
            v3824_kpi_card("Agenda oggi", agenda_count, "🗓️"),
            unsafe_allow_html=True,
        )

    with k3:
        st.markdown(
            v3824_kpi_card("Accessi oggi", accessi_count, "🚦"),
            unsafe_allow_html=True,
        )

    with k4:
        st.markdown(
            v3824_kpi_card("Incassi oggi", v38_euro(incassi_oggi), "💰"),
            unsafe_allow_html=True,
        )

    st.markdown("---")

    left, right = st.columns([3.6, 1.15], gap="large")

