def v3820_get_scadenza_abbonamento_cliente(cliente):
    if cliente is None:
        return ""

    start_date = v3825_best_start_date(cliente)
    subscription_type = v3825_subscription_type(cliente)
    expected = v3823_expected_date(start_date, subscription_type)
    saved = v3825_saved_subscription_expiry(cliente)

    # manuale/salvata coerente
    if saved is not None and expected is not None:
        if v3823_dates_are_coherent(saved, expected):
            return v3822_format_ts(saved)
        return v3822_format_ts(expected)

    if expected is not None:
        return v3822_format_ts(expected)

    if saved is not None:
        return v3822_format_ts(saved)

    return ""


def v3820_get_scadenza_rata_cliente(cliente):
    if cliente is None:
        return ""

    row = v3825_row_dict(cliente)

    payment_type = v3825_payment_type(row)
    payment_type_upper = str(payment_type or "").strip().upper()

    # unica soluzione: la rata coincide sempre con fine abbonamento
    if "UNICA" in payment_type_upper:
        return v3820_get_scadenza_abbonamento_cliente(row)

    saved = v3825_saved_payment_expiry(row)
    start_date = v3825_payment_start_date(row)
    expected = v3823_expected_date(start_date, payment_type)

    if saved is not None and expected is not None:
        if v3823_dates_are_coherent(saved, expected):
            return v3822_format_ts(saved)
        return v3822_format_ts(expected)

    if expected is not None:
        return v3822_format_ts(expected)

    if saved is not None:
        return v3822_format_ts(saved)

    # fallback finale: se esiste un abbonamento ma non una frequenza rata,
    # la prossima data utile coincide con la fine abbonamento.
    return v3820_get_scadenza_abbonamento_cliente(row)


def v3825_clienti_overview_df():
    clienti = v3820_load_clienti_direct_safe()
    docs = v3820_load_docs_safe()
    pagamenti = v3820_load_pagamenti_safe()
    rows = []

    if clienti is None or clienti.empty:
        return pd.DataFrame()

    for _, cliente in clienti.iterrows():
        cliente_id = cliente.get("id")

        try:
            active = v3808_is_cliente_attivo(cliente)
        except Exception:
            stato_raw = str(
                cliente.get("stato")
                or cliente.get("stato_cliente")
                or "ATTIVO"
            ).upper()
            active = stato_raw not in {"DISATTIVATO", "INATTIVO", "ARCHIVIATO"}

        stato = "🟢 Attivo" if active else "⚪ Disattivato"

        try:
            lezioni_totali, lezioni_usate, lezioni_residue = v38_contatori_cliente(cliente)
        except Exception:
            lezioni_totali, lezioni_usate, lezioni_residue = 0, 0, 0

        try:
            importo_contratto = float(
                v3810_get_raw_cliente_importo(cliente.to_dict()) or 0
            )
        except Exception:
            try:
                importo_contratto = float(cliente.get("importo") or 0)
            except Exception:
                importo_contratto = 0.0

        pagato, numero_pagamenti = v3820_pagamenti_sum_safe(
            pagamenti,
            cliente_id,
        )
        residuo = max(importo_contratto - float(pagato or 0), 0.0)

        numero_documenti, tipi_documenti, _ = v3820_docs_info_safe(
            docs,
            cliente_id,
        )

        documenti_cliente = pd.DataFrame()
        if docs is not None and not docs.empty and cliente_id is not None:
            try:
                if "v3815_doc_cliente_id" in globals():
                    document_ids = pd.to_numeric(
                        docs.apply(v3815_doc_cliente_id, axis=1),
                        errors="coerce",
                    )
                    documenti_cliente = docs[
                        document_ids == int(float(cliente_id))
                    ]
            except Exception:
                documenti_cliente = pd.DataFrame()

        stato_certificato, scadenza_certificato = v3820_cert_status_safe(
            cliente,
            documenti_cliente,
        )

        scadenza_abbonamento = v3820_get_scadenza_abbonamento_cliente(cliente)
        scadenza_rata = v3820_get_scadenza_rata_cliente(cliente)

        # Se saldato, rata = fine abbonamento.
        if v3824_is_fully_paid(importo_contratto, pagato):
            scadenza_rata = scadenza_abbonamento

        # Se residuo > 0, rata non deve restare vuota.
        # Ultimo fallback: fine abbonamento.
        if residuo > 0 and not scadenza_rata:
            scadenza_rata = scadenza_abbonamento

        rows.append({
            "ID": cliente_id,
            "Cliente": v38_cliente_nome(cliente),
            "Stato": stato,
            "Telefono": cliente.get("cellulare") or cliente.get("telefono") or "-",
            "Email": cliente.get("email") or "-",
            "Pacchetto": v3824_normalize_package(cliente.get("pacchetto")),
            "Abbonamento": (
                cliente.get("tipo_abbonamento")
                or cliente.get("tipologia_abbonamento")
                or "-"
            ),
            "Prossima rata": scadenza_rata or "-",
            "Scadenza abbonamento": scadenza_abbonamento or "-",
            "Lezioni": f"{int(lezioni_residue)}/{int(lezioni_totali)}",
            "Contratto": v3824_money(importo_contratto),
            "Pagato": v3824_money(pagato),
            "Residuo": v3824_money(residuo),
            "Pagamenti": int(numero_pagamenti),
            "Documenti": int(numero_documenti),
            "Certificato": stato_certificato or "-",
            "Scadenza certificato": (
                scadenza_certificato.strftime("%d/%m/%Y")
                if scadenza_certificato
                else "-"
            ),
            "Tipi documenti": tipi_documenti or "-",
            "Note": cliente.get("note") or "",
            "_attivo": active,
            "_residuo_num": residuo,
        })

    return pd.DataFrame(rows)


